(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.7"]={"from":168,"a":[["\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב ששת\u0004 את הברייתא שהגונב אדם ומוכרו לאבי הנגנב חייב. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אני שונה\u0004 כי \u0003ר' שמעון אומר:\u0004 גונב נפש \u0003\"מאחיו\",\u0004 כוונתו: \u0003עד שיוציאנו מרשות אחיו,\u0004 וכל עוד הוא ברשותם — פטור. \u0003ואת אמרת\u0004 \u0005[ואתה אמרת]\u0006 שהמוכרו לאביו \u0003חייב?! תני\u0004 \u0005[שנה]\u0006 במקום זה: \u0003פטור.\u0004","ותוהים: \u0003מאי קושיא\u0004 \u0005[מה הקושיה]\u0006 שמצא רב ששת בכך? \u0003דילמא הא\u0004 \u0005[שמא זו]\u0006 שאמרנו עד שיוציאנו מרשות אחיו כשיטת \u0003ר' שמעון\u0004 היא. \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האומרת שאף אם מוכרו למשפחתו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא?!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, משום שאותה ברייתא היא קטע ממדרש ההלכה לספר דברים, הנקרא \"ספרי\", ש\u0003אמר ר' יוחנן: סתם מתניתין\u0004 \u0005[משנתנו]\u0006 אם לא נאמר בה שם החכם האומרה יש לשער שהיא כשיטת \u0003ר' מאיר, סתם תוספתא ר' נחמיה, סתם ספרא\u0004 (מדרש ההלכה לספר ויקרא) כשיטת \u0003ר' יהודה, סתם ספרי\u0004 (מדרש הלכה לספרי במדבר ודברים) כשיטת \u0003ר' שמעון, וכולהו אליבא\u0004 \u0005[וכולם על פי שיטתו]\u0006 של \u0003ר' עקיבא\u0004 שכל אלה היו תלמידיו. ואם כן אין לשער שמדרש הלכה סתם בספרי יהא מנוגד לדעת ר' שמעון.","שנינו במשנה מחלוקת ביחס ל\u0003הגונב בנו,\u0004 שנחלקו בכך חכמים ור' יהודה. ושואלים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]\u0006 הפוטרים בגונב את בנו?","\u0003אמר אביי,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי ימצא\u0004 איש גונב נפש מאחיו\u0003\"\u0004 (דברים כד, ז), כוונתו: \u0003פרט למצוי\u0004 כבר בידו, וכיון והבן מצוי כבר ביד האב פטור הוא מגניבתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אלא מעתה\u0004 לפי אותה דרך פירוש נאמר שהכתוב \u0003\"כי ימצא איש שכב עם אשה בעלת בעל\u0004 ומתו גם שניהם\u0003\"\u0004 (שם כב, כב), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר: \u0003\"כי ימצא\"\u0004 — \u0003פרט למצוי!\u0004 ואם כן \u0003כגון של בית פלוני\u0004 של משפחה ידועה \u0003דשכיחן גבייהו\u0004 \u0005[שמצויות אצלם]\u0006 נשים נשואות, שלא היו נזהרים בצניעות והיו נשים נשואות לאחרים מצויות בבתים אלה, \u0003הכי נמי דפטירי\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הם \u0005פטורים]\u0006 אם ינאפו?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אנא\u0004 \u0005[אני]\u0006 שהבאתי ראיה לחכמים — מן הכתוב \u0003\"\u0004וגונב איש ומכרו \u0003ונמצא בידו\"\u0004 (שמות כא, טז) \u0003קאמינא\u0004 \u0005[אמרתי],\u0006 ומשם למדתי שדנים למוות רק מי שנמצא הגנוב רק בפעם זו בידו, יצא זה שהגנוב נמצא תמיד בידו.","\u0003אמר רבא: הלכך\u0004 \u0005[על כן]\u0006 \u0003הני מיקרי דרדקי ומתנו רבנן\u0004 \u0005[אותם מלמדי המקרא לתינוקות, והשונים משנה לתלמידי חכמים]\u0006 אותם תלמידים \u0003כמצויין בידן\u0004 של רבותיהם \u0003דמו\u0004 \u0005[נחשבים],\u0006 \u0003ופטירי\u0004 \u0005[ופטורים]\u0006 ממיתה אם גנבום.","שנינו במשנה שמי ש\u0003גנב מי שחציו\u0004 עבד וחציו בן חורין, ר' יהודה מחייב וחכמים פוטרים. \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה אחרת\u0005],\u0006 \u0003ר' יהודה אומר: אין לעבדים בושת,\u0004 ומי שבייש עבד אינו חייב בתשלומי בושת, שאינו בכלל ישראל להתחייב עליו על מה שביישו.","ושאלו שם: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 והסבירו, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי ינצו אנשים יחדו איש ואחיו\u0004 וקרבה אשת האחד להציל את אישה מיד מכהו ושלחה ידה והחזיקה במבושיו\u0003\"\u0004 (דברים כה, יא), שמשם למדנו תשלום קנס למבייש חבירו. והרי שם נאמר \"אחיו\", לומר: דין זה הוא רק לגבי \u0003מי שיש לו אחוה,\u0004 שיש לו קשרי משפחה מוכרים בהלכה, \u0003יצא עבד שאין לו אחוה\u0004 שאין קשר חוקי בינו ובין משפחתו.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים שאף עבד יש לו בושת, והם סבורים שאף הוא קרוי \"אחיו\" כי מכל מקום \u0003אחיו הוא במצות,\u0004 שהרי אף עבד כנעני חייב לקיים מקצת מצוות.","\u0003ו\u0004אילו \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003היכי דריש\u0004 \u0005[כיצד דורש]\u0006 \u0003ר' יהודה,\u0004 שהרי לכאורה הפוכה סברתו כאן, שהרי בגונב חציו עבד וחציו בן חורין מחייב ר' יהודה, והרי שלדעתו נחשב הוא כ\"אחיו\"?","ומשיבים: \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005],\u0006 נאמר כאן \u0003\"מאחיו\"\u0004 (דברים כד, ז) — הרי זה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003עבדים,\u0004 שלדעת ר' יהודה אינם בכלל \"אחיו\", אם כן מה שנאמר \u0003\"בני ישראל\"\u0004 (דברים כד, ז) — הרי זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מי שחציו עבד וחציו בן חורין\u0004 שאינו ישראל. ונאמר \u0003\"מבני ישראל\"\u0004 — במ' המתפרשת כ־מ' של מיעוט, כלומר, מחלק של בני ישראל, וגם זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מי שחציו עבד וחציו בן חורין,\u0004 \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003מיעוט אחר מיעוט, ו\u0004כלל הוא: \u0003אין מיעוט\u0004 הבא \u0003אחר מיעוט אלא לרבות,\u0004 הרי שיש ריבוי לדעת ר' יהודה, ומי שחציו עבד וחציו בן חורין נתרבה בכלל זה.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הדרשה \u0003\"מאחיו\" לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003עבדים לא משמע להו\u0004 \u0005[אינה נשמעת,\u0006 מסתברת, \u0005להם],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אחיו הוא במצות\u0004 ועדיין לא למדנו למעט עבד מדין גניבת אדם. ולכן המיעוט הכפול \u0003\"בני ישראל\" \"מבני ישראל\"\u0004 אינו מיעוט אחר מיעוט באותו ענין, אלא שני מיעוטים שונים הם: \u0003חד\u0004 \u0005[אחד]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003עבד\u0004 מדין גניבת אדם, שהרי ודאי שאינו בן ישראל, \u0003וחד למעוטי\u0004 \u0005[ואחד למעט]\u0006 אף \u0003מי שחציו עבד וחציו בן חורין.\u0004","ושואלים: \u0003אזהרה,\u0004 מקום שנזכר בו האיסור, \u0003לגונב נפש מנין? ר' יאשיה אמר: מ\"לא תגנב\"\u0004 שבעשרת הדברות (שמות כ, טו). \u0003ר' יוחנן אמר: מ\"לא ימכרו ממכרת עבד\"\u0004 (ויקרא כה, מב). ומעירים: \u0003ולא פליגי\u0004 \u0005[נחלקו]\u0006 אלא הדעות מצטרפות יחד; \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יאשיה\u0005]\u0006 \u0003קא חשיב\u0004 \u0005[מונה]\u0006 את ה\u0003לאו\u0004 (מצות \"לא תעשה\") שיש ב\u0003גניבה, ומר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן\u0005]\u0006 \u0003קא חשיב\u0004 \u0005[מונה]\u0006 את ה\u0003לאו\u0004 שיש ב\u0003מכירה\u0004 של אדם גנוב מישראל לעבדות.","דרך אחרת מוצאים בבריתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"לא תגנב\"\u0004 (שמות ב, טו) — \u0003בגונב נפשות הכתוב מדבר. אתה אומר בגונב נפשות, או אינו אלא בגונב ממון? אמרת: צא ולמד משלש עשרה מדות שהתורה נדרשת בהן,\u0004 שאחת מהן היא \u0003דבר הלמד מעניינו,\u0004 כלומר, למדים מן ההקשר, \u0003במה הכתוב מדבר\u0004 בפסוקים הסמוכים \"לא תרצח\" וכיוצא בהן — \u0003ב\u0004עבירות שיש בהן דיני \u0003נפשות, אף כאן בנפשות.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 מה שנאמר \u0003\"לא תגנבו\u0004 ולא תכחשו ולא תשקרו איש בעמיתו\u0003\"\u0004 (ויקרא יט, יא) — \u0003בגונב ממון הכתוב מדבר. אתה אומר בגונב ממון, או אינו אלא בגונב נפשות? אמרת: צא ולמד משלש עשרה מדות שהתורה נדרשת בהן,\u0004 שאחת מהן היא \u0003דבר הלמד מענינו. במה הכתוב מדבר\u0004 בפסוק זה? — בעבירות ש\u0003בממון, אף כאן בממון.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: היו \u0003עידי גניבה\u0004 לחוד שהעידו שגנב אדם, \u0003ועידי מכירה\u0004 לחוד, שהעידו על מכירתו, \u0003בנפש\u0004 (כלומר, לענין גניבת נפש, כאמור) \u0003שהוזמו\u0004 ונמצאו שקרנים. \u0003חזקיה אמר: אין נהרגין\u0004 בדין עדים זוממים. \u0003ר' יוחנן אמר: נהרגין.\u0004","ומסבירים: \u0003חזקיה\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 ככלל שהעדים יכולים להעיד על \u0003\"דבר\"\u0004 (כאמור: \"על פי שני עדים או שלושה עדים יקום דבר\". דברים יט, טו) \u0003ולא חצי דבר\u0004 וכיון שהעידה כל קבוצת עדים רק על חצי מעשה, על גניבה בלבד, או על מכירה בלבד, הרי זה נחשב כעדות על חצי דבר. \u0003ור' יוחנן אמר: כרבנן\u0004 \u0003דאמרי\u0004 \u0005[כ\u0006שיטת \u0005חכמים שאומרים]\u0006 שהעדים מעידים על \u0003\"דבר\",\u0004 \u0003ואפילו\u0004 על \u0003חצי דבר,\u0004 שאם העדויות שכאן מצטרפות הרי זו עדות שלימה, ולכן אם הוזמו — ייהרגו.","ומעירים: \u0003ומודה חזקיה בעדים האחרונים של בן סורר ומורה\u0004 שראוהו זולל וסובא לאחר שכבר העידו בו עדים קודמים שגנב וזלל וסבא ולקה בעדות ראשונה, \u0003ש\u0004אם \u0003הוזמו שנהרגין.\u0004 שעדות אחרונה זו היא עדות נבדלת שנועדה רק להמתת הנאשם, \u0003מתוך שיכולים לומר\u0004 העדים \u0003הראשונים:\u0004"],["\u0003\"\u0004רק \u0003להלקותו באנו\",\u0004 כלומר, להעיד עליו עדות מיוחדת כדי להענישו על מה שגנב, ואין עדותם מכוונת לענין חיוב כבן סורר כלל. \u0003ו\u0004לכן \u0003הני אחריני\u0004 \u0005[אלה\u0006 העדים \u0005האחרים,\u0006 האחרונים\u0005]\u0006 — \u0003כולי\u0004 \u0005[\u0006את \u0005כל]\u0006 ה\u0003דבר קא עבדי ליה\u0004 \u0005[עשו לו],\u0006 ואם הוזמו חייבים מיתה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מבין בשיטת חזקיה, אם כן \u0003עידי מכירה\u0004 של אדם \u0003נמי ליקטליה\u0004 \u0005[גם כן שיהרגום],\u0006 \u0003מתוך שיכולין עידי גניבה לומר: \"\u0004רק \u0003להלקותו באנו\",\u0004 שבאו להעיד רק שגנב נפש על מנת שילקה על כך, ולא כתחילת עדות להרגו על גניבה ומכירה. \u0003וכי תימא דקסבר\u0004 \u0005[ואם תאמר שסבור]\u0006 \u0003חזקיה\u0004 שהגונב נפש בלבד \u0003דלא לקי\u0004 \u0005[שאינו לוקה],\u0006","\u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 במחלוקת אחרת: \u0003עידי גניבה בנפש שהוזמו\u0004 לפני שהעידו עדי מכירה, \u0003חזקיה ור' יוחנן\u0004 נחלקו בכך: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לוקין\u0004 על כך, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין לוקין. ואמרינן\u0004 \u0005[ואמרנו]\u0006 בדיון באותו נושא: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 כי \u0003חזקיה\u0004 הוא ש\u0003אמר לוקין, מ\u0004כיון ש\u0003אמר חזקיה:\u0004 עדים זוממים שהעידו על כך \u0003אין נהרגין.\u0004","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003ר' יוחנן\u0004 הוא בעל דעה זו, הלא \u0003כיון\u0004 ש\u0003אמר\u0004 שעדים זוממים בנושא זה \u0003נהרגין, הוה ליה\u0004 \u0005[נעשה לו]\u0006 אותו איסור כ\u0003לאו שניתן לאזהרת מיתת בית דין,\u0004 שאם איסור \"לא תעשה\" משמש אזהרה (מקור לאיסור) לעבירה שעונשה מוות, \u0003ו\u0004הרי כלל בידינו ש\u0003כל לאו שניתן לאזהרת מיתת בית דין אין לוקין עליו,\u0004 גם אם לא חל במקרה זה עונש המוות. ואם \u0003איהו לא לקי\u0004 \u0005[הוא,\u0006 הנאשם, \u0005אינו לוקה]\u0006 על הגניבה, \u0003אינהו היכי לקו\u0004 \u0005[הם,\u0006 העדים, \u0005כיצד לוקים]\u0006 כעדים זוממים? והלא ענשם זהה לעונש המואשם על ידם! אלא ודאי סבור ר' יוחנן שעידי גניבה לדעת חזקיה לוקים, ואם כן צריכים לדון למוות את עדי המכירה לכל הדעות!","\u0003אלא אמר רב פפא:\u0004 עלינו לחזור בנו מן ההסבר הקודם, ולומר כי \u0003ב\u0004כת \u0003עידי מכירה דכולי עלמא לא פליגי\u0004 \u0005[שהכל,\u0006 גם חזקיה, \u0005אינם חלוקים]\u0006 שהם \u0003נהרגין,\u0004 שהרי עדותם היא עדות גמורה למוות, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בעידי גניבה. חזקיה אמר: אין נהרגין,\u0004 כי לדעתו \u0003גניבה לחודה קיימא\u0004 \u0005[לעצמה עומדת],\u0006 כעבירה לחוד שעונשה מלקות, \u0003ומכירה לחודה קיימא\u0004 \u0005[לעצמה עומדת]\u0006 ויש כאן איפוא שתי עדויות נפרדות. \u0003ר' יוחנן אמר: נהרגין,\u0004 כי \u0003גניבה אתחלתא\u0004 \u0005[התחלתה]\u0006 של \u0003מכירה היא,\u0004 שהמעידים על גונב אדם מעידים על עבירה שסופה מכירה והיא כעדות אחת.","ומעירים: \u0003ומודה ר' יוחנן בעדים הראשונים של בן סורר ומורה\u0004 שגנב ואכל, \u0003שהוזמו, שאין נהרגין, מתוך שיכולין לומר \"\u0004רק \u0003להלקותו באנו\"\u0004 על מה שעבר, שאין אנו מתכוונים כלל לדין בן סורר ומורה, ואין קשר בין מה שיענש אחר כך ובין העבירה הראשונה שעבר.","\u0003אמר אביי\u0004 לסכם את הדברים שאמרנו, ושיטות חדשות בלשון זו: \u0003הכל מודים בבן סורר ומורה, והכל מודים בבן סורר ומורה, ומחלוקת בבן סורר ומורה.\u0004","והסבר הדברים: \u0003הכל מודים בבן סורר ומורה,\u0004 כלומר, \u0003בעדים הראשונים, ש\u0004לדעת הכל גם לר' יוחנן \u0003אין נהרגין, מתוך שיכולין לומר \"\u0004רק \u0003להלקותו באנו\".\u0004","\u0003והכל מודים בבן סורר ומורה\u0004 — \u0003בעדים אחרונים, ש\u0004לדעת הכל, גם לחזקיה, הם \u0003נהרגים, מתוך שעדים הראשונים יכולין לומר \"\u0004רק \u0003להלקותו באנו\", והני כוליה\u0004 \u0005[ואלה,\u0006 העדים האחרונים, את \u0005כל]\u0006 ה\u0003דבר קא עבדי ליה\u0004 \u0005[הם עושים לו]\u0006 והיא עדות שלימה, ואם הוזמו — חייבים מיתה.","\u0003ומחלוקת בבן סורר ומורה,\u0004 כגון שהיו \u0003שנים\u0004 מן העדים האחרונים, לאחר שכבר לקה על שגנב ואכל פעם אחת, ש\u0003אומרים \"בפנינו גנב\", ושנים אומרים \"בפנינו אכל\",\u0004 ובכך נחלקו: האם שתי קבוצות אלה מעידות על \"דבר\" או על \"חצי דבר\".","\u0003אמר רב אסי: עדי מכירה בנפש\u0004 בלבד \u0003שהוזמו\u0004 — \u0003אין נהרגין, מתוך שיכול\u0004 הנאשם \u0003לומר:\u0004 אמנם מעידים אתם שמכרתי אדם, אבל \u0003\"עבדי מכרתי\".\u0004 נמצא שכאשר הם מעידים, אינם מעידים על עבירה שחייב עליה מיתה, שהרי אינם יכולים להוכיח שגנב את האיש הזה, ושמא עבדו הוא.","\u0003אמר רב יוסף: כמאן אזלא הא שמעתא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת הלכה זו]\u0006 של \u0003רב אסי?\u0004 — \u0003כ\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 שהעדים צריכים להעיד \u0003דבר\u0004 שלם \u0003ולא חצי דבר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 בתמיהה: לפי דבריך משמע שהלכה זו אינה יכולה להיות לפי שיטת חכמים, \u0003דאי כרבנן\u0004 \u0005[שאם\u0006 תאמר ש\u0005כ\u0006שיטת \u0005חכמים\u0006 היא\u0005],\u0006 שאינם סוברים כר' עקיבא, האם \u0003נהרגין\u0004 הם?! \u0003הא\u0004 \u0005[הרי]\u0006 נימוק של \u0003\"מתוך\" קאמר\u0004 \u0005[אמר],\u0006 \"מתוך שיכול לומר עבדי מכרתי\", ועל פי נימוק זה יפטר גם לשיטת חכמים!","\u0003אלא, אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת \u0005חכמים],\u0006 \u0003ו\u0004אולם יש לומר שמדובר באופן ש\u0003לא אתו\u0004 \u0005[באו]\u0006 \u0003עידי גניבה,\u0004 ויש עידי מכירה בלבד, שיכול הנאשם להיפטר, ולכן עדי השקר לא יומתו כשהוזמו. ותוהים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה יש לומר]?\u0006 הרי באמת אין הוכחה שהאיש שנמכר היה מישראל, ואינו עבד! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר דבר זה למקרה שהיו רק עידי מכירה, אלא \u0003דאף על גב דאתו\u0004 \u0005[שאף על פי שבאו]\u0006 \u0003לבסוף,\u0004 אחרי שהעידו העדים הראשונים, עדים שהעידו שנגנב אותו אדם.","ושואלים: \u0003ואכתי מאי למימרא\u0004 \u0005[ועדיין מה יש לומר]\u0006 בכך? הלא בזמן שהעידו עדי המכירה לא היתה זו עדות שיש בה כדי לחייב! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה שרואים \u0003דקא מרמזי רמוזי\u0004 \u0005[שרומזים רמזים\u0006 זה לזה\u0005]\u0006 עדים ראשונים ואחרונים, ולכאורה מובן שהם מכירים זה את זה ויודעים עדי המכירה שאחריהם יבואו עדי גניבה, והם חלק מעדות שקר שכוונתה להביא למותו של אדם, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003רמיזא מילתא היא\u0004 \u0005[רמיזה דבר הוא],\u0006 ולכן שתי העדויות ייחשבו כיחידה אחת. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003רמיזא לאו\u0004 \u0005[רמיזה\u0006 לא] \u0003כלום הוא,\u0004 וכל עוד לא באו והעידו יחד, אין זו נחשבת כעדות אחת, ועדות מכירה בלבד אינה נחשבת.","\u0003זקן ממרא על פי בית דין\u0004 שאינו מציית להוראות בית הדין של ישראל נידון למוות בחנק. \u0003שנאמר: \"כי יפלא ממך דבר למשפט...\u0004 וקמת ועלית אל המקום אשר יבחר ה' אלהיך בו... ועשית על פי הדבר אשר יגידו לך... והאיש אשר יעשה בזדון לבלתי שמוע... ומת האיש ההוא\u0003\"\u0004 (דברים יז, ח–יב). וכך נוהגים בענין זה: \u0003שלשה בתי דינין היו שם\u0004 בירושלים, \u0003אחד יושב על פתח הר הבית, ואחד יושב\u0004 לפנים ממנו \u0003על פתח העזרה, ואחד יושב בלשכת הגזית.\u0004","\u0003באין לזה שעל פתח הר הבית, ואומר\u0004 הזקן החכם שהורה הלכה שאינה מקובלת על חבריו: \u0003כך דרשתי\u0004 מן התורה \u0003וכך דרשו חבירי, כך לימדתי וכך לימדו חבירי\u0004 בהלכה ולא הגענו להסכמה בדבר. \u0003אם שמעו\u0004 חכמי בית דין זה הלכה פסוקה בנושא זה — \u0003אמר להם,\u0004","\u0003ואם לאו\u0004 \u0005[לא],\u0006 שלא שמעו — \u0003באין להן\u0004 החכמים והזקן \u0003לאותן שעל פתח עזרה\u0004 שהוא בית דין חשוב יותר, \u0003ואומר\u0004 הזקן: \u0003כך דרשתי וכך דרשו חבירי, כך לימדתי וכך לימדו חבירי, אם שמעו\u0004 — \u0003אמר להם,\u0004","\u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אלו ואלו באין לבית דין הגדול\u0004 סנהדרי של שבעים ואחד \u0003שבלשכת הגזית, שממנו יוצא תורה לכל ישראל, שנאמר:\u0004 \"ועשית על פי הדבר אשר יגידו לך \u0003מן המקום ההוא אשר יבחר ה'\u0004 ושמרת לעשות ככל אשר יורוך\" (שם י), והם אשר מסכמים וקובעים פסק הלכה מחייב. אם פסקו כנגד דבריו של אותו זקן, ו\u0003חזר\u0004 הזקן \u0003לעירו,\u0004 ובכל זאת \u0003שנה ולמד ב\u0004אותה \u0003דרך שהיה למד\u0004 בה מקודם לכן — \u0003פטור,\u0004 אולם \u0003אם הורה\u0004 לאחרים \u0003לעשות\u0004 כשיטתו שלא כדין סנהדרין — הרי זה \u0003חייב\u0004 מיתה, \u0003שנאמר: \"והאיש אשר יעשה בזדון...\"\u0004(שם יב), וכוונתו: \u0003אינו חייב עד שיורה לעשות.\u0004","ועוד אמרו: \u0003תלמיד\u0004 שעדיין לא הגיע לדרגת חכם, שלא נסמך, \u0003שהורה לעשות\u0004 כנגד הוראת בית דין הגדול — \u0003פטור,\u0004 לפי שהוראתו אינה קרויה הוראה. ואם כן \u0003נמצא חומרו קולו\u0004 שהחומרה שהחמירו עליו שלא יורה, גורמת לו הקלה שלא ידון למוות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"כי יפלא ממך דבר\"\u0004 (שם ח),"],["\u0003ב\u0004ענין \u0003מופלא שבבית דין,\u0004 כלומר, באדם המומחה וסמוך להיות דיין, \u0003הכתוב מדבר. \"ממך\"\u0004 — \u0003זה יועץ\u0004 הראוי לתת עצה בדינים חמורים כגון בעיבור השנה, \u0003ו\u0004כהוכחה ש\"ממך\" קשור ביועץ, ש\u0003כן הוא אומר: \"ממך יצא חשב על ה' רעה יעץ בליעל\"\u0004 (נחום א, יא). \u0003\"דבר\"\u0004 — \u0003זו הלכה\u0004 למשה מסיני. \u0003\"למשפט\"\u0004 — \u0003זה הדין,\u0004 שהוא אחת מדרכי הלימוד במדות שהתורה נדרשת בהם.","\u0003\"בין דם לדם\"\u0004 — להבחין בין סוגים שונים של דם: \u0003בין דם נדה\u0004 ל\u0003דם לידה\u0004 ו\u0003דם זיבה,\u0004 שבכל אחד הלכות מיוחדות בתורה. \u0003\"בין דין לדין\"\u0004 — להבחין \u0003בין דיני נפשות,\u0004 ל\u0003דיני ממונות,\u0004 שיש ביניהם הבדלים בחוקי הראיות ועוד, ובין \u0003דיני מכות. \"בין נגע לנגע\"\u0004 — \u0003בין נגעי\u0004 צרעת \u0003אדם\u0004 ל\u0003נגעי\u0004 צרעת \u0003בתים,\u0004 ו\u0003נגעי\u0004 צרעת \u0003בגדים,\u0004 שדיניהם שונים במקצת (ויקרא פרק יד).","\u0003\"דברי\"\u0004 — \u0003אלו החרמים,\u0004 שאומר שדבר יהא \"חרם לה' \" או \"לכהן\", \u0003והערכין\u0004 שמעריכים ערכו או ערך חבירו למקדש, \u0003וההקדשות\u0004 שכולם תלויים בדיבור כשמקדיש את הדברים. \u0003\"ריבת\"\u0004 — \u0003זו השקאת סוטה\u0004 במים המאררים (במדבר פרק ה), שהיא תלויה בריב בין איש ואשתו, \u0003ועריפת עגלה\u0004 שתלויה בריב שנגמר ברצח (דברים כא, א–ט), \u0003וטהרת מצורע\u0004 שמקובל שנענש בצרעת משום שדיבר לשון הרע. \u0003\"בשעריך\"\u0004 (דברים יז, ח) — \u0003זו\u0004 מתנות \u0003לקט שכחה ופאה\u0004 הניתנות לעניים שנאמר בהם שהם אוכלים בשערי העיר.","\u0003\"וקמת\"\u0004 (דברים יז, ח) משמעו — \u0003מבית דין\u0004 שיושב ודן בנושא זה. \u0003\"ועלית\"\u0004 (דברים יז, ח) — \u0003מלמד שבית המקדש\u0004 שאליו הולכים \u0003גבוה מארץ ישראל, וארץ ישראל גבוה מכל הארצות,\u0004 שלכן נופלת לשון \"עליה\" על הליכה למקדש ולארץ מכל מקום אחר בעולם. \u0003\"אל המקום\u0004 אשר יבחר ה' אלהיך בו\u0003\"\u0004 (דברים יז, ח) — \u0003מלמד שהמקום גורם\u0004 ונותן תוקף לפסקי ההלכה, שדווקא במקום בו בחר ה' למושב סנהדרין, הרי החולק עליהם שם — הוא זקן ממרא.","אגב הזכרת הדברים שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003בית המקדש\u0004 ש\u0003גבוה מארץ ישראל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועלית\", אלא\u0004 ש\u0003ארץ ישראל גבוה מכל הארצות מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לכן הנה ימים באים נאם ה' לא יאמר\u0004 עוד \u0003חי ה' אשר העלה את בני ישראל מארץ מצרים. כי אם חי ה' אשר העלה ואשר הביא את זרע בית ישראל מארץ צפנה ומכל הארצות אשר הדחתים שם וישבו על אדמתם\"\u0004 (ירמיה כג, ז), הרי שלשון \"עליה\" משמשת לשיבה לארץ ישראל מכל ארצות שבעולם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003זקן ממרא אינו חייב אלא\u0004 כשהורה \u0003על דבר שזדונו\u0004 (עשייתו בזדון) מחייבת \u0003כרת, ושגגתו\u0004 (עשייתו בשגגה) מחייבת \u0003חטאת,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אינו חייב אלא \u0003על דבר שעיקרו מדברי תורה ופירושו מדברי סופרים,\u0004 אבל אם לא נכתב עיקרו בתורה, או שכולו מפורש בתורה עצמה — אינו בכלל זקן ממרא. \u0003ר' שמעון אומר: אפילו\u0004 חלק אותו זקן על \u0003דקדוק אחד מדקדוקי סופרים\u0004 בפירוש התורה, הרי זה ממרא, בלי קשר לחומרת העבירה.","ומבארים את השיטות, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר?\u0004 — \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה של המילים \u0003\"דבר\" \"דבר\"; כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"כי יפלא ממך דבר למשפט\"\u0004 (דברים יז, ח), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ונעלם דבר מעיני הקהל\"\u0004 (ויקרא ד, יג). \u0003מה להלן\u0004 בענין חטאת הקהל אין מביאים חטאת זו אלא על \u0003דבר שחייב על זדונו כרת ועל שגגתו חטאת, אף כאן\u0004 ב\"יפלא דבר\" הכוונה ל\u0003דבר שחייב\u0004 \u0003על זדונו כרת ועל שגגתו חטאת.\u0004","\u0003ור' יהודה\u0004 מה טעמו? — שנאמר בזקן ממרא \u0003\"על פי התורה אשר יורוך\"\u0004 (דברים יז, יא), ללמד: \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 באותו ענין עצמו גם \u0003\"תורה\"\u0004 כתובה \u0003ו\u0004גם \u0003\"יורוך\",\u0004 דברי חכמים והוראתם המפרשים את הנאמר בתורה.","\u0003ור' שמעון:\u0004 הוא סומך על הכתוב \u0003\"אשר יגידו לך מן המקום ההוא\"\u0004 (שם י), ללמד: \u0003אפילו כל דהו\u0004 \u0005[שהוא],\u0006 שכל הלכה של חכמי לשכת הגזית מחייבת, והחולק עליה הריהו זקן ממרא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר חיננא לרבא: תרגמא\u0004 \u0005[הסבר]\u0006 \u0003לי להא מתניתא\u0004 \u0005[ברייתא זו]\u0006 שפרשנו את הפסוק כולו לדינים שונים \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' מאיר,\u0004 כלומר, הסבר כיצד כל ההבדלים ההלכתיים הללו קשורים להוראתו של זקן ממרא בענין שזדונו כרת ושגגתו חטאת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב פפא\u0004 תלמידו: \u0003פוק תרגמא ליה\u0004 \u0005[לך והסבר לו אותה].\u0006","אמר לו: \u0003\"כי יפלא\"\u0004 — \u0003במופלא שבבית דין הכתוב מדבר. \"ממך\"\u0004 — \u0003זה יועץ, שיודע לעבר שנים ולקבוע חדשים\u0004 הקרויים \"סוד\" ו\"עצה\", וכיצד יש בכך דבר שזדונו כרת. ומביאים דוגמא למחלוקת קיימת בתחום זה, \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה \u0005]:\u0006 \u0003הן\u0004 (ר' יהושע ור' פפייס שנזכרו באותו מקור קודם לכן) \u0003העידו שמעברים את השנה כל אדר,\u0004 בעוד \u0003ש\u0004חכמים \u0003היו\u0004 רגילים להיות \u0003אומרים: עד הפורים\u0004 בלבד מעברים.","ומעתה אם החזיק זקן ממרא בשיטה אחרת בניגוד לדעת כל החכמים שבלשכת הגזית, \u0003דאי להאי גיסא\u0004 \u0005[שאם לצד זה]\u0006 הוא טוען בניגוד לדעת חכמים, הרי הם קובעים זמן הפסח בחודש אחר ונמצא \u0003קא שרי\u0004 \u0005[\u0006ש\u0005הוא מתיר]\u0006 \u0003חמץ בפסח, ואי להאי גיסא\u0004 \u0005[ואם\u0006 חולק \u0005לצד זה],\u0006 וכגון שקבעו שלא לעבר השנה, \u0003קא שרי\u0004 \u0005[הוא מתיר]\u0006 \u0003חמץ בפסח\u0004 בחודש אחר, ובכך הורה על דבר שזדונו כרת ושגגתו חטאת.","\u0003\"דבר\"\u0004 — \u0003זה הלכה\u0004 למשה מסיני, \u0003זו הלכות אחד עשר\u0004 יום שבנדה. שהלכה היא, שהזמן הקצר ביותר של ימים שהם לא זמן נדה בין תקופה אחת של תחלת הווסת לתקופה שניה, הוא אחד עשר יום. ואם ראתה אשה דם שלושה ימים רצופים בתוך אחד עשר יום אלה, דינה כזבה וחייבת לשבת שבעה ימים נקיים, וכל דיני זיבה עליה. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו ברואה ביום \u0003עשירי\u0004 מסוף שבעת ימי נדתה. \u0003ר' יוחנן אמר:\u0004 היום \u0003ה\u0004\u0003עשירי\u0004 דינו \u0003כתשיעי\u0004 וככל ראיית דם בתוך אחד עשר יום שצריכה לשמור עצמה ולבדוק טהרתה למחר, \u0003ור' שמעון בן לקיש אמר:\u0004 היום ה\u0003עשירי\u0004 דינו כבר \u0003כ\u0004יום ה\u0003אחד עשר,\u0004 כיון שאין כאן מקום לשלושה ימים של זיבת דם שיהיו בתוך אחד עשר יום שהם \"בלא עת נדתה\", ומבארים את השיטות:","\u0003ר' יוחנן אמר\u0004 ש\u0003עשירי\u0004 דינו \u0003כתשיעי, מה תשיעי בעי\u0004 \u0005[צריך]\u0006 \u0003שימור,\u0004 כלומר, לבדוק אם יהא אחריו יום אחד נקי מדם, כדי להפסיק את רצף ימי הטומאה שלא יחשבו לזיבה, \u0003אף עשירי בעי\u0004 \u0005[צריך]\u0006 \u0003שימור\u0004 יום אחד עשר.","ואילו \u0003ריש לקיש אמר: עשירי\u0004 דינו \u0003כאחד עשר, מה\u0004 יום \u0003אחד עשר לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003שימור, אף עשירי לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003שימור,\u0004 שכן אם תראה למחרת ביום אחד עשר וגם ביום שאחרי זה (יום שנים עשר), הרי היום האחרון של שלושה ימים רצופים הוא כבר תחילת ימי הנדה ואין כאן זיבה, ולכן ממילא אינה צריכה שימור. ואם היו סנהדרין סבורים כר' יוחנן, והיה בא על האשה ביום זה בזדון — חייב כרת כבא על הנדה.","\u0003\"משפט\"\u0004 — \u0003זה הדין\u0004 כלומר, לימוד לפי המדות שהתורה נדרשת בהן"],["כגון \u0003דין\u0004 הבא על \u0003בתו מאנוסתו\u0004 שלא נתפרש בתורה ולמדנוהו.","וכפי ש\u0003אמר רבא, אמר לי רב יצחק בר אבודימי: אתיא\u0004 \u0005[באה,\u0006 נלמדה\u0005]\u0006 הלכה זו מגזירה שווה מן המילים \u0003\"הנה\" \"הנה\"\u0004 האמורות גם באשה ובתה וגם באיסור בת בתו ובת בנו,","\u0003אתיא\u0004 \u0005[באה]\u0006 מגזירה שווה של \u0003\"זמה\" \"זמה\"\u0004 האמורות שם, לענין עונש שריפה.","\u0003\"בין דם לדם\"\u0004 — נדרש: \u0003בין דם נדה, דם לידה, דם זיבה.\u0004 ובכל פרט יש מחלוקת חכמים בדבר שיש בזדונו כרת. \u0003דם נדה\u0004 כיצד? כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 שבין \u0003עקביא בן מהללאל ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003דם\u0004 שיצא מן האשה והיה צבעו \u0003ירוק\u0004 נחלקו בו האם קרוי הוא דם לענין נדה? ש\u0003עקביא בן מהללאל מטמא וחכמים מטהרין,\u0004 והבא על הנדה חייב כרת.","\u0003דם לידה\u0004 — \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רב ולוי. דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בדבר, \u0003רב אמר:\u0004 הדם היוצא מן האשה לאחר לידה וכן דם זיבה \u0003מעין אחד הוא\u0004 וממקור אחד יוצאים, אלא \u0003התורה טמאתו\u0004 מיד לאחר הלידה, \u0003והתורה טיהרתו\u0004 שבועיים לאחר הלידה. ולכן גם אם האשה ממשיכה לזוב דם אחר שבועיים ללידתה אומרים אנו שדם זה דם טוהר הוא ואינה מטמאה.","\u0003ולוי אמר: שני מעיינות הן, נסתם הטמא\u0004 לאחר שבועיים, ואז \u0003נפתח הטהור, נסתם הטהור נפתח הטמא.\u0004 ולכן אם לא הפסיקה שתיתת הדם לאחר שבועיים אפילו זמן קצר, מן הסתם ממשיך לנבוע הדם הטמא, והבא על אשה זו לדעת לוי חייב כרת.","\u0003דם זיבה\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר ור' יהושע. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003קישתה\u0004 (היתה מקשה ללדת) וזב ממנה דם, כדרך היולדות, \u0003שלשה ימים בתוך אחד עשר יום\u0004 שהם הזמן שנקצב בהלכה כזמן שבין נדה לנדה (ולכן הרואה בהם דם — דם זיבה הוא, שהרי הוא \"בלא עת נדתה\"), \u0003אם שפתה מעת לעת,\u0004 שנחה מקישויה ופסק הדם ליממה אחת, \u0003וילדה\u0004 לאחר מכן — \u0003הרי זו\u0004 נידונה כ\u0003יולדת בזוב,\u0004 וחייבת להביא נוסף לקרבן יולדת גם קרבן כזבה, אלו \u0003דברי ר' אליעזר.\u0004","\u0003ור' יהושע אומר:\u0004 דין יולדת ששפתה הוא אם שפתה דווקא \u0003לילה ויום, כלילי שבת ויומו\u0004 בסדר זה דווקא, ולא כל מעת לעת. ועוד: \u0003\"ששפתה\",\u0004 כוונתו — שנחה \u0003מן הצער\u0004 שפסקו כאביה, \u0003ולא\u0004 ששפתה \u0003מן הדם.\u0004 הרי מחלוקת בדין דם זיבה, והשאלה אם היא קרויה יולדת בזוב, היא שאלה שיש בה צד כרת.","ועוד נדרש שם \u0003\"בין דין לדין\"\u0004 — \u0003בין דיני ממונות, דיני נפשות, דיני מכות.\u0004 ומסבירים: \u0003דיני ממונות\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 שבין \u0003שמואל ור' אבהו,\u0004 ש\u0003אמר\u0004 \u0003שמואל: שנים שדנו\u0004 דיני ממונות \u0003דיניהם דין, אלא שנקראין בית דין חצוף. ור' אבהו אמר: לדברי הכל אין דיניהן דין.\u0004 ולפיכך אם ידונו שנים בסכסוך ויחליטו שיש לתת ממון לאחד המתדיינים, ואותו אדם יקח כסף זה ויקדש בו אשה, לדעת שמואל הכסף שלו והאשה מתקדשת בו, ולדעת ר' אבהו הממון אינו שלו וקידושיו אינם קידושין. הרי מכאן מסקנה שיש בה צד חיוב כרת.","ב\u0003דיני נפשות\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רבי ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 על הכתוב \"וכי ינצו אנשים ונגפו אשה הרה... ואם אסון יהיה \u0003ונתתה נפש תחת נפש\"\u0004 (שמות כא כב–כג), ש\"נפש\" כאן משמעו \u0003ממון,\u0004 כופר נפש.","והוא דן בדבר: \u0003אתה אומר\u0004 שכוונתו \u0003ממון, או אינו אלא\u0004 נטילת \u0003נפש ממש?\u0004 את הדבר ניתן להוכיח ממה ש\u0003נאמר\u0004 לשון \u0003\"נתינה\" למעלה\u0004 (\"ענוש יענש כאשר ישית עליו בעל האשה ונתן בפלילים\". שמות כא, כב), \u0003ונאמר\u0004 לשון \u0003\"נתינה\" למטה\u0004 (\"ואם אסון יהיה ונתתה נפש תחת נפש\". שמות כא כג), \u0003מה להלן\u0004 למעלה נתינה זו משמעה שיתן \u0003ממון, אף כאן\u0004 למטה \u0003ממון.\u0004 וחכמים מפרשים שהיא נטילת נפש ממש. הרי דין שיש בו צד כרת לגבי דיני נפשות.","וב\u0003דיני מכות\u0004 כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' ישמעאל ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 פסק דין אודות חיוב אדם \u0003מכות\u0004 אינו נעשה אלא \u0003בשלשה\u0004 דיינים. \u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמרו: בעשרים ושלשה.\u0004 ולדעתו אם דנוהו שלושה למלקות, יכול לתבוע מהם ממון דמי חבלתו, ואם קידש בממון זה אשה, הרי נובע צד חיוב כרת התלוי במחלוקת אם היה בית הדין מוסמך לדון בכך.","\u0003\"בין נגע לנגע\"\u0004 — פירושו להבחין \u0003בין נגעי אדם, נגעי בתים, נגעי בגדים.\u0004","ומחלוקת שיש בה צד כרת ב\u0003נגעי אדם\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יהושע ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אם בהרת קדם לשער הלבן,\u0004 שלאחר שראה הכהן את הבהרת צמח בה שיער לבן — \u0003טמא\u0004 כמפורש בתורה, ו\u0003אם שער לבן קדם לבהרת\u0004 — \u0003טהור.\u0004 ואולם אם היה \u0003ספק\u0004 מה קדם — חכמים אומרים: \u0003טמא, ר' יהושע אומר: כהה.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"כהה\"? אמר רבא: כהה\u0004 פירושו כבהרת שכהה מראה, שנאמר בתורה כי הוא \u0003טהור.\u0004 ואם יכנס איש שיש בו ספק זה למקדש, מחלוקת היא אם חייב כרת.","ו\u0003נגעי בתים\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אלעזר בר' שמעון ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר בר' שמעון אומר: לעולם אין הבית טמא\u0004 בנגע צרעת \u0003עד שיראה\u0004 הנגע \u0003כ\u0004גודל \u0003שני גריסין, על שתי אבנים, בשתי כתלים, בקרן זוית\u0004 שבבית. \u0003ארכו\u0004 של הנגע \u0003כשני גריסין ורחבו כגריס.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר בר' שמעון?\u0004 ומסבירים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב זה \u0003\"קיר\"\u0004 ובאותו כתוב \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"קירת\"\u0004 (\"וראה את הנגע... בקירות הבית שקערורות ירקרקות או אדמדמת ומראיהן שפל מן הקיר\". ויקרא יד, לז). \u0003איזהו קיר שהוא כקירות? הוי אומר זה קרן זוית.\u0004 ורק הנכנס לבית כזה טמא, אבל אם לא היה כן הנגע אינו נטמא, ואם יכנס אחר כך למקדש פטור מכרת.","\u0003נגעי בגדים\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יונתן בן אבטולמוס ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יונתן בן אבטולמוס אומר: מנין\u0004"],["\u0003לפריחה\u0004 של נגע צרעת \u0003בבגדים שהיא טהורה,\u0004 שאם פרח הנגע ונתמלא כל הבגד בצרעת שהוא טהור, כשם שהדין בנגעי אדם?","— \u0003נאמרה קרחת וגבחת ב\u0004נגע ה\u0003אדם\u0004 (\"וכי יהיה בקרחת או בגבחת נגע\". ויקרא יג, מב), \u0003ונאמרה קרחת וגבחת בבגדים\u0004 (\"וראה הכהן אחרי הכבס את הנגע... פחתת היא בקרחתו או בגבחתו\". ויקרא יג, נה). \u0003מה להלן\u0004 באדם — אם \u0003פרח\u0004 הנגע \u0003בכולו טהור, אף כאן\u0004 בבגדים — אם \u0003פרח בכולו טהור.\u0004 וחכמים שאינם סבורים כן, אומרים שבגד זה הריהו טמא, והנוגע בו ונכנס למקדש חייב כרת.","\u0003\"דברי\"\u0004 — \u0003אלו הערכין והחרמים והקדישות.\u0004 ונבאר אף באלו מחלוקת שיש בה צד כרת. \u0003הערכין\u0004 — \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' מאיר ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המעריך\u0004 ילד \u0003פחות מבן חדש\u0004 שלא נאמר בתורה כל ערך לו, \u0003ר' מאיר אומר: נותן דמיו,\u0004 שוודאי נתכוון אותו אדם לא לערך, אלא לנדור כפי שוויו של תינוק זה. \u0003וחכמים אומרים: לא אמר כלום.\u0004 ומתוך השאלה האם כסף זה יש בו קדושה, נובעים כמה הבדלים (לענייני קידושין ועוד) העשויים להביא לידי כרת.","\u0003החרמים\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יהודה בן בתירה ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה בן בתירה אומר: סתם חרמים\u0004 אם אמר אדם על חפץ \"חרם הוא\" — הרי הם כהקדש, והם \u0003ל\u0004צורך \u0003בדק הבית\u0004 של המקדש, \u0003שנאמר: \"כל חרם קדש קדשים הוא לה' \"\u0004(ויקרא כז, כח).","\u0003וחכמים אומרים: סתם חרמים לכהן,\u0004 כלומר, אין בהם קדושה אלא הם ניתנים לכהנים, \u0003שנאמר: \"כשדה החרם לכהן תהיה אחזתו\"\u0004 (ויקרא כא), הרי ששדה החרם נחלת הכהן הוא. \u0003אם כן מה תלמוד לומר \"קדש קדשים הוא לה' \"?\u0004 — ללמד \u0003ש\u0004החרם \u0003חל\u0004 גם \u0003על קדשי קדשים ועל קדשים קלים,\u0004 שאף דבר שיש בו קדושה יכול להחרימו וצריך לתת את ערכו להקדש. וממחלוקת זו אם החרם הוא קודש או חול, יש הבדל לענין שימוש בו לצרכים שונים, ולענין קידושין יש כאן צד כרת.","\u0003הקדשות\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר בן יעקב ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר בן יעקב אומר: אפילו צינורא\u0004 (כעין מזלג קטן) \u0003של הקדש צריכה\u0004 בית דין של \u0003עשרה בני אדם\u0004 כדי \u0003לפדותה,\u0004 וחכמים סבורים שדי בשלושה. שלדעת ר' אליעזר בן יעקב אם פדו אותה רק שלושה הריהי עדיין קודש, ויש הבדל לדין מעילה ולאפשרות השימוש בצינורא.","\u0003\"ריבת\"\u0004 — \u0003זה השקאת סוטה, ועריפת העגלה, וטהרת מצורע. השקאת סוטה\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר ור' יהושע. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקנא לאשתו,\u0004 כלומר, הבעל המזהיר את אשתו שלא תהא במקום סתר עם גבר מסויים, \u0003ר' אליעזר אומר: מקנא\u0004 ומזהיר אותה \u0003על פי שנים\u0004 (בפני שני עדים), \u0003ומשקה,\u0004 כלומר, מביא אותה למקדש להשקותה מי סוטה אם נסתרה עם אותו אדם \u0003על פי עד אחד או על פי עצמו.\u0004","\u0003ר' יהושע אומר: מקנא\u0004 לה \u0003על פי שנים, ומשקה\u0004 אותה \u0003על פי שנים.\u0004 ומכאן נובע הבדל לענין כתובתה אם מגיע לה כתובתה או לא (שסוטה שלא נבדקה אינה מקבלת כתובה), ולענין השימוש בממון כתובתה, ואם הוא נחשב כגזל.","\u0003עריפת עגלה\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר ור' עקיבא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאין היו מודדין\u0004 מן החלל לעיר הקרובה? \u0003ר' אליעזר אומר: מטיבורו\u0004 של המת, \u0003ר' עקיבא אומר: מחוטמו. ר' אליעזר בן יעקב אומר: ממקום שנעשה בו חלל\u0004 כרגיל, \u0003מצוארו,\u0004 ולדעת כל חכם אם מדדו ממקום שאינו מתאים אין העגלה מתקדשת, והיא חולין ואפשר לקדש בה אשה, ויש גם כאן צד כרת.","לגבי \u0003טהרת מצורע\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' שמעון וחכמים, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 מצורע ש\u0003אין לו בהן יד,\u0004 או \u0003בהן רגל,\u0004 או \u0003אוזן\u0004 \u0003ימנית\u0004 שאמרה התורה שיש לתת עליהם דם ושמן כדי לטהר את המצורע — \u0003אין לו טהרה עולמית. ר' אליעזר אומר: נותן לו על מקומו,\u0004 על המקום בו היו חלקים אלה בגופו, \u0003ויוצא. ר' שמעון אומר: נותן על של שמאל ויוצא.\u0004 ובקביעה אם מצורע זה נטהר תלוי היתרו להכנס למקדש, ואם נכנס — אם חייב כרת משום טומאה.","\u0003\"בשעריך\"\u0004 — \u0003זה לקט שכחה\u0004 ו\u0003פיאה.\u0004 כיצד? \u0003לקט\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שני שבלין\u0004 שלא נקצרו עם האלומה ומצאן עני בשדה — הריהן \u0003לקט,\u0004 ומותר לקחתן, \u0003שלשה\u0004 שיבלים — \u0003אינן לקט\u0004 ויחזור בעל הבית ויקחן, אם ירצה. ובדין \u0003שכחה\u0004 — \u0003שני עומרין\u0004 שנשארו בשדה הם בגדר \u0003שכחה,\u0004 ושייכים לעניים, \u0003שלשה\u0004 עומרים ויותר — \u0003אינן שכחה,\u0004 ושייכים לבעל הבית.","\u0003ועל כולן בית שמאי אומרים: שלש לעני וארבע לבעל הבית.\u0004 ולפי זה אם לקח העני שבולת שלישית או עומר שלישי הריהו לדעת בית הלל גזלן, ואינו יכול לקדש בו את האשה.","\u0003פיאה\u0004 — כגון \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' ישמעאל ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצות פיאה\u0004 האמורה בתורה לתת את פאת שדהו לעניים היא \u0003להפריש\u0004 את הפיאה \u0003מן הקמה.\u0004 ואם \u0003לא הפריש מן הקמה\u0004 — \u0003יפריש\u0004 שיעור פאה (אחד משישים בערך) \u0003מן העומרין. לא הפריש מן העומרין\u0004 — \u0003יפריש מן הכרי עד שלא מירחו\u0004 (שלא סידרו בערימה חלקה וישרה כראוי). ואם \u0003מירחו\u0004 — נתחייבה כבר תבואה זו במעשר, ואז \u0003מעשר\u0004 כראוי \u0003ונותן לו\u0004 לעני כדי שיעור פיאה.","\u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמרו: אף מפריש מן העיסה\u0004 כשיעור פיאה, וחכמים אומרים שלאחר טחינה שוב אין חיוב פיאה בקמח. וכשלקח העני מן העיסה מחלוקת אם נחשבת היא כרכושו הראוי לקדש בו, או לא.","שנינו במשנה שהיו בירושלים \u0003שלשה בתי דינין,\u0004 וכיצד היה עושה בית הדין שבפניו בא הזקן הממרא. \u0003אמר רב כהנא:\u0004 אם \u0003הוא\u0004 הזקן הממרא \u0003אומר מפי השמועה,\u0004 כלומר, כך שמעתי ולמדתי מפי רבותי, \u0003והן\u0004 בית הדין \u0003אומרין מפי השמועה,\u0004 שכך קיבלו הם מפי רבותיהם — \u0003אינו נהרג,\u0004 שיש לו על מה לסמוך.","\u0003הוא אומר: \"כך הוא בעיני\",\u0004 שאין לו מסורת, אבל כך נראה בעיניו, \u0003והן אומרין: \"כך הוא בעינינו\"\u0004 — \u0003אינו נהרג. וכל שכן\u0004 אם \u0003הוא אומר מפי השמועה, והן אומרין: \"כך הוא בעינינו\"\u0004 — ודאי \u0003אינו נהרג. עד שיאמר\u0004 הוא: \u0003\"כך הוא בעיני\", והן אומרים: מפי השמועה\u0004 קיבלנו היפך דבריך. שאם הוא בא ורוצה על ידי סברתו לחלוק על מסורת הקבלה הריהו נידון למיתה. \u0003תדע,\u0004 ראיה לדבר, \u0003שהרי לא הרגו את עקביא בן מהללאל\u0004 אף שחלק על כל חכמי דורו, וזאת משום שאמר מפי השמועה.","\u0003ור' אלעזר אומר: אפילו הוא אומר מפי השמועה, והן אומרין \"כך הוא בעינינו\"\u0004 — \u0003נהרג,\u0004 וטעם הדבר הוא — \u0003כדי שלא ירבו מחלוקות בישראל\u0004 ותיפסק הלכה אחת לכל העם. \u0003ואם תאמר: מפני מה לא הרגו את עקביא בן מהללאל?\u0004 — \u0003מפני שלא הורה הלכה למעשה,\u0004 ורק טען לאמיתות שיטתו, ודבר זה מותר תמיד.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו] שאומר הזקן הממרא: \u0003כך דרשתי וכך דרשו רוב חבירי, כך למדתי וכך למדו חבירי\". מאי לאו\u0004 \u0005[האם לא]\u0006 כולל הדבר ש\u0003הוא אומר מפי השמועה, והם אומרין \"כך הוא בעינינו\"!\u0004 ודוחים: \u0003לא,\u0004 יש לפרש כך: ש\u0003הוא אומר \"כך הוא בעיני\", והם אומרים מפי השמועה.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003אמר ר' יאשיה: שלשה דברים סח לי זעירא\u0004 שהיה \u0003מאנשי ירושלים: בעל שמחל על קינויו,\u0004 שלאחר שקינא לאשתו שלא תסתר חזר ואמר שהוא מוחל לה — \u0003קינויו מחול,\u0004 ואם נסתרה אינו צריך להשקותה."],["\u0003בן סורר ומורה שרצו אביו ואמו למחול לו\u0004 ואף שחטא לא הביאוהו לבית דין — \u0003מוחלין לו.\u0004","וכן \u0003זקן ממרא שרצו בית דינו למחול לו\u0004 — \u0003מוחלין לו. וכשבאתי אצל חבירי שבדרום\u0004 וספרתי להם מסורת זו, \u0003על שנים\u0004 מהם \u0003הודו לי,\u0004 ו\u0003על זקן ממרא לא הודו לי, כדי שלא ירבו מחלוקת בישראל.\u0004 וכיון שזהו טעם העונש, הרי זו הוכחה שגם אם אמר הוא מפי השמועה הריהו חייב, ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא לשיטת רב כהנא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: מתחילה\u0004 בדורות ראשונים \u0003לא היו מרבין מחלוקת בישראל, אלא\u0004 כך היו קובעים הלכה: \u0003בית דין של שבעים ואחד יושבין בלשכת הגזית, ושני בתי דינין של עשרים ושלשה, אחד יושב על פתח הר הבית, ואחד יושב על פתח העזרה, ושאר בתי דינין של עשרים ושלשה יושבין בכל עיירות ישראל.\u0004","\u0003הוצרך הדבר לשאול,\u0004 שלא היה ברור ומקובל — \u0003שואלין מבית דין שבעירן. אם שמעו\u0004 חכמי בית הדין הלכה בענין זה — \u0003אמרו להן, ואם לאו\u0004 \u0005[לא]\u0006 שמעו — \u0003באין לזה שסמוך לעירן. אם שמעו\u0004 אותו בית דין הלכה בענין זה — \u0003אמרו להם, ואם לאו\u0004 \u0005[לא]\u0006 שמעו — \u0003באין לזה שעל פתח הר הבית. אם שמעו\u0004 אותו בית דין הלכה בענין זה — \u0003אמרו להם, ואם לאו\u0004 \u0005[לא]\u0006 שמעו \u0003באין לזה שעל פתח העזרה.\u0004","\u0003ואומר\u0004 אחד החכמים שלא הסכימו כל חבריו עמו: \u0003כך דרשתי וכך דרשו חבירי, כך למדתי וכך למדו חבירי. אם שמעו\u0004 אותו בית דין הלכה בענין זה — \u0003אמרו להם, ואם לאו\u0004 \u0005[לא]\u0006 שמעו — \u0003אלו ואלו באין ללשכת הגזית, ששם יושבין\u0004 חכמי סנהדרי גדולה \u0003מ\u0004שעת הקרבת \u0003תמיד של שחר\u0004 בבוקר \u0003עד\u0004 שעת הקרבת \u0003תמיד של בין הערבים.\u0004","\u0003ובשבתות ובימים טובים\u0004 שאין דנים בהם היו \u0003יושבין בחיל,\u0004 במקום המוקף חומה קטנה בתוך הר הבית. \u0003נשאלה שאלה בפניהם, אם שמעו\u0004 אותו בית דין הלכה בענין זה — \u0003אמרו להם, ואם לאו\u0004 \u0005[לא]\u0006 שמעו — היו \u0003עומדין למנין\u0004 (להצבעה) באותו נושא. אם \u0003רבו המטמאים\u0004 — \u0003טמאו,\u0004 קבעו הלכה שטמא הוא, אם \u0003רבו המטהרין\u0004 — \u0003טהרו.\u0004 ובאופן זה נסתיימו כל המחלוקות תוך זמן קצר.","אבל \u0003משרבו תלמידי שמאי והלל שלא שמשו\u0004 את רבותיהם ולא למדו \u0003כל צרכן\u0004 — אז \u0003רבו מחלוקת בישראל, ונעשית תורה כשתי תורות,\u0004 שנוצרו שתי אסכולות שונות ולא הגיעו לכלל הלכה פסוקה בכל נושא.","ועוד לענין סדרי בתי הדין הקודמים: \u0003משם\u0004 מהסנהדרין שבלשכת הגזית \u0003כותבין ושולחין בכל מקומות: כל מי שהוא חכם ושפל ברך\u0004 (צנוע) \u0003ודעת הבריות נוחה הימנו\u0004 — \u0003יהא דיין בעירו.\u0004 אם הצליח, אותו דיין בעירו, \u0003משם מעלין אותו ל\u0004בית דין של \u0003הר הבית,\u0004 כשנתפנה מקום לדיין, \u0003משם ל\u0004בית דין של \u0003עזרה, משם ללשכת הגזית\u0004 — הכל לפי חכמתו.","אגב דברים אלה בענין בחירת דיינים, מביאים כי \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]:\u0006 \u0003איזהו בן העולם הבא?\u0004 — \u0003ענוותן ושפל ברך, שייף עייל שייף ונפיק\u0004 \u0005[מתכופף\u0006 ו\u0005נכנס\u0006 ו\u0005מתכופף ויוצא]\u0006 בצניעות, \u0003וגריס באורייתא תדירא\u0004 \u0005[ולומד בתורה בקביעות],\u0006 \u0003ולא מחזיק טיבותא לנפשיה\u0004 \u0005[טובה לעצמו],\u0006 שאינו רואה עצמו משום מעלותיו כאדם גדול הראוי לרוב כבוד. \u0003יהבו ביה רבנן עינייהון\u0004 \u0005[נתנו בו חכמים עיניהם]\u0006 \u0003ברב עולא בר אבא,\u0004 שלדעתם התקיימו בו כל המעלות הללו.","שנינו במשנה שאף אם \u0003חזר\u0004 הזקן הממרא \u0003לעירו ושנה\u0004 כדרך שהיה שונה קודם ולא שינה דעתו — אינו חייב, עד שיורה לעשות כשיטתו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הזקן ממרא \u0003אינו חייב\u0004 מיתה \u0003עד שיעשה\u0004 הוא עצמו \u0003כהוראתו, או שיורה לאחרים ויעשו\u0004 הם \u0003כהוראתו.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין זה ש\u0003יורה לאחרים ויעשו כהוראתו\u0004 יש חידוש בדבר, כי \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003לאו בר קטלא\u0004 \u0005[לא בן מוות]\u0006 \u0003הוא, והשתא בר קטלא\u0004 \u0005[ועכשיו בן מוות]\u0006 \u0003הוא. אלא\u0004 מה טעם לומר \u0003שיעשה\u0004 הוא עצמו \u0003כהוראתו?\u0004 והלא \u0003מעיקרא נמי בר קטלא\u0004 \u0005[מתחילה\u0006 על המעשה עצמו \u0005גם כן בן מוות]\u0006 \u0003הוא,\u0004 שהרי אם היה עובר עבירה שעונשה מיתת בית דין היה נידון למוות על העבירה שעבר, גם אם לא המרה את דעת בית דין מתחילה! ומוסיפים: \u0003התינח היכא דאורי\u0004 \u0005[\u0006דבר \u0005זה נוח\u0006 לפרש \u0005במקום שהורה]\u0006 \u0003ב\u0004ענין \u0003חלב ודם,\u0004 שאמנם חייבים עליהם כרת אך לא מיתה בידי אדם, \u0003דמעיקרא לאו בר קטלא\u0004 \u0005[שמתחילה\u0006 על המעשה עצמו \u0005לא בן מוות]\u0006 \u0003הוא, והשתא בר קטלא\u0004 \u0005[ועכשיו\u0006 שהורה \u0005בן\u0006 \u0005מוות]\u0006 \u0003הוא. אלא היכא דאורי\u0004 \u0005[במקום שהורה]\u0006 באיסורים שהם \u0003בחייבי מיתות בית דין\u0004 ועשה בעצמו כן, הרי \u0003מעיקרא נמי\u0004 \u0005[מתחילה גם כן]\u0006 גם אם לא הורה \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא!\u0004","ומשיבים: בכל זאת יש הבדל, כי \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 אם לא הורה \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003התראה\u0004 לפני המעשה כדי שיהרגוהו, ואילו \u0003השתא לא בעי\u0004 \u0005[עכשיו\u0006 בענין הוראה \u0005אינו צריך]\u0006 \u0003התראה,\u0004 אלא כיון שעבר נידון למוות משום המראתו.","ושואלים: ואם היה זה \u0003מסית, דלא בעי\u0004 \u0005[שאינו צריך]\u0006 \u0003התראה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ובדין זה מהו ההבדל בין זקן ממרא ואדם אחר? ומשיבים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 אם לא היה מורה שהסתה זו מותרת, \u0003אי אמר טעמא, מקבלינן מיניה\u0004 \u0005[אם היה אומר טעם\u0006 להתנצל ולהסביר שלא נתכוון לכך, \u0005היינו מקבלים ממנו],\u0006 \u0003השתא אי אמר טעמא, לא מקבלינן מיניה\u0004 \u0005[עכשיו, אם יאמר טעם, אין מקבלים ממנו],\u0006 שהרי גילה דעתו שאין בכך איסור ובוודאי על דעת כן עשה.","לענין הוראה של זקן ממרא, \u0003חומר\u0004 הוא \u0003בדברי סופרים מבדברי תורה,\u0004 כיצד? — זקן ממרא \u0003האומר \"אין\u0004 מצות \u0003תפילין\u0004 קיימת כלל \u0003\",\u0004 \u0003כדי לעבור על דברי תורה\u0004 — \u0003פטור\u0004 מעונש הממרא, משום שהחולק על דברי תורה עצמם אינו נקרא עוד זקן וחכם, ואין דעתו חשובה כלל. ואולם אם חלק על מסורת חכמים שבדין תפילין ואומר למשל שהן \u0003חמש טוטפות\u0004 ולא ארבע, כדי \u0003להוסיף על דברי סופרים\u0004 — \u0003חייב.\u0004","\u0003אמר ר' אלעזר אמר ר' אושעיא,\u0004 כללו של דבר: \u0003אינו חייב אלא על דבר שעיקרו\u0004 (עיקר מצוותו) \u0003מדברי תורה, ופירושו\u0004 (כיצד דרך עשייתו) \u0003מדברי סופרים. ויש בו\u0004 כדי \u0003להוסיף\u0004 פרט למצוה זו, \u0003ואם הוסיף גורע\u0004 על ידי כך ושוב אינה נחשבת מצוה. \u0003ואין לנו\u0004 דוגמה שיש בה כל התנאים הללו \u0003אלא תפילין,\u0004 וכל זה \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יהודה\u0004 שאין זקן ממרא נענש אלא אם חלק על דבר שעיקרו מדברי תורה ופירושו מדברי סופרים.","ומקשים: וכי רק תפילין הם דוגמה לכך? \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם \u0003לולב\u0004 ושאר מינים הניטלים בחג הסוכות, ש\u0003עיקרו מדברי תורה\u0004 (\"ולקחתם לכם ביום הראשון... כפות תמרים\". ויקרא כג, מ), \u0003ופירושו\u0004 מה הם בדיוק אותם ארבעת המינים שנזכרים בו ומה מניינם, הם \u0003מדברי סופרים, ויש בו להוסיף\u0004 מינים אחרים, \u0003ואם הוסיף גורע\u0004 ושוב אין זה לולב כהלכתו!","ודוחים: אין הדבר כן, כי \u0003בלולב מאי סבירא לן\u0004 \u0005[מה סבורים אנו]?\u0006 \u0003אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 מעיקר הדין ש\u0003לולב אין צריך אגד,\u0004 כלומר, שאין מצוה מן התורה לאגוד ולקשור את כל המינים שבלולב יחד, אם כן לא עשה כלום כשהוסיף עוד מין לארבעת המינים, כי \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה,\u0006 המינים שהן מצוה, \u0005לבדו\u0006 הוא \u0005עומד וזה\u0006 שהוסיף להם \u0005לבדו\u0006 הוא \u0005עומד],\u0006 והרי זה כמחזיק בידו לולב של מצוה ועוד דבר נוסף שאינו קשור כלל למצוה, \u0003ואי סבירא לן\u0004 \u0005[ואם סבורים אנו]\u0006 ש\u0003צריך\u0004 הלולב \u0003אגד,\u0004 שחייבים לאגוד את מיניו, אם כן \u0003גרוע ועומד הוא\u0004 שמשעת עשייתו אינו לולב כלל שהרי נוספו בו מינים אחרים, והרוצה לעשות בו מצוה לא עשה כלום, כאילו היה נוטל חוט ברזל לצורך זה.","ומקשים: וכי אין דוגמה לכך? \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 דין \u0003ציצית,\u0004 ש\u0003עיקרו מדברי תורה\u0004 (במדבר טו, לז–מא), \u0003ופירושו מדברי סופרים,\u0004 כמה הם ציציותיו ומכמה חוטים הם, \u0003ויש בו להוסיף\u0004 חוטים נוספים או ציציות נוספות, \u0003ואם הוסיף גורע!\u0004","ומשיבים: אי אפשר לעשות כן, כי \u0003בציצית, מאי סבירא לן\u0004 \u0005[מה סבורים אנו]?\u0006 \u0003אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 ש\u0003קשר העליון\u0004 שקושרים את חוטי הציצית יחד בכנף הבגד הרי זה \u0003לאו דאורייתא\u0004 \u0005[אינו מן התורה],\u0006 שמדין תורה צריך רק שתהיינה ציציות במקום, ואם כן \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה,\u0006 החוטים הצריכים \u0005לבדו עומד וזה\u0006 החוט הנוסף \u0005לבדו עומד],\u0006 והחוטים הנוספים הקשורים בטלית אינם מעכבים. \u0003ואי סבירא לן\u0004 \u0005[ואם סבורים אנו]\u0006"],["ש\u0003קשר העליון דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, אם כן משעת קשירתו \u0003גרוע ועומד\u0004 הוא, שאין זו ציצית כלל.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאתה אומר שהתוספת פוסלת מעיקרה, אם כן \u0003תפילין נמי\u0004 \u0005[גם כן]\u0006 נכנסים לאותו גדר. כיצד? — \u0003אי עביד\u0004 \u0005[אם עשה]\u0006 \u0003ארבעה בתי\u0004 \u0005[בתים],\u0006 \u0003ואייתי אחרינא ואנח גבייהו\u0004 \u0005[והביא\u0006 עוד \u0005בית אחר והניח עמם],\u0006 \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה\u0006 ארבעת הבתים \u0005לבדו עומד וזה\u0006 הבית החמישי \u0005לבדו עומד]\u0006 ואינו חייב על הבית החמישי, \u0003ואי עביד\u0004 \u0005[ואם עשה]\u0006 \u0003חמשה בתי\u0004 \u0005[בתים]\u0006 מתחילה \u0003גרוע ועומד הוא!\u0004 ומשיבים: אינו דומה כאן, כי \u0003האמר\u0004 \u0005[הרי\u0006 כבר \u0005אמר]\u0006 \u0003ר' זירא\u0004 ביחס ל\u0003בית\u0004 ה\u0003חיצון\u0004 של התפילין שאם \u0003אינו רואה את האויר,\u0004 והוא מכוסה בדבר מה שאינו מגופו של הבית — \u0003פסול.\u0004 ונמצא שהמוסיף בית חמישי לתפילין הרי הוא פוסל אותן בהוספה זו, ואין לומר \"האי לחודיה קאי\", ועל תוספת כזו חייב הזקן הממרא.","\u0003אין ממיתין אותו\u0004 את הזקן הממרא \u0003לא בבית דין שבעירו\u0004 (אף ששם עשה את העבירה), \u0003ולא בבית דין שביבנה\u0004 אף על פי שהיה זה בית דין הגדול של ישראל במשך תקופה מסויימת, \u0003אלא מעלין אותו לבית דין הגדול שבירושלים, ומשמרין אותו\u0004 במאסר \u0003עד הרגל\u0004 (אחד החגים, הרגלים), \u0003וממיתין אותו ברגל\u0004 כשיש רוב עם בירושלים, \u0003שנאמר: \"וכל העם ישמעו ויראו ולא יזידון עוד\"\u0004 (דברים יז, יג), אלו \u0003דברי ר' עקיבא. ר' יהודה אומר: אין מענין את דינו של זה\u0004 שיצטרך להמתין ולהתייסר זמן רב בידיעה שהוא נידון למוות, \u0003אלא ממיתין אותו מיד\u0004 כשנידון, \u0003ו\u0004אולם \u0003כותבין ושולחין שלוחין בכל המקומות: איש פלוני מתחייב מיתה בבית דין\u0004 על שהמרה פי בית דין.","כתוספת למחלוקת ר' עקיבא ור' יהודה במשנה מביאים מה ששנינו עוד בענין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין ממיתין אותו,\u0004 את הזקן הממרא, \u0003לא בבית דין שבעירו, ולא בבית דין שביבנה, אלא מעלין אותו לבית דין הגדול שבירושלים, ומשמרין אותו עד הרגל, וממיתין אותו ברגל, שנאמר: \"וכל העם ישמעו ויראו\",\u0004 אלו \u0003דברי ר' עקיבא.\u0004","\u0003אמר לו ר' יהודה\u0004 לר' עקיבא: \u0003וכי נאמר \"יראו וייראו\"?\u0004 שצריך משום כך להמיתו לעיני כל ישראל, \u0003והלא לא נאמר אלא \"ישמעו וייראו\"!\u0004 אם כן \u0003למה מענין דינו של זה? אלא, ממיתין אותו מיד, וכותבין ושולחין\u0004 להודיע \u0003בכל מקום: איש פלוני נתחייב מיתה בבית דין,\u0004 ועל ידי כך שומעים כל העם ומתייראים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעה\u0004 נידונים למוות \u0003צריכין הכרזה\u0004 לרבים: \u0003המסית, ובן סורר ומורה, וזקן ממרא, ועדים זוממין. בכולהו כתיב בהו\u0004 \u0005[בכולם נאמר בהם]\u0006 הלשונות \u0003\"וכל העם\"\u0004 (שם), \u0003\"וכל ישראל\"\u0004 (שם יג, יב. שם כא, כא), ואילו \u0003בעדים זוממין כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"והנשארים\u0004 ישמעו ויראו\u0003\"\u0004 (שם יט, כ), וטעם השינוי: ש\u0003לא כולי עלמא חזו לסהדותא\u0004 \u0005[הכל ראויים לעדות],\u0006 שהרי בכללם נשים ופסולי עדות, ולכן אין האיום שבמיתת עדים זוממים על כל ישראל אלא על חלק (\"הנשארים\") מהם.","\u0003נביא השקר\u0004 הנידון בחנק כולל את \u0003המתנבא מה שלא שמע\u0004 מפי הגבורה, \u0003ו\u0004כן את המתנבא \u0003מה שלא נאמר לו,\u0004 ואפילו נאמר הדבר לנביא אחר — \u0003מיתתו בידי אדם\u0004 בחנק.","\u0003אבל\u0004 נביא \u0003הכובש את נבואתו,\u0004 שאינו רוצה להתנבא ברבים, \u0003והמוותר על דברי נביא,\u0004 אדם הבז לדברי הנביא ואינו רוצה לציית להם, \u0003ונביא שעבר על דברי עצמו\u0004 שנאמר לו שיעשה דבר ואינו עושהו — \u0003מיתתו בידי שמים, שנאמר\u0004 בנביא: \u0003\"\u0004והיה האיש אשר לא ישמע אל דברי אשר ידבר בשמי \u0003אנכי אדרש מעמו\"\u0004 (דברים יח, יט).","\u0003המתנבא בשם עבודה זרה, ואומר: כך אמרה עבודה זרה, אפילו כוון את ההלכה\u0004 בשם אותה עבודה זרה, ואסר כדין, \u0003לטמא את הטמא ולטהר את הטהור\u0004 — הרי זה חייב מיתה.","ועוד נידונים בחנק: \u0003הבא על אשת איש,\u0004 ומהיכן מתחיל גדר אשת איש? — \u0003כיון שנכנסה לרשות הבעל לנשואין, אף על פי שלא נבעלה\u0004 ועדיין היא בתולה — \u0003הבא עליה הרי זה\u0004 נידון \u0003בחנק\u0004 ולא כנערה המאורסה בסקילה, לפי שמשעת כניסה הריהי כאשת איש.","\u0003ו\u0004כן נידונים בחנק \u0003זוממי בת כהן\u0004 שהעידו עליה בשקר שזנתה, \u0003ו\u0004כן \u0003בועלה\u0004 של בת כהן אף הוא נידון בחנק. ומעירים: \u0003שכל המוזמין מקדימין לאותה מיתה\u0004 שזממו להרוג בה את הנאשם, \u0003חוץ מזוממי בת כהן ובועלה,\u0004 שאף שבת כהן עצמה נידונה בשריפה, העדים נידונים בחנק כדין הבועל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בעונשי החוטאים בנבואה: \u0003שלשה\u0004 מהם \u0003מיתתן בידי אדם, ושלשה מיתתן בידי שמים.\u0004 ופרטיהן: \u0003המתנבא מה שלא שמע, ומה שלא נאמר לו, והמתנבא בשם עבודה זרה\u0004 — \u0003מיתתן\u0004 \u0003בידי אדם.\u0004 ואילו \u0003הכובש את נבואתו, והמוותר על דברי נביא, ונביא שעבר על דברי עצמו\u0004 — \u0003מיתתן בידי שמים.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 ומה מקורם במקרא? \u0003אמר רב יהודה אמר רב,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"אך הנביא אשר יזיד לדבר דבר בשמי את אשר לא צויתיו לדבר ואשר ידבר בשם אלהים אחרים ומת הנביא ההוא\" (שם יח, כ). ומפרשים: \u0003\"אך הנביא אשר יזיד לדבר דבר בשמי\"\u0004 — הרי \u0003זה המתנבא מה שלא שמע, \"ואשר לא צויתיו\"\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לחבירו צויתיו,\u0004 אם כן \u0003זה המתנבא מה שלא נאמר לו. \"ואשר ידבר בשם אלהים אחרים\"\u0004 — \u0003זה המתנבא בשם עבודה זרה, וכתיב\u0004 \u0005[ונאמר]\u0006 בכל אלה: \u0003\"ומת הנביא ההוא\", וכל מיתה האמורה בתורה סתם אינה אלא חנק.\u0004","\u0003הכובש את נבואתו\u0004 ואינו מתנבא, \u0003והמוותר על דברי נביא, ונביא שעבר על דברי עצמו\u0004 — \u0003מיתתן בידי שמים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה האיש אשר לא ישמע\u0004 אל דברי אשר ידבר בשמי אנוכי אדרש מעמו\u0003\"\u0004 (שם יט), \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 גם כן \u0003\"לא ישמיע\"\u0004 — הרי עונש לנביא שכובש ואינו משמיע נבואתו, \u0003וקרי ביה\u0004 \u0005[וקרא בו]\u0006 גם כן \u0003\"לא ישמע אל דברי\"\u0004 שאינו מציית לדבר ה' שנגלה לו עצמו, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בכל אלה: \u0003\"אנכי אדרש מעמו\",\u0004 ומשמעו — מיתתם \u0003בידי שמים.\u0004","ומבארים את דברי הברייתא. מה ששנינו בה: \u0003המתנבא מה שלא שמע\u0004 — הרי זה \u0003כגון צדקיה בן כנענה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעש לו צדקיהו בן כנענה קרני ברזל\u0004 ויאמר כה אמר ה' באלה תנגח את ארם עד כלותם\u0003\"\u0004 (דברי הימים ב' יח, י). ושואלים: \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]?\u0006 הרי \u0003רוח נבות אטעיתיה\u0004 \u0005[הטעתה אותו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ה' מי יפתה את אחאב ויעל ויפל ברמת גלעד... ויצא הרוח ויעמד לפני ה' ויאמר אני אפתנו... ויאמר תפתה וגם תוכל צא ועשה כן\"\u0004 (מלכים א' כב, כ–כב).","אגב הבאת הפסוק מביאים מה ש\u0003אמר רב יהודה: מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"צא\"\u0004 שנאמר בכתוב זה, מדוע לא נאמר סתם \"עשה כן\"? — כוונתו: \u0003צא ממחיצתי,\u0004 שכיון שהציע לעשות דבר שקר שוב אינו ראוי לעמוד במחיצת הקדוש ברוך הוא. ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 היתה אותה \u0003רוח? אמר ר' יוחנן: רוחו של נבות היזרעאלי\u0004 היתה ורצתה לנקום באחאב. וכיון שרוח זו נשלחה מאת ה' להטעות את הנביאים, הלא היו אלה מוטעים ולא מזידים בנבואת שקר.","ומשיבים: \u0003הוה ליה למידק\u0004 \u0005[היה לו\u0006 לצדקיהו \u0005לדקדק\u0006 בדברים\u0005],\u0006 \u0003כ\u0004שיטת \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: סיגנון אחד עולה לכמה נביאים,\u0004 שנביאים שונים פעמים נכנס בלבם אותו תוכן בלשונות שונות, \u0003ואין שני נביאים מתנבאין בסיגנון אחד,\u0004 באותן מילים ממש.","כגון מה ש\u0003עובדיה אמר: \"זדון לבך השיאך\"\u0004 (עובדיה א, ג), ו\u0003ירמיה\u0004 מתנבא באותו ענין, אבל משנה מעט מן הסגנון, שהוא \u0003אמר: \"תפלצתך השיא אתך זדון לבך\"\u0004 (ירמיה מט, טז). \u0003והני מדקאמרי כולהו כהדדי\u0004 \u0005[ו\u0006נביאים \u0005אלה מכיון שאמרו כולם כאחד]\u0006 באותו סגנון (\"עלה... והצלח ונתן ה' ביד המלך\"), \u0003שמע מינה לא כלום קאמרי\u0004 הרי זה סימן מובהק לנבואתם שנבואת שקר היא.","ושואלים: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לא הוה ידע ליה להא\u0004 \u0005[היה יודע\u0006 צדקיה בן כנענה \u0005אותה הלכה]\u0006 של \u0003ר' יצחק\u0004 ולא ידע סימן זה? ומשיבים: \u0003יהושפט\u0004 מלך יהודה \u0003הוה התם\u0004 \u0005[היה שם],\u0006 \u0003וקאמר להו\u0004 \u0005[ואמר להם].\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר יהושפט האין פה נביא עוד לה' \"\u0004(מלכים א' כב, ז). \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחאב: \u0003הא איכא\u0004 \u0005[הרי יש,\u0006 מצויים\u0005]\u0006 \u0003כל הני\u0004 \u0005[אלה]\u0006 הנביאים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 יהושפט: \u0003כך מקובלני מבית אבי אבא,\u0004 כלומר, ממסורת משפחת בית דוד: \u0003סיגנון אחד עולה לכמה נביאים, ואין שני נביאים מתנבאים בסיגנון אחד.\u0004 וכיון שאלה מתנבאים פה אחד אין זו נבואת אמת.","ומבארים את מה ששנינו במשנה: \u0003המתנבא מה שלא נאמר לו\u0004 — \u0003כגון חנניה בן עזור, דקאי\u0004 \u0005[שהיה עומד]\u0006 \u0003ירמיה בשוק העליון\u0004 בירושלים \u0003וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003\"כה אמר ה' צבאות הנני שבר את קשת עילם\u0004 ראשית גבורתם\u0003\"\u0004 (ירמיה מט, לה), \u0003נשא חנניה קל וחומר בעצמו: מה עילם שלא בא אלא לעזור את בבל, אמר הקדוש ברוך הוא: \"הנני שבר את קשת עילם\", כשדים עצמן על אחת כמה וכמה\u0004 שצפויה להם מפלה, \u0003אתא איהו\u0004 \u0005[בא הוא\u0006 עצמו\u0005]\u0006 \u0003בשוק התחתון, אמר: \"כה אמר ה'\u0004 צבאות אלהי \u0003ישראל לאמור\u0004 \u0003שברתי את על מלך בבל\"\u0004 (שם כח, ב). ומסופר שם שמת בידי שמים (\"לכן כה אמר ה' הנני משלחך מעל פני האדמה השנה אתה מת\". שם טז).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: האי\u0004 \u0005[זו]\u0006 נבואת חנניה הרי \u0003לחבירו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא נאמר,\u0004 ומדוע קורא לכך המתנבא מה שלא נאמר לו? הרי זה מתנבא מה שלא שמע! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כיון דאיתיהיב\u0004 \u0005[שניתן]\u0006 \u0003קל וחומר למידרש\u0004 \u0005[להידרש],\u0006 הרי זה \u0003כמאן דאיתמר ליה דמי\u0004 \u0005[כמי שנאמר לו נחשב],\u0006 שכיון שעל פי התורה מותר ללמוד קל וחומר מן הכתובים ומדה זו מחייבת, יכול היה ללמוד קל וחומר אף מנבואת ירמיהו, אלא \u0003הוא ניהו\u0004 \u0005[הוא זה]\u0006 ש\u0003לא נאמר לו\u0004 דבר ולא היה צריך להתנבא בשם ה', אלא לומר שלמד כן בקל וחומר מדברי ירמיהו.","ומה ששנינו במשנה: \u0003המתנבא בשם עבודה זרה\u0004 — \u0003כגון נביאי הבעל.\u0004","\u0003\"הכובש את נבואתו\"\u0004 — \u0003כגון יונה בן אמיתי. \"והמוותר על דברי נביא\"\u0004 — \u0003כגון\u0004"],["\u0003חבריה\u0004 \u0005[חבירו]\u0006 של הנביא \u0003מיכה\u0004 בן ימלא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואיש אחד מבני הנביאים אמר אל רעהו בדבר ה' הכיני נא וימאן האיש להכתו\"\u0004 (מלכים א' כ, לה), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר לו יען אשר לא שמעת\u0004 בקול ה' הנך הולך מאתי והכך האריה וילך מאצלו וימצאהו האריה ויכהו","\u0003\"\u0004(מלכים א' כ, לו), למדנו שהעובר על דברי נביא חייב מיתה בידי שמים. \u0003ונביא שעבר על דברי עצמו\u0004 — \u0003כגון עדו הנביא,\u0004 שלפי המסורת הוא הנביא שנשלח לנבא פורענות לירבעם, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ולא אוכל לחם ולא אשתה מים במקום הזה. \u0003כי כן צוה אתי\u0004 בדבר ה'\u0003\"\u0004 (מלכים א' יג, ח–ט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר לו גם אני נביא כמוך\u0004 ומלאך דבר אלי בדבר ה' לאמר... ויאכל לחם\u0003\"\u0004 (מלכים א' כ, יח), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וישב אתו\u0004 ויאכל לחם בביתו וישת מים\u0003\"\u0004 (מלכים א' כ, יט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וילך וימצאהו אריה\u0004 בדרך וימיתהו\u0003\"\u0004 (מלכים א' כ, כד), הרי שנביא שעובר על דברי עצמו נענש בידי שמים.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב חסדא:\u0004 נביא \u0003הכובש את נבואתו לוקה. אמר ליה\u0004 \u0005[לו]\u0006 בדרך משל: וכי \u0003מאן דאכיל תמרי בארבלא לקי\u0004 \u0005[מי שאוכל תמרים בכברה לוקה]?!\u0006 הלא \u0003מאן מתרי ביה\u0004 \u0005[מי מתרה בו]?\u0006 שגם אם אכל תמרים מתולעים שאסור לאכלם, כיון שאיש לא ראה את התולעים, כיצד ילקוהו? ומי יודע בזה שכובש את נבואתו? \u0003אמר אביי: חבריה נביאי\u0004 \u0005[חבריו הנביאים]\u0006 הם מתרים בו.","שואלים: והם, \u0003מנא ידעי\u0004 \u0005[מנין יודעים]?\u0006 ומשיבים, \u0003אמר אביי: דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כי לא יעשה ה' אלהים דבר כי אם גלה סודו\u0004 אל עבדיו הנביאים\u0003\"\u0004 (עמוס ג, ז). ומקשים: \u0003ודילמא הדרי ביה\u0004 \u0005[ושמא חזרו בו]\u0006 משמים, ושוב אין רוצים שינבא נבואה זו? ומשיבים: \u0003אם איתא דהדרי ביה\u0004 \u0005[אמנם היו חוזרים בו]\u0006 מן הנבואה — \u0003אודועי הוו מודעי לכלהו נביאי\u0004 \u0005[היו מודיעים לכל הנביאים].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003יונה, דהדרי ביה\u0004 \u0005[שחזרו בו]\u0006 \u0003ולא אודעוהו\u0004 \u0005[הודיעוהו]\u0006 שנשתנה גזר דינה של נינוה! ומשיבים: \u0003יונה מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003\"נינוה נהפכת\" אמרי ליה\u0004 \u0005[אמרו לו],\u0006 \u0003איהו\u0004 \u0005[הוא]\u0006 \u0003לא ידע אי\u0004 \u0005[אם]\u0006 \u0003לטובה אי\u0004 \u0005[אם]\u0006 \u0003לרעה,\u0004 והוא סבר שהכוונה היא נהפכת ממש, ולבסוף נתקיימה נבואתו באופן אחר שנהפכה העיר מבחינה מוסרית לטובה.","ועוד שואלים: \u0003המוותר על דברי נביא, מנא ידע דאיענש\u0004 \u0005[מנין יודע\u0006 השומע \u0005ש\u0006נביא הוא ו\u0005יענש]\u0006 על אי ציות לדבריו? ומשיבים: \u0003דיהב ליה\u0004 \u0005[שנותן לו]\u0006 \u0003אות\u0004 שנביא הוא. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מיכה,\u0004 ש\u0003לא יהיב ליה\u0004 \u0005[נתן לו]\u0006 \u0003אות\u0004 לחבירו שבא בדבר ה' ומיאן לו, \u0003ואיענש\u0004 \u0005[ונענש]!\u0006 ומשיבים: \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003מוחזק\u0004 כנביא \u0003שאני\u0004 \u0005[שונה\u0006 הדבר\u0005],\u0006 שאם הוא נביא ידוע שוב אינו צריך לתת אות לכל נבואה, וצריך להשמע לדבריו אם אמרם בשם ה'.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שהמוחזק אינו צריך אות, \u0003אברהם בהר המוריה היכי\u0004 \u0005[איך]\u0006 \u0003שמע ליה\u0004 \u0005[לו]\u0006 \u0003יצחק\u0004 להישחט? והרי לא הראה לו אות. וכן \u0003אליהו בהר הכרמל, היכי סמכי עליה ועבדי\u0004 \u0005[כיצד סמכו עליו ועשו]\u0006 \u0003שחוטי חוץ?\u0004 שהרי אסור להקריב כל קרבן לה' מחוץ למקדש! \u0003אלא היכא\u0004 \u0005[היכן]\u0006 ש\u0003מוחזק\u0004 כנביא \u0003שאני\u0004 \u0005[שונה\u0006 הדבר\u0005]\u0006 ושומעים בקולו.","כיון שהוזכרה עקידת יצחק, מביאים כמה דברי אגדה בענין זה. נאמר: \u0003\"ויהי אחר הדברים האלה והאלהים נסה את אברהם\"\u0004 (בראשית כב, א). ושואלים: \u0003אחר מאי\u0004 \u0005[מה]?\u0006 שהרי לכאורה אין קשר בין המעשים הקודמים ובין מעשה העקידה!","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי בן זימרא: אחר דבריו של שטן.\u0004 וכך היה המעשה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויגדל הילד ויגמל\u0004 ויעש אברהם משתה גדול ביום הגמל את יצחק\u0003\"\u0004 (בראשית כא, ח), \u0003אמר שטן לפני הקדוש ברוך הוא: רבונו של עולם! זקן זה חננתו למאה שנה פרי בטן, מכל סעודה שעשה לא היה לו תור אחד או גוזל אחד להקריב לפניך\u0004 כקרבן תודה? \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003כלום עשה\u0004 שמחה זו \u0003אלא בשביל\u0004 משום \u0003בנו, אם אני אומר לו \"זבח את בנך לפני\"\u0004 — \u0003מיד זובחו. מיד\u0004 לאחר דברים אלה \u0003\"והאלהים נסה את אברהם\",\u0004 (בראשית כב, א).","על הנאמר שם \u0003\"ויאמר קח נא את בנך\"\u0004 (בראשית כב, ב), \u0003אמר ר' שמעון בר אבא: אין \"נא\" אלא לשון בקשה.\u0004 ומדוע נאמר כן? — \u0003משל למלך בשר ודם שעמדו עליו מלחמות הרבה, והיה לו גבור אחד ונצחן. לימים עמדה עליו מלחמה חזקה, אמר לו\u0004 לגיבור: \u0003בבקשה ממך, עמוד לי במלחמה זו\u0004 ונצח בה למענך, \u0003שלא יאמרו: ראשונות אין בהם ממש\u0004 ולא גיבור אמיתי אתה. \u0003אף הקדוש ברוך הוא אמר לאברהם:\u0004 כבר \u0003ניסיתיך בכמה נסיונות ועמדת בכלן, עכשיו עמוד לי בנסיון זה, שלא יאמרו אין ממש ב\u0004נסיונות ה\u0003ראשונים.\u0004","את הלשון \"את בנך את יחידך אשר אהבת את יצחק\" (בראשית כב,ב) מפרשים: \u0003\"את בנך\"\u0004 — אמר לו אברהם: והרי \u0003שני בנים יש לי?!\u0004 אמר לו הקדוש ברוך הוא: \u0003\"את יחידך\"\u0004 — אמר לו אברהם: \u0003זה יחיד לאמו וזה יחיד לאמו.\u0004 אמר לו הקדוש ברוך הוא: \u0003\"אשר אהבת\"\u0004 — אמר לו אברהם: \u0003תרוייהו רחימנא להו\u0004 \u0005[את שניהם אוהב אני].\u0006 אמר לו הקדוש ברוך הוא: \u0003\"את יצחק\". וכל כך למה?\u0004 מדוע לא אמר מיד \"את יצחק\"? — \u0003כדי שלא תטרף דעתו עליו\u0004 מחמת זעזוע.","\u0003קדמו שטן לדרך\u0004 כשהלך לעקוד את בנו, ו\u0003אמר לו\u0004 בלשון הכתוב: \u0003\"הנסה דבר אליך תלאה... הנה יסרת רבים וידים רפות תחזק. כושל יקימון מליך... כי עתה תבוא אליך ותלא\"\u0004 (איוב ד, ב–ה), כלומר, האם אתה מתחרט עכשיו? \u0003אמר לו: \"\u0004ו\u0003אני בתמי אלך\"\u0004 (תהלים כו, יא).","\u0003אמר לו\u0004 השטן: \u0003\"הלא יראתך כסלתך\"\u0004 (איוב ד, ו), כלומר, יראתך את ה' כסילות היא אם תשחוט את בנך. \u0003אמר לו\u0004 אברהם: \u0003\"זכר נא מי הוא נקי אבד\"\u0004 (איוב ד, ז), ובודאי צדיק ה' וישר משפטו. \u0003כיון דחזא דלא קא שמיע ליה\u0004 \u0005[שראה\u0006 השטן \u0005שאין\u0006 אברהם \u0005שומע לו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"ואלי דבר יגנב\u0004 ותקח אזני שמץ מנהו\u0003\"\u0004 (איוב ד, יב), \u0003כך שמעתי מאחורי הפרגוד\u0004 (המסך, שבין ה' למלאכי השרת): \u0003השה לעולה ואין יצחק לעולה. אמר לו\u0004 אברהם: אולי נכונים הדברים, ואולם \u0003כך עונשו של בדאי, שאפילו אמר אמת אין שומעין לו\u0004 ולכן אין אני מאמינך, ועושה כפי שאמר לי ה'.","\u0003ר' לוי אמר:\u0004 \"אחר הדברים\" פירושו \u0003אחר דבריו של ישמעאל ליצחק\u0004 שנראה שהיו ביניהם סכסוכים (\"ותרא שרה את בן הגר המצרית מצחק\". בראשית כא, ט). \u0003אמר לו ישמעאל ליצחק: אני גדול ממך ב\u0004שמירת \u0003מצות, שאתה מלת בן שמנת ימים\u0004 שלא מדעתך ולא מרצונך \u0003ואני בן שלש עשרה שנה\u0004 כגדול קיבלתי על עצמי ונימולתי. \u0003אמר לו\u0004 יצחק לישמעאל: \u0003ובאבר אחד אתה מגרה בי\u0004 ומראה גדולתך עלי? \u0003אם אומר לי הקדוש ברוך הוא \"זבח עצמך לפני\"\u0004 — \u0003אני זובח. מיד \"והאלהים נסה את אברהם\"\u0004 כדי שיתאמת הדבר שיצחק מוכן למסור נפשו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נביא שהדיח\u0004 לעבודה זרה נידון \u0003בסקילה. ר' שמעון אומר: בחנק. מדיחי עיר הנדחת\u0004 נידונים כשאר מסיתים \u0003בסקילה. ר' שמעון אומר: בחנק.\u0004","ומבארים: \u0003נביא שהדיח\u0004 נידון \u0003בסקילה. מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]?\u0006 — \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה מלשונות \u0003\"הדחה\" \"הדחה\"\u0004 שיש גם בעיר הנדחת וגם במסית, ולומדים \u0003ממסית\u0004 סתם. \u0003מה להלן\u0004 מסית סתם נידון \u0003בסקילה\u0004 — \u0003אף כאן\u0004 נידון \u0003בסקילה.\u0004","\u0003ור' שמעון\u0004 אומר: כאן לגבי נביא המנבא בשם עבודה זרה \u0003מיתה\u0004 סתם \u0003כתיבא ביה\u0004 \u0005[כתובה בו],\u0006 \u0003וכל מיתה האמורה בתורה סתם אינה אלא חנק.\u0004","\u0003מדיחי עיר הנדחת בסקילה, מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]?\u0006 — \u0003גמירי\u0004 \u0005[לומדים הם]\u0006 גזירה שווה מלשונות \u0003\"הדחה\" \"הדחה\" או ממסית\u0004 אחר \u0003או מ\u0004דין \u0003נביא שהדיח.\u0004","\u0003ור' שמעון:\u0004 הוא \u0003גמר\u0004 \u0005[למד]\u0006 \u0003\"הדחה\" \"הדחה\"\u0004 בגזירה שווה \u0003מנביא\u0004 שהסית שמיתתו בחנק.","ושואלים: \u0003וליגמר\u0004 \u0005[ושילמד]\u0006 ר' שמעון \u0003ממסית\u0004 שהוא דומה יותר! ומשיבים: \u0003דנין מסית\u0004 את ה\u0003רבים ממסית\u0004 את ה\u0003רבים, ואין דנין מסית\u0004 את ה\u0003רבים ממסית\u0004 את ה\u0003יחיד.\u0004 ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003דנין הדיוט,\u0004 כלומר, סתם מסית, \u0003מהדיוט\u0004 ממדיחי עיר הנדחת שאף הם הדיוטות, \u0003ואין דנין הדיוט מנביא\u0004 שמן הסתם יש לו דין אחר!","\u0003ור' שמעון\u0004 סבור כי אין מקום להבדל זה, ש\u0003כיון שהדיח\u0004 — \u0003אין לך הדיוט גדול מזה.\u0004","\u0003אמר רב חסדא:\u0004"],["\u0003מחלוקת\u0004 זו היא \u0003ב\u0004נביא ש\u0003עוקר הגוף\u0004 (עיקר האיסור) של \u0003עבודה זרה,\u0004 כלומר, שביטל איסור עבודה זרה, או \u0003קיום מקצת וביטול מקצת\u0004 של \u0003עבודה זרה,\u0004 שאף שמודה שעבודה זרה אסורה מתיר הוא לעובדה במקרה מסויים. \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 בענין נביא המנבא שיש לעבוד עבודה זרה: \"והנביא ההוא... יומת, כי דבר סרה על ה'... להדיחך \u0003מן הדרך\u0004 אשר צוך ה' אלהיך ללכת בה\" (דברים יג, ו), והלשון \"מן\" משמעו — \u0003אפילו מקצת הדרך.\u0004","\u0003אבל עוקר\u0004 את \u0003הגוף\u0004 של \u0003שאר מצות,\u0004 שמנבא לבטלן מעיקרן — \u0003דברי הכל\u0004 נביא שקר הוא ודינו \u0003בחנק. וקיום מקצת וביטול מקצת\u0004 ש\u0003בשאר מצות\u0004 — \u0003דברי הכל פטור,\u0004 ואם נביא אמת הוא צריך לשמוע בקולו לבטל מצוה מסויימת לפי שעה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא\u0004 על כך ממה ששנינו בברייתא הדורשת כתוב זה \"להדיחך מן הדרך אשר צוך ה' אלהיך ללכת בה\" (דברים יג, ו): \u0003\"ללכת\"\u0004 — \u0003זו מצות \"עשה\". \"בה\"\u0004 — \u0003זו מצות \"לא תעשה\". ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לפרש כי מדובר כאן \u0003בעבודה זרה,\u0004 מצות \u0003\"עשה\" בעבודה זרה\u0004 \u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]?\u0006 והלא איסור עבודה זרה אינו אלא מצות \"לא תעשה\"! ומשיבים: \u0003תרגמה\u0004 \u0005[הסבירה]\u0006 \u0003רב חסדא:\u0004 במצות עשה של \u0003\"ונתצתם\u0004 את מזבחותם ושברתם את מצבותם ואשריהם תשרפון באש ופסילי אלהיהם תגדעון ואבדתם את שמם מן המקום ההוא\u0003\"\u0004 (דברים יב, ג), שאותו נביא אומר לבטלה. אף שקושיית רב המנונא נדחתה, מכל מקום הוא מפרש בדרך אחרת, \u0003רב\u0004","\u0003המנונא אמר: מחלוקת בעוקר הגוף, בין בעבודה זרה בין בשאר מצות, וקיום מקצת וביטול מקצת\u0004 שב\u0003עבודה זרה. דרחמנא אמר\u0004 \u0005[שהתורה אמרה]:\u0006 \u0003\"\u0004וסרתם \u0003מן הדרך\"\u0004 (דברים יא, כח), לומר: \u0003אפילו מקצת הדרך.\u0004","\u0003אבל קיום מקצת וביטול מקצת\u0004 ש\u0003בשאר מצות\u0004 — \u0003דברי הכל פטור,\u0004 שזה בגדר רשות הנביא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המתנבא לעקור דבר מן התורה\u0004 — \u0003חייב\u0004 מיתה בחנק כנביא שקר. והמתנבא \u0003לקיים\u0004 \u0003מקצת ולבטל מקצת\u0004 — \u0003ר' שמעון פוטר. ובעבודה זרה, אפילו אומר\u0004 הנביא: \u0003\"\u0004רק \u0003היום עיבדוה ולמחר בטלוה\"\u0004 — \u0003דברי הכל חייב.\u0004","ומסבירים: \u0003אביי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כרב חסדא, ומתרץ לה\u0004 \u0005[ומיישב אותה,\u0006 את הברייתא\u0005]\u0006 \u0003כ\u0004שיטת \u0003רב חסדא,\u0004 ואילו \u0003רבא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כרב המנונא ומתרץ לה\u0004 \u0005[ומיישב אותה]\u0006 את הברייתא \u0003כ\u0004שיטת \u0003רב המנונא.\u0004","ובאופן זה: \u0003אביי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כרב חסדא, ומתרץ לה\u0004 \u0005[ומיישב אותה]\u0006 \u0003כ\u0004שיטת \u0003רב חסדא\u0004 כך: \u0003המתנבא לעקור דבר מן התורה\u0004 בכל מצוה — \u0003דברי הכל\u0004 נידון \u0003ב\u0004מיתת \u0003חנק,\u0004 והמתנבא \u0003לקיים\u0004 \u0003מקצת ולבטל מקצת\u0004 — \u0003ר' שמעון פוטר, והוא הדין לרבנן\u0004 \u0005[לחכמים]\u0006 שאף הם סבורים שפטור. \u0003ו\u0004אילו \u0003בעבודה זרה, אפילו אמר \"היום עיבדוה ולמחר בטלוה\"\u0004 — \u0003חייב. מר כדאית ליה\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005כפי שיש להם]\u0006 דעה שיש לעונשו בסקילה, \u0003ומר כדאית ליה\u0004 \u0005[וחכם זה,\u0006 ר' שמעון, \u0005כפי שיש לו]\u0006 דעה אחרת בדבר עונשו של נביא המסית.","ואילו \u0003רבא סבר לה\u0004 בענין זה \u0003כרב המנונא, ומתרץ לה\u0004 \u0005[ומיישב אותה]\u0006 \u0003כ\u0004שיטת \u0003רב המנונא\u0004 כך: \u0003המתנבא לעקור דבר מן התורה, בין בעבודה זרה בין בשאר מצות\u0004 — \u0003חייב, מר כדאית ליה, ומר כדאית ליה\u0004 \u0005[חכם זה כמו שיש לו\u0006 דעה בהלכה זו, \u0005וחכם זה כמו שיש לו\u0006 דעה אחרת בהלכה זו\u0005].\u0006 המתנבא \u0003לקיים מקצת ולבטל מקצת בשאר מצות\u0004 — \u0003ר' שמעון פוטר, והוא הדין לרבנן\u0004 \u0005[לחכמים]\u0006 שאף הם פוטרים בכך. \u0003ובעבודה זרה, אפילו אומר \"היום עיבדוה ולמחר בטלוה\"\u0004 — \u0003חייב, מר כדאית ליה, ומר כדאית ליה\u0004 \u0005[חכם זה,\u0006 ר' שמעון, \u0005כפי שיש לו, וחכם זה,\u0006 חכמים, \u0005כפי שיש לו],\u0006 ואם כן אין ראיה ברורה מן הברייתא לכל צד.","\u0003אמר ר' אבהו אמר ר' יוחנן\u0004 סיכום להלכות אלה: \u0003בכל\u0004 מצוות התורה, \u0003אם יאמר לך נביא \"עבור\u0004 לפי שעה \u0003על דברי תורה\"\u0004 — \u0003שמע לו, חוץ מעבודה זרה, שאפילו\u0004 מראה אותות מופלאים ואף \u0003מעמיד לך חמה באמצע הרקיע\u0004 — \u0003אל תשמע לו,\u0004 שכבר הזהירה התורה שנביא שקר הוא. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: הגיע תורה לסוף דעתה של עבודה זרה\u0004 כמה היא מסוכנת וכמה גדול פיתויה, \u0003לפיכך נתנה תורה ממשלה בה,\u0004 שגם אם יש בידה כוח להראות אותות מופלאים, \u0003שאפילו מעמיד לך\u0004 נביא שקר \u0003חמה באמצע הרקיע\u0004 — \u0003אל תשמע לו.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' עקיבא: חס ושלום שהקדוש ברוך הוא מעמיד חמה לעוברי רצונו\u0004 ובודאי לא יוכל נביא עבודה זרה לעשות מופת אמיתי כלל, \u0003אלא כגון חנניה בן עזור שמתחלתו נביא אמת\u0004 היה, ואז יתכן שנעשו לו אותות גדולים משמים לאמת את נבואתו, \u0003ולבסוף\u0004 נעשה \u0003נביא שקר,\u0004 ולכן אף שהיה מוחזק כנביא, אם ינבא לעבוד עבודה זרה — יש לדעת שהוא משקר.","שנינו במשנה כי \u0003זוממי בת כהן\u0004 ובועלה נידונים בחנק, ולא בשריפה כמותה! ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה],\u0006 מה מקורם במקרא? \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: מה תלמוד לומר\u0004 בכתוב המדבר בעדים זוממים \u0003\"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט)? — \u0003לפי שכל המזוממין שבתורה\u0004 בדיני ערוה למשל \u0003זוממיהן ובועליהן כיוצא בהן,\u0004 שנידונים כל השותפים לעבירה וכן העדים הזוממים באותה מיתה שהוא חנק.","ואולם \u0003בת כהן\u0004 יצאה מכללם, ש\u0003היא\u0004 נידונה \u0003בשריפה ואין בועלה\u0004 נידון \u0003בשריפה,\u0004 וכיון שנתחלק העונש על עבירה זו, הרי \u0003זוממין, איני יודע אם לו\u0004 (לבועל) \u0003הוקשו\u0004 (הושוו) בדינם \u0003אם לה הוקשו\u0004 (הושוו)?! \u0003כשהוא אומר\u0004 ומדגיש \u0003\"לעשות לאחיו\"\u0004 הרי יש לדייק ולומר: \u0003לאחיו ולא לאחותו,\u0004 כלומר, דנים אותם במיתה שזממו להמית את הבועל ולא את הנבעלת.","\u0005הדרן עלך אלו הן הנחנקין\u0006","\u0003כל ישראל\u0004 ואפילו עבריינים וחייבי מיתות בית דין \u0003יש להם חלק לעולם הבא, שנאמר: \"ועמך כלם צדיקים לעולם יירשו ארץ נצר מטעי מעשה ידי להתפאר\"\u0004 (ישעיה ס, כא), ורק אנשים בודדים המיוחדים ברשעם יוצאים מכלל זה. \u0003ואלו שאין להם חלק לעולם הבא\u0004 אף שיש בידם מצוות רבות אחרות: \u0003האומר \"אין תחיית המתים מן התורה\",\u0004 שכופר שיחיו המתים ברצות ה' לעתיד לבוא. \u0003ו\u0004האומר: \u0003\"אין תורה מן השמים\", ואפיקורוס\u0004 המבזה חכמי ישראל ותורתם.","\u0003ר' עקיבא אומר: אף הקורא בספרים החיצונים, ו\u0004כן \u0003הלוחש על המכה\u0004 (הפצע) \u0003ואומר\u0004 כסגולה: \u0003\"כל המחלה אשר שמתי במצרים לא אשים עליך כי אני ה' רפאך\"\u0004 \u0005(שמות טו, כו)\u0006, שבכך הוא מזלזל בקדושת השם ולכך אין לו חלק לעולם הבא. \u0003אבא שאול אומר: אף ההוגה את השם\u0004 המפורש \u0003באותיותיו.\u0004","\u0003שלשה מלכים\u0004 חשובים המנויים במקרא, \u0003וארבעה הדיוטות\u0004 חשובים שזכו לרוב חכמה המוזכרים במקרא \u0003אין להן חלק לעולם הבא. שלשה מלכים\u0004 הם: \u0003ירבעם\u0004 בן נבט, \u0003אחאב, ומנשה\u0004 מלך יהודה. \u0003ר' יהודה אומר: מנשה יש לו חלק לעולם הבא, שנאמר: \"ויתפלל אליו\u0004 ויעתר לו \u0003וישמע תחנתו וישיבהו ירושל ם למלכותו\"\u0004 (דברי הימים ב' לג, יג), הרי שעשה תשובה גדולה והועילה לו! \u0003אמרו לו:\u0004 אמנם התחרט מנשה ותשובתו הועילה ש\u0003למלכותו השיבו, ו\u0004אולם \u0003לא לחיי העולם הבא השיבו. ארבעה הדיוטות\u0004 הם: \u0003בלעם\u0004 בן בעור, \u0003ודואג\u0004 האדומי, \u0003ואחיתופל, וגחזי.\u0004","על האמור במשנה שואלים: \u0003וכל כך למה\u0004 נענש האומר שאין תחיית המתים? \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003הוא כפר בתחיית המתים, לפיכך לא יהיה לו חלק בתחיית המתים.\u0004 לפי הכלל \u0003שכל מדותיו של הקדוש ברוך הוא\u0004 שבהן הוא מודד לבריות, הריהן \u0003מדה כנגד מדה,\u0004 שהעונש הוא תמיד מעין העבירה.","ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מניין שכל מדותיו של הקדוש ברוך הוא מדה כנגד מדה?\u0004 — \u0003שנאמר: \"ויאמר אלישע שמעו דבר ה'\u0004 כה אמר ה' \u0003כעת מחר סאה סלת בשקל וסאתים שערים בשקל בשער שמרון\"\u0004 (מלכים ב' ז, א), \u0003וכתיב \"ויען השליש אשר המלך נשען על ידו את איש האלהים ויאמר הנה ה' עשה ארבות בשמים היהיה הדבר הזה ויאמר הנכה ראה בעיניך ומשם לא תאכל\"\u0004 (מלכים ה' ז, ב),"],["\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי לו כן וירמסו אתו העם בשער וימת\"\u0004 (מלכים ב' ז, כ). ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003קללת אלישע גרמה ליה\u0004 \u0005[לו]\u0006 שימות כך, ולא מדה כנגד מדה על כפירתו? שהרי \u0003אמר רב יהודה אמר רב: קללת חכם, אפילו על חנם\u0004 (גם אם לא היתה מוצדקת), \u0003היא באה\u0004 ומתקיימת, וכל שכן קללת אלישע שבדין קללו! ומשיבים: \u0003אם כן לכתוב קרא\u0004 \u0005[שיכתוב המקרא]:\u0006 \u0003\"וירמסוהו וימת\", מאי\u0004 \u0005[מה]\u0006 משמעות תוספת ההדגשה \u0003\"בשער\",\u0004 ללמד: \u0003על עסקי שער,\u0004 על שלגלג ואמר שגם אם יפתח ה' שערים בשמים לא יהא כן, ולכן נענש מדה כנגד מדה.","\u0003אמר ר' יוחנן: מניין לתחיית המתים מן התורה?\u0004 — \u0003שנאמר\u0004 בתרומת מעשר: \u0003\"ונתתם ממנו את תרומת ה' לאהרן הכהן\"\u0004 (במדבר יח, כח), \u0003וכי אהרן\u0004 עצמו \u0003לעולם קיים\u0004 שתקויים מצוה זו בו? \u0003והלא לא נכנס\u0004 אהרן עצמו \u0003לארץ ישראל,\u0004 מקום \u0003שנותנין לו תרומה,\u0004 ונמצא שלא התקיים בו הכתוב כלל! \u0003אלא מלמד שעתיד\u0004 אהרן \u0003לחיות\u0004 לעתיד לבוא, \u0003וישראל נותנין לו תרומה\u0004 — \u0003מכאן לתחיית המתים מן התורה.\u0004","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנינו]\u0006 מדרש אחר על אותו כתוב: \u0003\"לאהרן\"\u0004 — כוונתו \u0003כאהרן, מה אהרן חבר\u0004 (תלמיד חכם) — \u0003אף בניו חברים,\u0004 שיש להקפיד ולתת מתנות כהונה רק לכהן תלמיד חכם.","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מניין שאין נותנין תרומה לכהן עם הארץ?\u0004 — \u0003שנאמר: \"ויאמר לעם ליושבי ירושל ם לתת מנת הכהנים והלוים למען יחזקו בתורת ה' \"\u0004(דברי הימים ב' לא, ד), משמע ש\u0003כל המחזיק בתורת ה'\u0004 — \u0003יש לו מנת, ושאינו מחזיק בתורת ה'\u0004 — \u0003אין לו מנת.\u0004","\u0003אמר רב אחא בר אדא אמר רב יהודה: כל הנותן תרומה לכהן עם הארץ כאילו נותנה לפני ארי, מה ארי ספק דורס\u0004 (הורג במכה) \u0003ואוכל, ספק אינו דורס ואוכל\u0004 ומניח את טרפו חי — \u0003אף כהן עם הארץ\u0004 שניתנה לו תרומה, \u0003ספק אוכלה בטהרה\u0004 כראוי, \u0003ספק אוכלה בטומאה\u0004 ובאיסור חמור.","\u0003ר' יוחנן אמר: אף גורם לו\u0004 לכהן זה \u0003מיתה, שנאמר\u0004 בדיני תרומות: \u0003\"ומתו בו כי יחללהו\"\u0004 (ויקרא כב, ט), ללמד שאם יאכלו הכהנים תרומתם בטומאה ויחללוה על ידי כך, חייבים הם מיתה לשמים. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר בן יעקב תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אף משיאו עון אשמה, שנאמר: \"והשיאו אותם עון אשמה באכלם את קדשיהם\"\u0004 (שם טז).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' סימאי אומר: מניין לתחיית המתים מן התורה?\u0004 — \u0003שנאמר\u0004 על אבות האומה: \u0003\"וגם הקמתי את בריתי אתם לתת להם את ארץ כנען\"\u0004 (שמות ו, ד). \u0003\"לכם\" לא נאמר,\u0004 שאין הכוונה לומר שהתקיימה ברית האבות בנתינת הארץ לבני ישראל, \u0003אלא \"להם\"\u0004 לאבות עצמם — \u0003מכאן לתחיית המתים מן התורה\u0004 שעתידים הם לחיות ולרשת את הארץ ויתקיימו בהם דברי ה'.","\u0003(צד\"ק ג\"ם גש\"ם קם סימן). שאלו מינין את רבן גמליאל: מניין שהקדוש ברוך הוא מחייה מתים?\u0004 הביא ו\u0003אמר להם\u0004 ראיות \u0003מן התורה, ומן הנביאים, ומן הכתובים, ולא קיבלו ממנו.\u0004","\u0003מן התורה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ה' אל משה הנך שכב עם אבתיך וקם\"\u0004 (דברים לא, טז), \u0003אמרו לו: ודילמא\u0004 \u0005[ושמא]\u0006 אין ההפסק בכתוב כפי שאתה עושה וצריך לקרוא \u0003\"וקם העם הזה וזנה\u0004 אחרי אלהי נכר הארץ","\u0003\"\u0004(דברים לא, טז). הביא להם ראיה \u0003מן הנביאים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יחיו מתיך נבלתי יקומון הקיצו ורננו שכני עפר כי טל אורת טלך וארץ רפאים תפיל\"\u0004 (ישעיה כו, יט). אמרו לו: משם אין ראיה לתחיית מתים לעתיד, \u0003ודילמא\u0004 \u0005[ושמא]\u0006 מדובר רק ב\u0003מתים שהחיה יחזקאל?\u0004","הביא להם עוד ראיה \u0003מן הכתובים,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וחכך כיין הטוב הולך לדודי למישרים דובב שפתי ישנים\"\u0004 (שיר השירים ז, י), כלומר, לעתיד לבוא יחיו וידובבו שפתי ישני עפר. אמרו לו: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003רחושי מרחשן שפוותיה בעלמא\u0004 \u0005[רוחשות שפתותיהם בלבד]\u0006 בלא קשר לתחייה, ו\u0003כ\u0004פי שאמר \u0003ר' יוחנן.\u0004 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: כל מי שנאמרה הלכה בשמו בעולם הזה, שפתותיו דובבות\u0004 (נעות) \u0003בקבר\u0004 כחוזר ואומר אימרה זו, \u0003שנאמר: \"דובב שפתי ישנים\".\u0004","\u0003עד שאמר להם\u0004 רבן גמליאל \u0003מקרא זה\u0004 כראיה: \u0003\"\u0004למען ירבו ימיכם וימי בניכם על האדמה \u0003אשר נשבע ה' לאבתיכם לתת להם\"\u0004 (דברים יא, כא), \u0003\"לכם\" לא נאמר אלא \"להם\",\u0004 שעתידים האבות לחיות ולרשת את הארץ — \u0003מיכן לתחיית המתים מן התורה.\u0004","\u0003ויש אומרים\u0004 כי \u0003מן המקרא הזה אמר להם: \"ואתם הדבקים בה' אלהיכם חיים כלכם היום\"\u0004 (דברים ד, ד), והרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 ש\u0003\"חיים כלכם היום\",\u0004 שהרי הוא פונה לאנשים חיים ומדבר אליהם, \u0003אלא אפילו ביום שכל העולם כולם מתים אתם חיים,\u0004 כלומר, \u0003מה היום כולכם קיימין\u0004 — \u0003אף לעולם הבא כולכם קיימין.\u0004","\u0003שאלו רומיים את ר' יהושע בן חנניה: מניין שהקדוש ברוך הוא מחיה מתים, ו\u0004מנין שהוא \u0003יודע מה שעתיד להיות? אמר להו\u0004 \u0005[להם]:\u0006 \u0003תרווייהו\u0004 \u0005[שניהם]\u0006 למדים \u0003מן המקרא הזה, שנאמר: \"ויאמר ה' אל משה הנך שכב עם אבתיך וקם העם הזה וזנה\"\u0004 (דברים לא, טז), הרי שנאמר שימות משה ויקום, ומכאן לתחיית המתים ולידיעת הקדוש ברוך הוא את העתיד להיות.","והקשו לו: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 יש לקרוא: \u0003\"וקם העם הזה וזנה\"? אמר להו\u0004 \u0005[להם]:\u0006 \u0003נקוטו מיהא פלגא בידייכו\u0004 \u0005[החזיקו על כל פנים חצי בידכם],\u0006 כי מכאן נלמד לפחות ש\u0003יודע\u0004 ה' \u0003מה שעתיד להיות. איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כעין זה בשם אמוראים, \u0003אמר ר' יוחנן משום ר' שמעון בן יוחאי: מניין שהקדוש ברוך הוא מחיה מתים, ויודע מה שעתיד להיות?\u0004 — \u0003שנאמר: \"הנך שכב עם אבתיך וקם\".\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' אליעזר בר' יוסי: בדבר זה זייפתי,\u0004 כלומר, הוכחתי את שקרם של \u0003ספרי כותים, שהיו אומרים אין תחיית המתים מן התורה. אמרתי להן: זייפתם תורתכם, ולא העליתם בידכם כלום. שאתם אומרים אין תחיית המתים מן התורה, הרי הוא אומר \"הכרת תכרת הנפש ההוא עונה בה\"\u0004 (במדבר טו, לא). \u0003\"הכרת תכרת\"\u0004 אתם מבינים שימות האדם \u0003בעולם הזה. \"עונה בה\"\u0004 — \u0003לאימת\u0004 \u0005[לאימתי]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003לעולם הבא,\u0004 הרי שיש עולם הבא, והוא רמוז בתורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ולימא להו תרוייהו\u0004 \u0005[ושיאמר להם\u0006 את \u0005שני\u0006 הדברים\u0005]\u0006 \u0003מ\"הכרת תכרת\"!\u0004 כפי הדרשה: \"הכרת\" — בעולם הזה, \"תכרת\" — לעולם הבא! ומשיבים: \u0003אינהו הוו אמרי ליה\u0004 \u0005[הם היו אומרים לו]:\u0006 \u0003דברה תורה כלשון בני אדם\u0004 ואין להוכיח דבר מן הלשון הכפולה.","ומעירים: דבר זה הוא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שבאמת נחלקו באותו כתוב, ששנינו: כוונת הכתוב \u0003\"הכרת תכרת\"\u0004 היא: \u0003\"הכרת\"\u0004 — \u0003בעולם הזה, \"תכרת\"\u0004 — \u0003לעולם הבא,\u0004 אלו \u0003דברי ר' עקיבא. אמר לו ר' ישמעאל: והלא כבר נאמר\u0004 בהמשך הענין לשון נוספת של כריתות, \u0003\"את ה' הוא מגדף ונכרתה\"\u0004 (במדבר טו, ל), \u0003וכי שלשה עולמים יש? אלא \"ונכרתה\"\u0004 פירושו — \u0003בעולם הזה, \"הכרת\"\u0004 — \u0003לעולם הבא,\u0004 והחזרה \u0003\"הכרת תכרת\"\u0004 אינה באה ללמד דבר, כי \u0003דברה תורה כלשון בני אדם\u0004 בלשונות כפולים אלה.","ושואלים: \u0003בין\u0004 ל\u0003ר' ישמעאל ובין\u0004 ל\u0003ר' עקיבא \"עונה בה\" מאי עבדי ביה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 מה משמעות כתוב זה לשיטתם? ומשיבים: \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול\u0004 יענש בכרת \u0003אפילו עשה תשובה?\u0004 — \u0003תלמוד לומר \"עונה בה\"\u0004 — \u0003לא אמרתי\u0004 שייענש כך \u0003אלא בזמן ש\u0004עדיין \u0003עונה בה.\u0004","מספרים: \u0003שאלה קליאופטרא מלכתא\u0004 \u0005[המלכה]\u0006 \u0003את ר' מאיר, אמרה: ידענא דחיי שכבי\u0004 \u0005[יודעת אני שהמתים יחיו],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויציצו מעיר כעשב הארץ\"\u0004 (תהלים עב, טז), שכשם שצומח העשב כן יחזרו המתים לחיים. \u0003אלא כשהן עומדין,\u0004 האם הם \u0003עומדין ערומין או בלבושיהן עומדין? אמר לה: קל וחומר מחיטה, ומה חיטה שנקברה ערומה,\u0004 כלומר, בלא מוץ וכיסוי, הריהי \u0003יוצאה\u0004 כשהיא צומחת \u0003בכמה לבושין\u0004 של קש, \u0003צדיקים שנקברים בלבושיהן — על אחת כמה וכמה\u0004 שיקומו לבושים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לרבן גמליאל: אמריתו דשכבי חיי\u0004 \u0005[אומרים אתם שהמתים יחיו],\u0006 \u0003הא הוו עפרא\u0004 \u0005[\u0006ו\u0005הרי הם נעשים עפר],\u0006 \u0003ועפרא מי\u0004 \u0003קא חיי\u0004 \u0005[ועפר האם יכול הוא לחיות]?\u0006"],["\u0003אמרה ליה ברתיה\u0004 \u0005[לו בתו]\u0006 של הקיסר לרבן גמליאל: \u0003שבקיה ואנא מהדרנא ליה\u0004 \u0005[הניחנו ואני אשיב לו]\u0006 במשל. \u0003שני יוצרים\u0004 של כלי חרס \u0003יש בעירנו, אחד\u0004 מהם \u0003יוצר\u0004 כלים \u0003מן המים, ואחד יוצר מן הטיט, איזה מהן משובח? אמר לה: זה שיוצר מן המים. אמרה לו:\u0004 אם \u0003מן המים צר, מן הטיט לא כל שכן\u0004 שיוכל לעשות כלי, שאם ברא ה' את כל העולם מן המים, ודאי שיוכל לברוא בני אדם שוב מן העפר.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 \u0003קל וחומר\u0004 הדבר \u0003מכלי זכוכית; מה כלי זכוכית שעמלן\u0004 (שעשייתם) \u0003ברוח בשר ודם,\u0004 שהרי נופחים אותם והם נעשים כלים, ואם \u0003נשברו יש להן תקנה,\u0004 שיכולים להתיכם ולחזור ולעשותם כלים, \u0003בשר ודם ש\u0004נפש חייו היא מנפיחת \u0003רוחו של הקדוש ברוך הוא\u0004 — \u0003על אחת כמה וכמה.\u0004","מסופר, \u0003אמר ליה ההוא מינא\u0004 \u0005[לו מין אחד]\u0006 \u0003לר' אמי: אמריתו דשכבי חיי\u0004 \u0005[אומרים אתם שהמתים יחיו],\u0006 \u0003והא הוו עפרא, ועפרא מי קא חיי\u0004 \u0005[והרי נעשו עפר, ועפר האם חי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמשול לך משל, למה הדבר דומה?\u0004 — \u0003למלך בשר ודם שאמר לעבדיו: לכו ובנו לי פלטרין\u0004 (ארמונות) \u0003גדולים במקום שאין\u0004 שם \u0003מים ועפר, הלכו ובנו אותו. לימים\u0004 (לאחר זמן) \u0003נפלו\u0004 הארמונות. \u0003אמר להם: חזרו ובנו אותו במקום שיש עפר ומים. אמרו לו: אין אנו יכולין.\u0004","\u0003כעס עליהם\u0004 המלך \u0003ואמר להן: במקום שאין מים ועפר\u0004 — \u0003בניתם, עכשיו שיש מים ועפר\u0004 — \u0003על אחת כמה וכמה!\u0004 ואם תחילת יצירת האדם היא מאין, כל שכן שיכול להיווצר מעפרו. \u0003ואם אי אתה מאמין\u0004 שאפשר ליצור מן העפר \u0003צא לבקעה\u0004 (לשדה) \u0003וראה עכבר שהיום\u0004 עדיין \u0003חציו בשר וחציו אדמה,\u0004 ו\u0003למחר השריץ ונעשה כלו בשר. שמא תאמר\u0004 הלא ענין זה הוא \u0003לזמן מרובה,\u0004 אם כן \u0003עלה להר וראה שהיום אין בו אלא חלזון אחד,\u0004 ו\u0003למחר ירדו גשמים ונתמלא כולו חלזונות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לגביהא בן פסיסא: ווי לכון חייביא, דאמריתון \"מיתי חיין\"\u0004 \u0005[אוי לכם חייבים,\u0006 רשעים, \u0005שאומרים אתם\u0006 ש\u0005המתים יחיו],\u0006 והלא אפילו אלו \u0003דחיין, מיתי\u0004 \u0005[שחיים, מתים],\u0006 ואומר אתה \u0003דמיתי חיין\u0004 \u0005[שהמתים יחיו]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 גביהא בן פסיסא: \u0003ווי לכון חייביא, דאמריתון \"מיתי לא חיין\"\u0004 \u0005[אוי לכם חייבים,\u0006 רשעים, \u0005שאומרים אתם\u0006 ש\u0005המתים לא יחיו],\u0006 והלא אלה ש\u0003לא הוו\u0004 \u0005[היו]\u0006 מעולם חיים — \u0003חיי\u0004 \u0005[\u0006נבראים ו\u0005חיים\u0006 מחדש\u0005],\u0006 אלה \u0003דהוי חיי\u0004 \u0005[אלו שהיו חיים\u0006 פעם\u0005]\u0006 \u0003לא כל שכן\u0004 שהם יכולים לחיות? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו מין בכעס: \u0003חייביא קרית לי\u0004 \u0005[חייב,\u0006 רשע, \u0005אתה קורא לי]?!\u0006 \u0003אי קאימנא, בעיטנא\u0004 \u0005[אם אקום, אבעט]\u0006 \u0003בך ופשיטנא לעקמותך מינך\u0004 \u0005[ואפשוט את גבנונך ממך],\u0006 שגביהא בן פסיסא גיבן היה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בבדיחות הדעת: \u0003אם אתה עושה כן\u0004 ותפשוט את עקמומיתי \u0003\"רופא אומן\" תקרא, ושכר הרבה תטול.\u0004","כיון שהוזכר גביהא בן פסיסא ויכולתו הרבה בוויכוח מביאים עוד מעשיות על וויכוחים שהתווכח בשם עם ישראל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במגילת תענית: \u0003בעשרים וארבעה בניסן\u0004 יום של שמחה, כי \u0003איתנטילו דימוסנאי\u0004 \u0005[סולקו מערערים ושליטים]\u0006 \u0003מיהודה ומירושלים.\u0004 וזה המעשה: \u0003כשבאו בני אפריקיא לדון עם ישראל לפני\u0004 הקיסר \u0003אלכסנדרוס מוקדון, אמרו לו: ארץ כנען שלנו היא, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004זאת הארץ אשר תפול לכם בנחלה \u0003ארץ כנען לגבלתיה\"\u0004 (במדבר לד, ב), \u0003וכנען אבוהון דהנהו אינשי הוה\u0004 \u0005[אביהם של אותם אנשים,\u0006 כלומר שלנו, \u0005היה].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003גביהא בן פסיסא לחכמים: תנו לי רשות ואלך\u0004 אני \u0003ואדון עמהן לפני אלכסנדרוס מוקדון, אם ינצחוני\u0004 בויכוח \u0003אמרו\u0004 למלך: \u0003הדיוט שבנו נצחתם\u0004 ועדיין יש לכם להתווכח עם חכמי ישראל, \u0003ואם אני אנצח אותם אמרו להם: תורת משה נצחתכם\u0004 ולא תתלו את הגדולה בי. \u0003נתנו לו רשות, והלך ודן עמהם.\u0004","\u0003אמר להם: מהיכן אתם מביאים ראייה\u0004 שהארץ שלכם? \u0003אמרו לו\u0004 \u0003:\u0004 \u0003מן התורה. אמר להן: אף אני לא אביא לכם ראייה אלא מן התורה, שנאמר\u0004 בתורה: \u0003\"ויאמר ארור כנען עבד עבדים יהיה לאחיו\"\u0004 (בראשית ט, כה), וכלל הוא שכל \u0003עבד שקנה נכסים\u0004 — ה\u0003עבד למי\u0004 שייך, וה\u0003נכסים למי?\u0004 הלא הכל לאדוניו ולא לו. \u0003ולא עוד אלא שהרי כמה שנים שלא עבדתונו,\u0004 וחייבים אתם להחזיר אף נכסיהם האחרים לנו ולשוב לעבדות.","\u0003אמר להם אלכסנדרוס מלכא\u0004 \u0005[המלך]:\u0006 \u0003החזירו לו תשובה! אמרו לו: תנו לנו זמן שלשה ימים\u0004 להרהר בדבר. \u0003נתן להם זמן, בדקו\u0004 ועיינו \u0003ולא מצאו תשובה. מיד ברחו, והניחו שדותיהן כשהן זרועות, וכרמיהן כשהן נטועות.\u0004 ומעירים: \u0003ואותה שנה שביעית\u0004 (שמיטה) \u0003היתה\u0004 ונהנו ישראל משדות אלה, שהם עצמם היו בדוחק מפני שמירת השמיטה.","ועוד מסופר: \u0003שוב פעם אחת באו בני מצרים לדון עם ישראל לפני אלכסנדרוס מוקדון. אמרו לו: הרי הוא אומר\u0004 בתורה \u0003\"וה' נתן את חן העם בעיני מצרים וישאילום\"\u0004 (שמות יב, לו) — \u0003תנו לנו כסף וזהב שנטלתם ממנו\u0004 בהשאלה ולא החזרתם.","\u0003אמר גביהא בן פסיסא לחכמים: תנו לי רשות ואלך ואדון עמהן לפני אלכסנדרוס, אם ינצחוני אמרו להם: הדיוט שבנו נצחתם, ואם אני אנצח אותם אמרו להם: תורת משה רבינו נצחתכם. נתנו לו רשות והלך ודן עמהן,\u0004","\u0003אמר להן: מהיכן אתם מביאין ראייה? אמרו לו: מן התורה. אמר להן: אף אני לא אביא לכם ראייה אלא מן התורה, שנאמר: \"ומושב בני ישראל אשר ישבו במצרים שלשים שנה וארבע מאות שנה\"\u0004 (שם מ), והיו משועבדים למצרים בעבודת פרך, \u0003תנו לנו שכר עבודה של ששים ריבוא\u0004 נפש (של יוצאי מצרים), \u0003ששיעבדתם במצרים שלשים שנה וארבע מאות שנה.\u0004","\u0003אמר להן אלכסנדרוס מוקדון: החזירו לו תשובה! אמרו לו: תנו לנו זמן שלשה ימים\u0004 להרהר בדבר. \u0003נתן להם זמן, בדקו ולא מצאו תשובה. מיד הניחו שדותיהן כשהן זרועות, וכרמיהן כשהן נטועות וברחו.\u0004 ומעירים: \u0003ואותה שנה שביעית היתה\u0004 ונהנו מכך ישראל.","\u0003ושוב פעם אחת באו בני ישמעאל ובני קטורה לדון עם ישראל לפני אלכסנדרוס מוקדון. אמרו לו: ארץ כנען שלנו ושלכם\u0004 (של ישראל), שאף להם חלק בה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואלה תלדת ישמעאל בן אברהם\u0004 אשר ילדה הגר המצרית שפחת שרה לאברהם\u0003\"\u0004 (בראשית כה, יב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואלה תולדת יצחק בן אברהם\"\u0004 (שם יט), והארץ שנתנה לאברהם צריכה איפוא להתחלק בין כל יורשיו.","\u0003אמר להן גביהא בן פסיסא לחכמים: תנו לי רשות ואלך ואדון עמהם לפני אלכסנדרוס מוקדון. אם ינצחוני אמרו: הדיוט שבנו נצחתם, ואם אני אנצח אותם אמרו להם: תורת משה רבינו נצחתכם. נתנו לו רשות, הלך ודן עמהן.\u0004","\u0003אמר להם\u0004 לבני ישמעאל: \u0003מהיכן אתם מביאין ראייה? אמרו לו: מן התורה. אמר להן: אף אני לא אביא ראייה אלא מן התורה, שנאמר: \"ויתן אברהם את כל אשר לו ליצחק. ולבני הפילגשים אשר לאברהם נתן אברהם מתנת\u0004 וישלחם מעל יצחק בנו בעודנו חי קדמה אל ארץ קדם\u0003\"\u0004 (שם ה–ו), \u0003אב שנתן אגטין\u0004 (כתבים ושטרות חלוקה) \u0003לבניו בחייו, ושיגר זה מעל זה, כלום יש לזה על זה כלום?\u0004 שהרי האב עצמו עשה חלוקה זו של הנכסים. אגב הזכרת הענין שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003מתנות\u0004 אלה שהוזכרו? \u0003אמר ר' ירמיה בר אבא: מלמד שמסר להם שם\u0004 שיש בו כוח על טבעי של \u0003טומאה,\u0004 שיוכלו לעשות בו כשפים.","כיון שדובר בוויכוחים שהיו בין גדולי ישראל וגדולי אומות העולם מזכירים עוד ויכוח אחר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אנטונינוס\u0004 קיסר רומי \u0003לרבי:\u0004 והלא \u0003גוף ונשמה יכולין לפטור עצמן מן הדין\u0004 על מה שחטאו, \u0003כיצד?\u0004 — \u0003גוף אומר: נשמה\u0004 היא ש\u0003חטאת\u0004 (חטאה), וראיה לדבר — \u0003שמיום שפירשה ממני\u0004 (שעזבתני בשעת מיתה) \u0003הריני מוטל כאבן דומם בקבר. ונשמה אומרת:\u0004 ה\u0003גוף חטא, שמיום שפירשתי ממנו הריני פורחת באויר כצפור\u0004 ואיני מסוגלת לחטוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003אמשול לך משל, למה הדבר דומה?\u0004 — \u0003למלך בשר ודם שהיה לו פרדס נאה, והיה בו\u0004"],["\u0003בכורות\u0004 (בכורי תאנים) \u0003נאות, והושיב בו שני שומרים\u0004 לשמור את הגן, \u0003אחד חיגר\u0004 שאינו יכול להלך, \u0003ואחד סומא,\u0004 שאף אחד מהם לא יוכל להגיע לפירות הפרדס. \u0003אמר לו\u0004 ה\u0003חיגר לסומא: בכורות נאות אני רואה בפרדס, בא והרכיבני\u0004 על גבך, ואני אראה לך את הדרך \u0003ונביאם לאכלם. רכב חיגר על גבי סומא, והביאום ואכלום.\u0004","\u0003לימים בא בעל פרדס. אמר להן: בכורות נאות\u0004 שבפרדס \u0003היכן הן? אמר לו חיגר: כלום יש לי רגלים להלך בהן? אמר לו סומא: כלום יש לי עינים לראות\u0004 את הדרך? \u0003מה עשה\u0004 בעל הפרדס שהבין כיצד נעשתה ההערמה? \u0003הרכיב חיגר על גבי סומא\u0004 כדרך שחטאו, \u0003ודן אותם כאחד.\u0004","\u0003אף הקדוש ברוך הוא\u0004 לעתיד לבוא \u0003מביא נשמה וזורקה\u0004 שוב \u0003בגוף, ודן אותם כאחד\u0004 כדרך שחטאו כשהיו יחד, \u0003שנאמר: \"יקרא אל השמים מעל ואל הארץ לדין עמו\"\u0004 (תהלים נ, ד). \u0003\"יקרא אל השמים מעל\"\u0004 — \u0003זו נשמה\u0004 שהיא העליונה, \u0003\"ואל הארץ לדין עמו\"\u0004 — \u0003זה הגוף.\u0004","ועוד מספרים על שיחה שהיתה ביניהם בנושא אחר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אנטונינוס לרבי: מפני מה חמה יוצאה במזרח ושוקעת במערב? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הוה איפכא נמי הכי הוה אמרת לי\u0004 \u0005[אילו היה ההיפך גם כן כך היית אומר,\u0006 שואל \u0005אותי],\u0006 והרי צריכה השמש לזרוח מצד אחד ולשקוע מצד אחר. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי קאמינא\u0004 \u0005[כך אומר אני]\u0006 \u0003לך,\u0004 כלומר, זו היא שאלתי: \u0003מפני מה שוקעת במערב\u0004 ואינה פונה לעתים לצדדים אחרים?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כדי ליתן שלום לקונה,\u0004 שכאשר היא שוקעת למערב הריהי כמשתחווה, \u0003שנאמר: \"וצבא השמים לך משתחוים\"\u0004 (נחמיה ט, ו), והשכינה היא בצד מערב כפי שמצינו במקדש, ששם מקום קודש הקדשים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אם לצורך זה שוקעת במערב, אם כן \u0003ותיתי\u0004 \u0005[ותבוא]\u0006 השמש \u0003עד פלגא\u0004 \u0005[חצי]\u0006 ה\u0003רקיע\u0004 ותרד מעט, \u0003ותתן שלמא\u0004 \u0005[שלום]\u0006 כמשתחווה למערב \u0003ותיעול\u0004 \u0005[\u0006ותחזור \u0005ותיכנס]\u0006 למקומה במזרח, כדי לשקוע שם! ענה לו: דבר זה נעשה \u0003משום פועלים, ומשום עוברי דרכים,\u0004 שאם לא היתה החמה שוקעת בכיוון מסויים ואורה פוחת והולך, לא היו אלה יודעים את שעת היום להכין עצמם ללכת לביתם או לבית מלון.","\u0003ו\u0004עוד \u0003אמר לו אנטונינוס לרבי: נשמה מאימתי ניתנה באדם,\u0004 האם \u0003משעת פקידה,\u0004 כלומר, משעה שנקלט זרע האיש אצל האשה, \u0003או משעת יצירה\u0004 כאשר נוצרת כבר צורה מסויימת של עובר, והיא נחשבת כעבור ארבעים יום לאחר תחילת ההריון. \u0003אמר לו\u0004 רבי: \u0003משעת יצירה. אמר לו\u0004 אנטונינוס: לא יתכן דבר זה, האם \u0003אפשר\u0004 ש\u0003חתיכה של בשר עומדת\u0004 אפילו \u0003שלשה ימים בלא מלח ואינה מסרחת?\u0004 בוודאי אין העובר יכול להתקיים ארבעים יום ללא נפש חיים, \u0003אלא\u0004 בהכרח יש בו נשמה \u0003משעת פקידה. אמר רבי: דבר זה למדני אנטונינוס, ו\u0004אף ה\u0003מקרא מסייעו, שנאמר\u0004 בתיאור הלידה \u0003\"ופקדתך שמרה רוחי\"\u0004 (איוב י, יב), לרמוז שמשעת פקידה שומר אני את הרוח בקרבי.","\u0003ו\u0004עוד \u0003אמר לו אנטונינוס לרבי: מאימתי יצר הרע שולט באדם,\u0004 האם \u0003משעת יצירה או משעת יציאה\u0004 מן הרחם? \u0003אמר לו\u0004 רבי: \u0003משעת יצירה. אמר לו\u0004 אנטונינוס: \u0003אם כן\u0004 הוא, יהא העובר \u0003בועט במעי אמו ויוצא\u0004 מפני שתקפו יצרו לכך! \u0003אלא\u0004 ודאי יצרו שולט בו \u0003משעת יציאה. אמר רבי: דבר זה למדני אנטונינוס, ומקרא מסייעו, שנאמר: \"לפתח חטאת רבץ\"\u0004 (בראשית ד, ז), לרמוז שמשעה שאדם יוצא מפתח הרחם מאז רובצת בו החטאת־היצר.","\u0003ריש לקיש רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין שני מקראות העוסקים בתחיית המתים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"\u0004הנני מביא אותם מארץ צפון וקבצתים מירכתי ארץ \u0003בם עור ופסח הרה וילדת יחדו\"\u0004 (ירמיה לא, ז), שמשם מובן שבאחרית הימים יהיו עדיין בעלי מומים, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אז ידלג כאיל פסח ותרן לשון אלם כי נבקעו במדבר מים ונחלים בערבה\"\u0004 (ישעיה לה, ו). \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את המקראות? אלא יש לומר: \u0003עומדין\u0004 כולם בתחיית המתים \u0003במומן, ומתרפאין\u0004 לאחר מכן.","בנושא דומה \u0003עולא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"בלע המות לנצח ומחה ה'\u0004 אלהים \u0003דמעה מעל כל פנים\"\u0004 (שם כה, ח), הרי שלא יהא עוד מוות בעולם. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"כי הנער בן מאה שנה ימות לא יהיה משם עוד עול ימים\"\u0004 (שם סה, כ). והשיב: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן\u0004 — \u0003בישראל\u0004 שלא ימותו כלל, \u0003כאן\u0004 — \u0003בגוים\u0004 שאמנם יחיו חיים ארוכים מאד אך לבסוף ימותו. ושואלים: \u0003וגוים מאי בעו התם\u0004 \u0005[מה צריכים\u0006 אותם \u0005שם]?\u0006 ומשיבים: \u0003הנך דכתיב בהו\u0004 \u0005[אלה\u0006 הם הגוים \u0005שנאמר בהם]\u0006 \u0003\"ועמדו זרים ורעו\u0004 \u0003צאנכם ובני נכר אכריכם וכרמיכם\"\u0004 (שם סא, ה).","\u0003רב חסדא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וחפרה הלבנה ובושה החמה כי מלך ה' צבאות\u0004 בהר ציון ובירושלים ונגד זקניו כבוד\u0003\"\u0004 (שם כד, כג), משמע שלא יאירו עוד הירח והשמש, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והיה אור הלבנה כאור החמה ואור החמה יהיה שבעתים כאור שבעת הימים\"\u0004 (שם ל, כו), משמע שיתקיימו המאורות אלא שאורם יגדל! והשיב: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן לימות המשיח\u0004 יגדל אור החמה והלבנה, \u0003כאן לעולם הבא\u0004 יהיה רק אור ה' לבדו.","ושואלים: \u0003ול\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר\u0004 ש\u0003אין\u0004 הבדל \u0003בין העולם הזה לימות המשיח אלא שיעבוד גליות בלבד\u0004 שישתחררו ממנו ישראל, כיצד מסביר הוא את הסתירה במקראות? ומשיבים: אף לדעתו \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 ושניהם מדברים בעולם הבא, אלא \u0003כאן\u0004 — \u0003במחנה צדיקים\u0004 יהיה אור החמה שבעתים, \u0003כאן\u0004 — \u0003במחנה שכינה\u0004 לא יהיה אלא אור ה' לבדו.","\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אני אמית ואחיה\"\u0004 (דברים לב, לט), משמע שבכוחו של ה' להחיות מתים, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך \u0003\"מחצתי ואני ארפא\"\u0004 (דברים לב, לט), שהוא שבח פחות מזה! אלא יש להבין: \u0003אמר הקדוש ברוך הוא: מה שאני ממית\u0004 — \u0003אני מחיה,\u0004 כלומר, כשם שמתו אנשים כך יחיו מתחילה בתחיית המתים, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מה שמחצתי\u0004 — \u0003ואני ארפא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על הנאמר \u0003\"אני אמית ואחיה\", יכול\u0004 שכוונת הפסוק היא \u0003שתהא מיתה ב\u0004אדם \u0003אחד וחיים באחד כדרך שהעולם נוהג\u0004 כעת? — \u0003תלמוד לומר: \"מחצתי ואני ארפא\", מה\u0004 ענייני \u0003מחיצה ורפואה\u0004 שהוזכרו בפסוק זה ודאי הכוונה \u0003ב\u0004אדם \u0003אחד\u0004 — \u0003אף מיתה וחיים באחד, מיכן תשובה לאומרין אין תחיית המתים מן התורה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' מאיר: מניין לתחיית המתים מן התורה?\u0004 — \u0003שנאמר: \"אז ישיר משה ובני ישראל את השירה הזאת לה' \"\u0004(שמות טו, א), \u0003\"שר\" לא נאמר אלא \"ישיר\"\u0004 — \u0003מכאן לתחיית המתים מן התורה,\u0004 לומר שעתיד משה רבינו לחזור ולשיר את השירה. ו\u0003כיוצא בדבר אתה אומר\u0004 על הכתוב: \u0003\"אז יבנה יהושע מזבח לה' \"\u0004(יהושע ח, ל), \u0003\"בנה\" לא נאמר אלא \"יבנה\"\u0004 — \u0003מכאן לתחיית המתים מן התורה.\u0004","ומקשים: \u0003אלא מעתה\u0004 שאתה למד ממה שנאמרו דברים בלשון עתיד, אם כן הכתוב \u0003\"אז יבנה שלמה במה לכמוש שקץ מואב\"\u0004 (מלכים א' יא, ז), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהכוונה ש\u0003יבנה\u0004 לעתיד לבוא?! אלא את הצורה \"יבנה\" יש לפרש בדרך אחרת, שלא נאמר שבנה שלמה עצמו במה לאליל, \u0003אלא מעלה\u0004 (מחשיב) \u0003עליו\u0004 \u0003הכתוב כאילו בנה,\u0004 מתוך שלא עיכב ביד נשותיו. ואם כן אין ראיה מלשון זו.","\u0003אמר ר' יהושע בן לוי: מניין לתחיית המתים מן התורה?\u0004 — \u0003שנאמר: \"אשרי יושבי ביתך עוד יהללוך סלה\"\u0004 (תהלים פד, ה), \u0003\"היללוך\" לא נאמר, אלא \"יהללוך\"\u0004 בלשון עתיד — \u0003מכאן לתחיית המתים מן התורה. ואמר ר' יהושע בן לוי: כל האומר שירה\u0004 לה' \u0003בעולם הזה, זוכה ואומרה\u0004 גם \u0003לעולם הבא, שנאמר \"אשרי יושבי ביתך עוד יהללוך סלה\",\u0004 כלומר, עוד יזכו להללך לעתיד לבוא.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מניין לתחיית המתים מן התורה?\u0004 — \u0003שנאמר: \"קול צפיך נשאו קול יחדו ירננו\u0004 כי עין בעין יראו בשוב ה' ציון\u0003\"\u0004 (ישעיה נב, ח), \u0003\"ריננו\" לא נאמר, אלא \"ירננו\"\u0004 — \u0003מכאן לתחיית המתים מן התורה.\u0004 \u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: עתידין כל הנביאים כולן\u0004 להיות \u0003אומרים שירה בקול אחד, שנאמר: \"קול צפיך נשאו קול יחדו ירננו\"\u0004 (ישעיה נב, ח).","\u0003אמר רב יהודה אמר רב: כל המונע הלכה מפי תלמיד\u0004 הרוצה ללמוד, \u0003כאילו גוזלו מנחלת אבותיו, שנאמר: \"תורה צוה לנו משה מורשה קהלת יעקב\"\u0004 (דברים לג, ד), שהתורה \u0003מורשה\u0004 (ירושה) \u0003היא לכל ישראל מששת ימי בראשית,\u0004 ומי שמעכב את התלמיד מללמוד, הרי זה כגוזל ממנו את נחלתו המורשתית. \u0003אמר רב חנא בר ביזנא אמר ר' שמעון חסידא: כל המונע הלכה מפי תלמיד, אפילו עוברין שבמעי אמו מקללין אותו\u0004 על כך, \u0003שנאמר: \"מנע בר\u0004"],["\u0003יקבהו לאום\u0004 וברכה לראש משביר\u0003\"\u0004 (משלי יא, כו), \u0003ואין\u0004 משמעות \u0003\"לאום\" אלא עוברין,\u0004 כלומר, אף הם קרויים \"לאום\", \u0003שנאמר: \"\u0004שני גוים בבטנך ושני לאומים ממעיך יפרדו \u0003ולאם מלאם יאמץ\"\u0004 (בראשית כה, כג), \u0003ואין \"קבה\" אלא קללה, שנאמר\u0004 בדברי בלעם: \u0003\"מה אקב לא קבה אל\"\u0004 (במדבר כג, ח), \u0003ואין\u0004 משמעות \u0003\"בר\" אלא תורה, שנאמר \"נשקו בר פן יאנף\"\u0004 (תהלים ב, יב), המתפרש: החזיקו בתורה.","\u0003עולא בר ישמעאל אומר:\u0004 מי שמונע הלכה מפי תלמיד \u0003מנקבין אותו ככברה,\u0004 וראיה לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"\u0004מונע בר \u0003יקבהו לאום\"\u0004 (משלי יא, כו), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ויקב חר בדלתו\"\u0004 (מלכים ב' יב, י), הרי ש\"נקיבה\" לשון עשיית חור הוא. \u0003ואמר אביי:\u0004 מנקבים אותו \u0003כי אוכלא דקצרי\u0004 \u0005[כמו טפטפת המים של הכובסים].\u0006","\u0003ואם למדו\u0004 הרב לתלמיד, \u0003מה שכרו? אמר רבא אמר רב ששת: זוכה לברכות כיוסף, שנאמר: \"וברכה לראש משביר\"\u0004 (משלי שם), \u0003ואין \"משביר\" אלא\u0004 כינוי ל\u0003יוסף, שנאמר: \"ויוסף הוא השליט על הארץ הוא המשביר לכל עם הארץ\"\u0004 (בראשית מב, ו).","\u0003אמר רב ששת: כל המלמד תורה בעולם הזה, זוכה ומלמדה לעולם הבא, שנאמר: \"ומרוה גם הוא יורה\"\u0004 (משלי יא, כה), שהמורה (=\"מרוה\" בחילוף אותיות) ימשיך להורות גם בעתיד.","ושוב חוזרים לענין הראשון, \u0003אמר רבא: מניין לתחיית המתים מן התורה?\u0004 — שאת מה \u0003שנאמר: \"יחי ראובן ואל ימת\u0004 ויהי מתיו מספר\u0003\"\u0004 (דברים לג, ו) יש לפרש כך: \u0003\"יחי ראובן\"\u0004 — \u0003בעולם הזה, \"ואל ימת\"\u0004 — \u0003לעולם הבא. רבינא אמר\u0004 ראיה \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר: \u0003\"ורבים מישני אדמת עפר יקיצו אלה לחיי עולם ואלה לחרפות לדראון עולם\"\u0004 (דניאל יב, ב). \u0003רב אשי אמר\u0004 ראיה \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"ואתה לך לקץ ותנוח ותעמד לגרלך לקץ הימין\"\u0004 (שם יג).","\u0003אמר ר' אלעזר: כל פרנס שמנהיג את הצבור בנחת\u0004 בלא כעס וביושר \u0003זוכה ומנהיגם לעולם הבא, שנאמר: \"כי מרחמם ינהגם ועל מבועי מים ינהלם\"\u0004 (ישעיה מט, י), שכשם שרחמם בעולם הזה, כן יזכה להנהיגם לעולם הבא. ואגב מאמרו זה של ר' אלעזר מביאים עוד שורת מאמרים מתורתו בענייני הנהגת האדם ודרכו.","\u0003ואמר ר' אלעזר: גדולה\u0004 מעלת ה\u0003דעה\u0004 שיש באדם שהיא התבונה והידיעה לנהוג בדרכי החיים, לפי \u0003שניתנה בין שתי אותיות,\u0004 כלומר, בין שני שמות קדושים, \u0003שנאמר: \"כי אל דעות ה' \"\u0004(שמואל א' ב, ג), והרי זה מורה על מעלת הדעת.","\u0003ואמר ר' אלעזר: גדול\u0004 מעלת ה\u0003מקדש שניתן\u0004 אף הוא \u0003בין שתי אותיות, שנאמר: \"\u0004מכון לשבתך \u0003פעלת ה' מקדש ה' כוננו ידיך\"\u0004 (שמות טו, יז). \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על שמועה זו \u0003רב אדא קרחינאה: אלא מעתה\u0004 לפי אותו עקרון תאמר כי \u0003גדולה נקמה ש\u0004הרי \u0003ניתנה\u0004 אף היא \u0003בין שתי אותיות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אל נקמות ה' אל נקמות הופיע\"\u0004 (תהלים צד, א)!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין מכאן סתירה, כי \u0003למילתיה\u0004 \u0005[לעניינו,\u0006 לצרכה\u0005],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 שלעתים נקמה גם היא דבר גדול, וכשיטת \u0003עולא.\u0004 ש\u0003אמר עולא: שתי הופעיות הללו\u0004 \"אל נקמות הופיע\", וכן \"הופיע מהר פארן\" (דברים לג, ב), \u0003למה?\u0004 — \u0003אחת למדת טובה\u0004 של מתן תורה, \u0003ואחת למדת פורענות\u0004 לנקום מאויבי ישראל ומשעבדיו.","את שתי מימרותיו האחרונות מקשר \u0003ואמר ר' אלעזר\u0004 במאמר: \u0003כל אדם שיש בו דעה כאילו נבנה בית המקדש בימיו, שזה\u0004 המקדש \u0003ניתן בין שתי אותיות, וזה\u0004 הדעת \u0003ניתן בין שתי אותיות.\u0004","\u0003ואמר ר' אלעזר: כל אדם שיש בו דעה לסוף\u0004 הוא \u0003מתעשר, שנאמר: \"ובדעת חדרים ימלאו כל הון יקר ונעים\"\u0004 (משלי כד, ד).","\u0003ואמר ר' אלעזר: כל אדם שאין בו דעה אסור לרחם עליו, שנאמר: \"כי לא עם בינות הוא על כן לא ירחמנו עשהו ויצרו לא יחננו\"\u0004 (ישעיה כז, יא), ואם ה' אינו מרחם עליו, כל שכן בני אדם אחרים אין להם לרחם עליו.","\u0003ואמר ר' אלעזר: כל הנותן פיתו למי שאין בו דעה, יסורין באין עליו, שנאמר: \"לחמך ישימו מזור תחתיך אין תבונה בו\"\u0004 (עובדיה א, ז), כלומר, הנותן לחמו למי שאין תבונה בו סופו שיהא לו למחלה. ומפרש: \u0003ואין\u0004 משמעות \u0003\"מזור\" אלא יסורין,\u0004 על פי ההקבלה בכתוב \u0003שנאמר: \"וירא אפרים\u0004 \u0003ד\u0004\u0003את חליו ויהודה את מזרו\"\u0004 (הושע ה, יג).","\u0003ואמר ר' אלעזר: כל אדם שאין בו דעה\u0004 — \u0003לסוף\u0004 הוא \u0003גולה\u0004 ממקומו, \u0003שנאמר: \"לכן גלה עמי מבלי דעת\"\u0004 (ישעיה ה, יג).","\u0003ו\u0004עוד \u0003אמר ר' אלעזר: כל בית שאין דברי תורה נשמעים בו בלילה\u0004 — \u0003אש\u0004 של גיהנום \u0003אוכלתו, שנאמר: \"כל חשך טמון לצפוניו תאכלהו אש לא נפח ירע שריד באהלו\"\u0004 (איוב כ, כו), ו\u0003אין\u0004 משמעות \u0003\"שריד\" אלא תלמיד חכם, שנאמר: \"ובשרידים אשר ה' קרא\"\u0004 (יואל ג, ה), שבית חשוך ודומם מתורה בלילה, תאכלהו אש שאינה צריכה להצתה — אש גיהנום.","\u0003ואמר ר' אלעזר: כל שאינו מהנה תלמידי חכמים מנכסיו, אינו רואה סימן ברכה לעולם, שנאמר: \"אין שריד לאכלו על כן לא יחיל טובו\"\u0004 (איוב כ, כא), \u0003ואין\u0004 משמעות \u0003\"שריד\" אלא תלמידי חכמים, שנאמר: \"ובשרידים אשר ה' קרא\"\u0004 ומי שאינו משתף את החכם (\"שריד\") באכלו — לא יגיע (\"יחיל\") לטובה.","\u0003ואמר ר' אלעזר: כל שאינו משייר פת על שלחנו\u0004 ומראה בכך שמודה לה' על שנתן לו די והותר — \u0003אינו רואה סימן ברכה לעולם, שנאמר: \"אין שריד לאכלו על כן לא יחיל טובו\"\u0004 ומקשים:","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר\u0004 עצמו: \u0003כל המשייר פתיתים על שלחנו כאילו עובד עבודה זרה, שנאמר: \"הערכים לגד שלחן והממלאים למני ממסך\"\u0004 (ישעיה סה, יא), שהיו משמרים למזל הבית (\"גד\") פירורים במתנה, והרי הם כעבודה זרה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דאיכא\u0004 \u0005[שיש]\u0006 פת \u0003שלימה בהדיה\u0004 \u0005[עימו],\u0006 ואם מקפיד להוסיף עוד פירורים הרי זה מראה שכוונתו לעבודה זרה, \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דליכא\u0004 \u0005[שאין]\u0006 פת \u0003שלימה בהדיה\u0004 \u0005[עימו].\u0006","\u0003ואמר ר' אלעזר: כל המחליף בדיבורו,\u0004 שאינו עומד בדיבורו, \u0003כאילו עובד עבודה זרה,\u0004 וראיה לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 כשבא יעקב לקחת את ברכת עשו: \u0003\"והייתי בעיניו כמתעתע\"\u0004 (בראשית כז, יב), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 לגבי עבודה זרה: \u0003\"הבל המה מעשה תעתעים\"\u0004 (ירמיה י, טו).","\u0003ואמר ר' אלעזר: כל המסתכל בערוה קשתו ננערת,\u0004 כלומר, אונו נפגם, \u0003שנאמר: \"עריה תעור קשתך\"\u0004 (חבקוק ג, ט), שהמסתכל בערוה (\"עריה\") הרי זה מנער ופוגם כוח קשתו.","\u0003ואמר ר' אלעזר: לעולם הוי קבל וקיים,\u0004 כלומר, לעולם תהיה חשוך (לא ידוע) ותתקיים (תחיה). \u0003אמר ר' זירא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנה מעין רעיון זה, שאמרו: \u0003בית אפל\u0004 שנראה בו כעין נגע צרעת \u0003אין פותחין לו חלונות לראות נגעו,\u0004 והבית בחזקת טהרה. הרי שדווקא האפל נשאר קיים. ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 רעיון זה.","ועוד לענין תחיית המתים \u0003אמר ר' טבי אמר ר' יאשיה: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"שאול ועצר רחם ארץ לא שבעה מים\"\u0004 (משלי ל, טז), \u0003וכי מה ענין שאול אצל רחם? אלא לומר לך\u0004 וללמדך: \u0003מה רחם מכניס\u0004 את הזרע \u0003ומוציא\u0004 תינוק, \u0003אף שאול\u0004 (הקבר) \u0003מכניס ומוציא\u0004 לתחיית המתים.","\u0003והלא דברים קל וחומר: ומה רחם שמכניסין בו בחשאי\u0004 — \u0003מוציאין ממנו בקולי קולות\u0004 שצועקת היולדת בשעת לידה, \u0003שאול שמכניסין בו בקולות\u0004 הבוכים והאבלים על המת — \u0003אינו דין שמוציאין ממנו בקולי קולות?\u0004 ובוודאי ישמעו קולות עצומים כשתגיע עת התחיה. \u0003מיכן תשובה לאומרין: אין תחיית המתים מן התורה.\u0004","\u0003תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003אליהו: צדיקים שעתיד הקדוש ברוך הוא להחיותן\u0004 לעתיד לבוא שוב \u0003אינן חוזרין לעפרן, שנאמר: \"והיה הנשאר בציון והנותר בירושל ם קדוש יאמר לו כל הכתוב לחיים בירושל ם\"\u0004 \u0005(ישעיה ד, ג)\u0006, \u0003מה קדוש לעולם קיים אף הם לעולם קיימין.\u0004"],["\u0003ואם תאמר: אותן שנים שעתיד הקדוש ברוך הוא לחדש בהן את עולמו, שנאמר: \"ונשגב ה' לבדו ביום ההוא\"\u0004 (ישעיה ב, יא), שישאר ה' לבדו ויחדש את העולם, \u0003צדיקים מה הן עושין,\u0004 האם חיים הם? — \u0003הקדוש ברוך הוא עושה להם כנפים כנשרים, ושטין על פני המים, שנאמר: \"על כן לא נירא בהמיר ארץ ובמוט הרים בלב ימים\"\u0004 (תהלים מו, ג), שכאשר מחליף הקדוש ברוך הוא את הארץ, לא יראו, לפי שיהיו באותה שעה בלב ימים. \u0003ושמא תאמר\u0004 ש\u0003יש להם צער\u0004 כשהם עפים כך ללא הרף? — \u0003תלמוד לומר: \"וקוי ה' יחליפו כח יעלו אבר כנשרים ירוצו ולא ייגעו ילכו ולא ייעפו\"\u0004 (ישעיה מ, לא).","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003ממתים שהחיה יחזקאל\u0004 שאין החיים בתחיה נשארים לעולם והם מתים לאחר זמן! ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003באמת משל היה\u0004 מעשה זה במתים שהחיה יחזקאל, ואין ללמוד משם.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: מתים שהחיה יחזקאל עמדו על רגליהם, ואמרו שירה\u0004 לה' \u0003ומתו. מה\u0004 (איזו) \u0003שירה אמרו?\u0004 — \u0003\"ה' ממית בצדק ומחיה ברחמים\". ר' יהושע אומר, שירה זו אמרו: \"ה' ממית ומחיה מוריד שאול ויעל\"\u0004 (שמואל א' ב, ו). \u0003ר' יהודה אומר: אמת, משל היה.\u0004","\u0003אמר לו ר' נחמיה: אם אמת למה משל, ואם משל למה אמת? אלא\u0004 כך יש לומר: \u0003באמת\u0004 בודאי \u0003משל היה. ר' אליעזר בנו של ר' יוסי הגלילי אומר:\u0004 לא זו בלבד שלא היה הדבר משל, אלא אף אותם \u0003מתים שהחיה יחזקאל עלו לארץ ישראל, ונשאו נשים והולידו בנים ובנות. עמד ר' יהודה בן בתירא על רגליו ואמר: אני מבני בניהם, והללו תפילין שהניח לי אבי אבא מהם.\u0004","ושואלים: \u0003ומאן נינהו\u0004 \u0005[ומי הם]\u0006 אותם \u0003מתים שהחיה יחזקאל?\u0004","\u0003אמר רב: אלו בני אפרים שמנו לקץ\u0004 של הגאולה מגלות מצרים \u0003וטעו\u0004 בחשבון ויצאו לפני הזמן המיועד ונהרגו, \u0003שנאמר: \"ובני אפרים שותלח וברד בנו ותחת בנו ואלעדה בנו ותחת בנו. וזבד בנו ושותלח בנו ועזר ואלעזר והרגום אנשי גת הנולדים בארץ\u0004 כי ירדו לקחת את מקניהם\u0003\"\u0004 (דברי הימים א' ז, כ–כא), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויתאבל אפרים אביהם ימים רבים ויבאו אחיו לנחמו\"\u0004 (שם כב).","\u0003ושמואל אמר:\u0004 מתים שהחיה יחזקאל \u0003אלו בני אדם שכפרו בתחיית המתים, שנאמר: \"ויאמר אלי בן אדם העצמות האלה כל בית ישראל המה הנה אמרים יבשו עצמותינו ואבדה תקותנו נגזרנו לנו\"\u0004 (יחזקאל לז, יא), משמע שכפרו בגמול לאחרית הימים.","\u0003ר' ירמיה בר אבא אמר: אלו בני אדם שאין בהן לחלוחית של מצוה, שנאמר \"העצמות היבשות שמעו דבר ה' \"\u0004(שם ד), שאף בחייהם היו כעצמות יבשות.","\u0003ר' יצחק נפחא אמר: אלו בני אדם שחיפו את ההיכל כולו שקצים ורמשים, שנאמר: \"ואבוא ואראה והנה כל תבנית רמש ובהמה שקץ וכל גלולי בית ישראל מחקה על הקיר סביב\u0004 סביב\u0003\"\u0004 (שם ח, י), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"והעבירני עליהם סביב סביב\"\u0004 (שם לז, ב), ולמדים בגזירה שווה מהמילים \"סביב\" \"סביב\" שאותם אנשים הם.","\u0003ר' יוחנן אמר: אלו מתים שבבקעת דורא. ואמר ר' יוחנן\u0004 לענין מתים אלה: \u0003מנהר אשל עד רבת בקעת דורא\u0004 היו הרוגי ישראל. \u0003שבשעה שהגלה נבוכדנצר הרשע את ישראל היו בהן בחורים שהיו מגנין\u0004 (מביישים) \u0003את החמה ביופיין, והיו\u0004 הנשים ה\u0003כשדיות רואות אותן ושופעות זבות\u0004 מחמת תאוה. \u0003אמרו לבעליהן, ובעליהן למלך. צוה המלך והרגום, ועדיין היו שופעות זבות,\u0004 שאף לאחר שנהרגו היו יפים. \u0003צוה המלך ורמסום\u0004 שלא יראו את צורתם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בשעה שהפיל נבוכדנצר הרשע את חנניה מישאל ועזריה לכבשן האש, אמר לו הקדוש ברוך הוא ליחזקאל: לך והחייה\u0004 את ה\u0003מתים\u0004 הנמצאים \u0003בבקעת דורא. כיון שהחייה אותן, באו\u0004 אותן \u0003עצמות וטפחו לו לאותו רשע\u0004 נבוכדנצר \u0003על פניו. אמר: מה טיבן של אלו? אמרו לו: חבריהן של אלו מחייה מתים בבקעת דורא. פתח\u0004 נבוכדנצר \u0003ואמר: \"אתוהי כמה רברבין ותמהוהי כמה תקיפין מלכותיה מלכות עלם ושלטנה עם דר ודר\"\u0004 \u0005[\"אותותיו כמה גדולים, ופלאיו כמה חזקים, מלכותו מלכות עולם, ושלטונו עד דור ודור\"]\u0006 (דניאל ג, לג).","\u0003אמר ר' יצחק: יוצק זהב רותח לתוך פיו של אותו רשע,\u0004 כלומר, ראוי לו שייסתם פיו במיתה משונה (ומפני כבוד המלכות אמר \"זהב רותח\"), \u0003שאילמלא לא בא מלאך וסטרו על פיו\u0004 שלא יוסיף ויאמר עוד דברי שבח, \u0003ביקש לגנות\u0004 (להמעיט ערכן) של \u0003כל שירות ותשבחות שאמר דוד בספר תהלים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ששה נסים נעשו באותו היום\u0004 שניצלו בו חנניה מישאל ועזריה, \u0003ואלו הן: צף הכבשן\u0004 ועלה מן הקרקע שהיה טמון בה, \u0003ונפרץ הכבשן, והומק סודו\u0004 (נמס סיד שבו), \u0003ונהפך צלם\u0004 שעשה נבוכדנצר להשתחוות לו \u0003על פניו, ונשרפו ארבע\u0004 שררות של \u0003מלכיות\u0004 שעמדו מסביב לכבשן, \u0003והחיה יחזקאל את המתים בבקעת דורא.\u0004","\u0003וכולהו\u0004 \u0005[וכולם]\u0006 יודעים אנו מן ה\u0003גמרא\u0004 \u0005[מסורת],\u0006 \u0003ו\u0004אולם \u0003ארבע מלכיות\u0004 שנשרפו \u0003קרא\u0004 \u0005[המקרא]\u0006 הוא שמספר על כך. \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונבוכדנצר מלכא שלח למכנש לאחשדרפניא סגניא ופחותא אדרגזריא גדבריא דתבריא תפתיא וכל שלטני מדינתא\"\u0004 \u0005[\"ונבוכדנצר המלך שלח לכנוס את האחשדרפנים הסגנים וכו'... וכל שליטי המדינות\"]\u0006 (שם ב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"איתי גברין יהודאין...\u0004 לא שמו עלך מלכא טעם לאלהך לא פלחין ולצלם דהבא די הקימת לא סגדין \u0003\"\u0004\u0005[\"יש אנשים יהודים... ולצלם הזהב אשר העמדת אינם משתחוים\"]\u0006 (שם יב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 לאחר שיצאו חנניה מישאל ועזריה מכבשן האש: \u0003\"ומתכנשין אחשדרפניא סגניא ופחותא והדברי מלכא חזין לגבריא אלך\"\u0004 \u0005[ומתכנסים האחשדרפנים והסגנים ויועצי המלך וראו את האנשים האלה],\u0006 את חנניה וחבריו אשר יצאו מן האש בלא פגע (שם כז), אבל ארבע דרגות מאותן רשימות ראשונות (אדרגזיא, גדבריא, דתבריא, תפתיא) אינן נמצאות ברשימה השניה, ללמדנו שנשרפו באש.","\u0003תני דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר בן יעקב: אפילו בשעת הסכנה לא ישנה אדם עצמו מן הרבנות\u0004 (הגדולה) \u0003שלו\u0004 ולא ישפיל את עצמו, \u0003שנאמר: \"באדין גבריא אלך כפתו בסרבליהון פטשיהון וכרבלתהון\u0004 ולבושיהון ורמיו לגוא אתון נורא יקדתא\" \u0005[\"אז האנשים הללו כפותים בסרבליהם ובגדיהם הושלכו לכבשן האש הלוהטת\"]\u0006 (שם כא), שגם בשעה שהושלכו לכבשן האש לבשו את בגדי היקר שלהם.","\u0003אמר ר' יוחנן:\u0004"],["\u0003גדולים צדיקים\u0004 במעלתם \u0003יותר ממלאכי השרת, שנאמר: \"ענה ואמר הא אנא חזא גברין ארבעה שרין מהלכין בגו נורא וחבל לא איתי בהון ורוה די רביעאה דמה לבר אלהין\"\u0004 \u0005[\"ענה ואמר הרי אני רואה אנשים ארבעה מותרים מהלכים בתוך האש ונזק אין בהם ומראהו של הרביעי דומה לבן אלהים]\u0006 (דניאל ג, כה), הרי שראה בכבשן האש את שלושת הצדיקים וגם את המלאך שהיה שם, אבל את המלאך הזה מונה הוא לא ראשון אלא רביעי.","\u0003אמר ר' תנחום בר חנילאי: בשעה שיצאו חנניה מישאל ועזריה מכבשן האש, באו כל אומות העולם וטפחו לשונאיהן של ישראל\u0004 (כלומר, בלשון נקיה, לישראל) \u0003על פניהם, אמרו להם: יש לכם אלוה כזה, ואתם משתחוים לצלם?! מיד פתחו\u0004 חנניה מישאל ועזריה \u0003ואמרו: \"לך ה' הצדקה ולנו בשת הפנים כיום הזה\"\u0004 (שם ט, ז).","ועל אותו נושא \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אמרתי אעלה בתמר אחזה בסנסניו\"\u0004 (שיר השירים ז, ט); \u0003\"אמרתי אעלה בתמר\"\u0004 — \u0003אלו ישראל\u0004 שהכתוב מדמה אותם לתמר שאמר שכולם כשרים ודבקים בה', \u0003ועכשיו\u0004 שעשה ה' להם נסיון על ידי גזירת המלך \u0003לא עלה בידי אלא סנסן אחד של חנניה מישאל ועזריה,\u0004 שרק הם מכל ישראל מסרו נפשם.","\u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ראיתי הלילה והנה איש רכב על סוס אדם והוא עמד בין ההדסים אשר במצלה\"\u0004 (זכריה א, ח), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ראיתי הלילה\"?\u0004 — \u0003ביקש הקדוש ברוך הוא להפוך את כל העולם כולו ללילה,\u0004 ולהחריבו על שאין איש צדיק. \u0003\"והנה איש רכב\"\u0004 — \u0003אין \"איש\" אלא הקדוש ברוך הוא, שנאמר: \"ה' איש מלחמה ה' שמו\"\u0004 (שמות טו, ג), \u0003\"על סוס אדם\"\u0004 לרמז: \u0003ביקש הקדוש ברוך הוא להפוך את העולם כולו לדם,\u0004","\u0003כיון שנסתכל בחנניה מישאל ועזריה נתקררה\u0004 (נתפייסה) \u0003דעתו, שנאמר: \"והוא עמד בין ההדסים אשר במצלה\", ואין \"הדסים\" אלא צדיקים, שנאמר: \"ויהי אמן את הדסה\u0004 היא אסתר בת דודו\u0003\"\u0004 (אסתר ב, ז), הרי ש\"הדסה\" הוא כינוי לאסתר הצדקת, \u0003ואין \"מצולה\" אלא בבל, שנאמר\u0004 בכתוב המדבר בענין מפלת בבל: \u0003\"האמר לצולה חרבי ונהרתיך אוביש\"\u0004 (ישעיה מד, כז), \u0003מיד\u0004 אותם שליחים (שראה בחזון כדמות סוסים) שהיו \u0003מלאים רוגז נעשים שרוקים\u0004 (אפורים), \u0003ואדומים נעשו לבנים. אמר רב פפא שמע מינה\u0004 \u0005[למד מכאן]\u0006 בדרך אגב כי \u0003סוסיא חיורא מעלי לחלמא\u0004 \u0005[סוס לבן יפה לחלום],\u0006 שסימן הוא לשלום ושקט.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 חנניה מישאל ועזריה, אחר הנס, \u0003להיכא אזול\u0004 \u0005[להיכן הלכו],\u0006 ששוב לא נאמר עליהם דבר? \u0003אמר רב: בעין הרע מתו,\u0004 מתוך שקינאו בהם הכל. \u0003ושמואל אמר: ברוק טבעו,\u0004 שרקקו בהם אומות העולם בישראל מרוב בוז שאינם עובדים את ה' כראוי. \u0003ור' יוחנן אמר: עלו לארץ ישראל, ונשאו נשים והולידו בנים ובנות.\u0004","ומעירים: מחלוקת זו היא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו באותו ענין, \u0003ר' אליעזר אומר: בעין הרע מתו. ר' יהושע אומר: ברוק טבעו. וחכמים אומרים: עלו לארץ ישראל ונשאו נשים והולידו בנים ובנות, שנאמר: \"שמע נא יהושע הכהן הגדול אתה ורעיך הישבים לפניך כי אנשי מופת המה\"\u0004 (זכריה ג, ח), \u0003איזו הם אנשים שנעשה להן מופת\u0004 באותו דור? — \u0003הוי אומר: זה חנניה מישאל ועזריה.\u0004","ושואלים: \u0003ודניאל להיכן אזל\u0004 \u0005[הלך]?\u0006 שהרי ודאי שלא השתחווה לצלם, ולא שמענו שהושלך לאש, ואם כן ודאי לא היה שם. \u0003אמר רב:\u0004 הלך \u0003למיכרא נהרא רבא בטבריא\u0004 \u0005[לכרות\u0006 את \u0005הנהר הגדול בטבריה].\u0006 \u0003ושמואל אמר:\u0004 נשלח דניאל \u0003לאתויי ביזרא דאספסתא\u0004 \u0005[להביא זרע אספסת]\u0006 מובחר ממקום רחוק, ולכן לא היה בבבל. \u0003ור' יוחנן אמר:\u0004 שלחו \u0003לאתויי חזירי\u0004 \u0005[להביא חזירים]\u0006 של \u0003אלכסנדריא של מצרים,\u0004 שהיה שם מין מובחר ומשובח של חזירים. ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 וכי אפשר לעשות זאת? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003תודוס הרופא אמר: אין פרה וחזירה יוצא מאלכסנדריא של מצרים שאין חותכין\u0004 את \u0003האם\u0004 (הרחם) \u0003שלה, בשביל שלא תלד!\u0004 ומשיבים: חזירים \u0003זוטרי\u0004 \u0005[קטנים]\u0006 \u0003אייתי\u0004 \u0005[הביא]\u0006 \u0003בלא דעתייהו\u0004 \u0005[דעתם]\u0006 של אנשי אלכסנדריא, ולא הבחינו שהוא מוציאם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה היו באותה עצה\u0004 שלא יהא דניאל בבבל בשעת גזירת השמד: \u0003הקדוש\u0004 \u0003ברוך הוא, ודניאל, ונבוכדנצר. הקדוש ברוך הוא אמר: ניזיל\u0004 \u0005[שילך]\u0006 \u0003דניאל מהכא\u0004 \u0005[מכאן],\u0006 ש\u0003לא לימרו\u0004 \u0005[יאמרו]\u0006 כי \u0003בזכותיה איתנצל\u0004 \u0005[בזכותו נצלו]\u0006 חנניה מישאל ועזריה מכבשן האש, אלא ידעו כי הם צדיקים בזכות עצמם.","\u0003ודניאל אמר\u0004 בליבו: \u0003איזיל מהכא\u0004 \u0005[אלך מכאן]\u0006 ש\u0003לא ליקיים\u0004 \u0005[יתקיים]\u0006 \u0003בי\u0004 מאמר הכתוב \u0003\"פסילי אלהיהם תשרפון באש\"\u0004 (דברים ז, כה), שחשש דניאל שהוא עצמו נעשה כפסל משום שנבוכדנצר עבד אותו כאל, ושמא יגרום לו הדבר שתשלוט בו האש.","\u0003ונבוכדנצר אמר: יזיל\u0004 \u0005[ילך]\u0006 \u0003דניאל מהכא\u0004 \u0005[מכאן],\u0006 ש\u0003לא לימרו\u0004 \u0005[יאמרו]:\u0006 \u0003קלייה לאלהיה בנורא\u0004 \u0005[שרף\u0006 נבוכדנצר \u0005את אלוהיו באש].\u0006 \u0003ומניין דסגיד ליה\u0004 \u0005[שהשתחווה לו]\u0006 לדניאל? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"באדין מלכא נבוכדנצר נפל על אנפוהי ולדניאל סגד\u0004 ומנחה וניחחין אמר לנסכה לה \u0003\"\u0004\u0005[אז המלך נבוכדנצר נפל על פניו ולדניאל השתחווה\u0006 ומנחה וניחוחים אמר לנסך לו\u0005]\u0006 (דניאל ב, מו).","בקשר למעשה חנניה מישאל ועזריה מביאים את מאמר הכתוב: \u0003\"כה אמר ה' צבאות אלהי ישראל אל אחאב בן קוליה ואל צדקיהו בן מעשיה הנבאים לכם בשמי לשקר\"\u0004 (ירמיה כט, כא), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ולקח מהם קללה לכל גלות יהודה אשר בבבל לאמר ישימך ה' כצדקיהו וכאחאב אשר קלם מלך בבל באש\"\u0004 (שם כב). \u0003\"אשר שרפם\" לא נאמר אלא \"אשר קלם\". אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מלמד שעשאן כקליות\u0004 (חיטים צלויות באש) שחורכים אותן מכל צד.","נאמר שם: \u0003\"יען אשר עשו נבלה בישראל וינאפו את נשי רעיהם\"\u0004 (שם כג). \u0003מאי עבוד\u0004 \u0005[מה עשו]?\u0006 ומספרים: \u0003אזול לגבי ברתיה\u0004 \u0005[הלכו אל בתו]\u0006 של \u0003נבוכדנצר, אחאב אמר לה, \"כה אמר ה': השמיעי\u0004 (הבעלי) \u0003אל צדקיה\". וצדקיה אמר\u0004 לה, \u0003\"כה אמר ה': השמיעי\u0004 (הבעלי) \u0003אל אחאב\". אזלה\u0004 \u0005[הלכה]\u0006 \u0003ואמרה ליה לאבוה\u0004 \u0005[לו לאביה]\u0006 מה שאמרו לה. \u0003אמר לה: אלהיהם של אלו שונא זימה הוא,\u0004 ואין זו נראית נבואה אמיתית, \u0003כי אתו לגבך שדרינהו לגבאי\u0004 \u0005[כאשר יבואו אליך שלחי אותם אלי].\u0006","\u0003כי אתו לגבה שדרתנהו לגבי אבוה\u0004 \u0005[כאשר באו אליה שלחה אותם אל אביה].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמר לכון\u0004 \u0005[לכם]\u0006 לעשות כן? \u0003אמרו: הקדוש ברוך הוא.\u0004 אמר נבוכדנצר: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חנניה מישאל ועזריה שאלתינהו\u0004 \u0005[שאלתי אותם]\u0006 \u0003ואמרו לי: אסור! אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אנן נמי נביאי כוותייהו\u0004 \u0005[אנו גם כן נביאים כמותם],\u0006 \u0003לדידהו\u0004 \u0005[להם]\u0006 \u0003לא אמר להו\u0004 \u0005[להם]\u0006 ציווי זה, \u0003לדידן\u0004 \u0005[לנו]\u0006 \u0003אמר לן\u0004 \u0005[לנו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 אם כן \u0003אנא בעינא דאיבדקינכו כי היכי דבדקתינהו\u0004 \u0005[אני רוצה לבדוק אתכם כפי שבדקתי אותם],\u0006 את \u0003חנניה מישאל ועזריה,\u0004 ולדעת אם אמנם אנשים צדיקים אתם.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אינון תלתא הוו, ואנן תרין\u0004 \u0005[הם שלושה היו, ואנו שנים\u0006 בלבד\u0005],\u0006 ואין זכותנו מרובה כל כך שננצל מן האש. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בחרו לכון\u0004 \u0005[לכם]\u0006 \u0003מאן דבעיתו בהדייכו\u0004 \u0005[מי שאתם רוצים\u0006 כשלישי \u0005אתכם].\u0006 \u0003אמרו\u0004 לו: \u0003יהושע כהן גדול.\u0004 ומדוע בחרו בו? \u0003סברי\u0004 \u0005[סברו]:\u0006 \u0003ליתי\u0004 \u0005[\u0006ש\u0005יבוא]\u0006 \u0003יהושע\u0004 הכהן הגדול עמנו \u0003דנפיש זכותיה ומגנא עלן\u0004 \u0005[שמרובה זכותו ותגן\u0006 גם \u0005עלינו].\u0006","\u0003אחתיוהו שדינהו\u0004 \u0005[הכניסום\u0006 ו\u0005זרקו אותם]\u0006 לאש. \u0003אינהו איקלו\u0004 \u0005[הם נשרפו],\u0006 ו\u0003יהושע כהן גדול איחרוכי מאניה\u0004 \u0005[נחרכו בגדיו],\u0006 \u0003שנאמר: \"ויראני את יהושע הכהן הגדול עמד לפני מלאך ה'\u0004 והשטן עומד על ימינו לשטנו\u0003\"\u0004 (זכריה ג, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר ה' אל השטן יגער ה' בך...\u0004 הלוא זה אוד מוצל מאש\u0003\"\u0004 (שם ב), הרי רמז למעשה זה שניצל מכבשן האש, אלא שהיה חרוך מעט.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 נבוכדנצר: \u0003ידענא דצדיקא את\u0004 \u0005[יודע אני שצדיק אתה]\u0006 שניצלת מן האש, \u0003אלא מאי טעמא אהניא בך פורתא נורא\u0004 \u0005[מה טעם\u0006 \u0005הועילה\u0006 שלטה \u0005בך במקצת האש],\u0006 ואילו \u0003חנניה מישאל ועזריה לא אהניא בהו\u0004 \u0005[הועילה\u0006 שלטה \u0005בהם]\u0006 האש \u0003כלל,\u0004 ולא נחרכו בגדיהם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינהו תלתא הוו, ואנא חד\u0004 \u0005[הם שלושה\u0006 צדיקים \u0005היו, ואני אחד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 נבוכדנצר: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אברהם יחיד הוה\u0004 \u0005[היה]\u0006 כשהושלך לכבשן האש וניצל לגמרי! ענה לו: \u0003התם לא הוו\u0004 \u0005[היו]\u0006 \u0003רשעים בהדיה\u0004 \u0005[עמו],\u0006 \u0003ולא אתיהיב רשותא לנורא\u0004 \u0005[ניתנה רשות לאש]\u0006 לבעור כלל, \u0003הכא הוו\u0004 \u0005[כאן היו]\u0006 \u0003רשעים בהדי\u0004 \u0005[אתי],\u0006 \u0003ואתיהיב רשותא לנורא\u0004 \u0005[וניתנה רשות לאש]\u0006 לשרוף אותם, ולכן פגעה גם בבגדי. ומעירים: \u0003היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003תרי אודי יבישי וחד רטיבא אוקדן יבישי לרטיבא\u0004 \u0005[שני אודים יבשים ואחד רטוב\u0006 שהיו באש \u0005הדליקו היבשים את הרטוב].\u0006","ושואלים: \u0003מאי טעמא איענש\u0004 \u0005[מה טעם נענש]\u0006 יהושע הכהן הגדול שבעוון זה הוצרך להיות מושלך לכבשן האש? \u0003אמר רב פפא: שהיו בניו נושאין נשים שאינן הגונות לכהונה, ולא מיחה בהן, שנאמר: \"ויהושע היה לבש בגדים צואים\u0004 ועומד לפני המלאך\u0003\"\u0004 (שם ג), \u0003וכי דרכו של יהושע ללבוש בגדים צואים? אלא מלמד\u0004 הכתוב ברמז \u0003שהיו בניו נושאים נשים שאינן הגונות לכהונה, ולא מיחה בהן,\u0004 ולכן נראה כך בחזון לזכריה הנביא.","ועוד בקשר לחנניה מישאל ועזריה, מביאים מה ש\u0003אמר ר' תנחום, דרש בר קפרא בציפורי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בדברי רות לנעמי \u0003\"שש השערים האלה נתן לי\"\u0004 (רות ג, יז). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שש השערים\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שש שעורים ממש,\u0004 שנתן לה רק שש שבלים, \u0003וכי דרכו\u0004 \u0003של בועז ליתן מתנה שש שעורים\u0004 בלבד?!"],["\u0003אלא שש סאין\u0004 נתן לה.","ויש לשאול: \u0003וכי דרכה של אשה ליטול\u0004 משא כבד של \u0003שש סאין? אלא רמז (רמז) לה\u0004 בכך, \u0003שעתידין ששה בנים לצאת ממנה שמתברכין בשש ברכות, ואלו הן: דוד, ומשיח, דניאל, חנניה, מישאל ועזריה.\u0004 ומפרטים: \u0003דוד\u0004 נתברך בשש מעלות — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ויען אחד מהנערים ויאמר הנה ראיתי בן לישי בית הלחמי ידע נגן וגבור חיל ואיש מלחמה ונבון דבר ואיש תאר וה' עמו\"\u0004 (שמואל א' טז, יח).","\u0003ואמר רב יהודה אמר רב: כל הפסוק הזה לא אמרו דואג\u0004 (שהוא \"אחד מהנערים\") \u0003אלא בלשון הרע,\u0004 ונתכוון להקניא את שאול בדוד. וכך יש לדרשו: \u0003\"ידע נגן\"\u0004 — זה \u0003שיודע לישאל\u0004 בדבר תורה, שאלות של טעם, וכענין. \u0003\"גבור\"\u0004 פירושו — \u0003שיודע\u0004 גם \u0003להשיב\u0004 דברי תורה לשואל. \u0003\"איש מלחמה\"\u0004 — איש \u0003שיודע לישא וליתן במלחמתה של תורה.\u0004 \u0003\"איש תאר\"\u0004 — \u0003שמראה פנים\u0004 (\"תואר\") \u0003בהלכה\u0004 ומסביר אותה יפה. \u0003\"ונבון דבר\"\u0004 — \u0003שמבין דבר מתוך דבר. \"וה' עמו\"\u0004 — \u0003שהלכה כמותו בכל מקום.\u0004","ומספרים: \u0003בכולהו\u0004 \u0005[בכולם]\u0006 בכל הדברים שמנו לשבח בדוד \u0003אמר להו\u0004 \u0005[להם]\u0006 שאול: \u0003יהונתן בני כמוהו, כיון\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"וה' עמו\"\u0004 שהלכה כמותו, \u0003מילתא דבדידיה נמי\u0004 \u0005[דבר שבו עצמו,\u0006 בשאול \u0005גם כן]\u0006 \u0003לא הוה ביה\u0004 \u0005[היה בו],\u0006 \u0003חלש דעתיה ואיקניא ביה\u0004 \u0005[חלשה דעתו והתקנא בו\u0006 בדוד\u0005].\u0006 ש\u0003בשאול כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ובכל אשר יפנה ירשיע\"\u0004 (שם יד, מז), שאף שהכתוב מדבר בנצחונותיו, ובכלל זה שהיה גדול בתורה, מכל מקום לא היה מגיע למסקנת ההלכה המקובלת. \u0003ובדוד כתיב\u0004 \u0005[נאמר]\u0006 בו: \u0003\"ובכל אשר יפנה יצליח\".\u0004","ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003דואג הוה\u0004 \u0005[היה]\u0006 אותו איש שאמר את הדברים? ומשיבים: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ויען אחד מהנערים\",\u0004 \"אחד\" — \u0003מיוחד שבנערים. וכתיב התם\u0004 \u0005[שם]:\u0006 \u0003\"ושם איש מעבדי שאול ביום ההוא נעצר לפני ה' ושמו דאג האדמי אביר הרעים אשר לשאול\"\u0004 (שם כא, ח).","וגם \u0003משיח\u0004 נאמרו בו שש מעלות, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונחה עליו רוח ה' רוח חכמה ובינה רוח עצה וגבורה רוח דעת ויראת ה' \"\u0004(ישעיה יא, ב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והריחו ביראת ה'\u0004 ולא למראה עיניו ישפוט ולא למשמע אזניו יוכיח\u0003\"\u0004(שם ג).","\u0003אמר ר' אלכסנדרי\u0004 על המלה \"והדיחו\": \u0003מלמד שהטעינו\u0004 ה' למשיח \u0003מצות ויסורין כריחיים. רבא אמר\u0004 פירושו: \u0003דמורח ודאין\u0004 \u0005[ש\u0006יוכל ל\u0005הריח ולדון],\u0006 כלומר, שיבחין בחוש מיוחד עם מי הצדק, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא למראה עיניו ישפוט\u0004 ולא למשמע אזניו יוכיח \u0003\",\u0004 ונאמר \u0003\"ושפט בצדק דלים והוכיח במישור לענוי ארץ\"\u0004 (שם ד).","מסופר: \u0003בר כוזיבא\u0004 (בר כוכבא) \u0003מלך תרתין שנין ופלגא\u0004 \u0005[שתי שנים ומחצה],\u0006 \u0003אמר להו לרבנן\u0004 \u0005[להם לחכמים]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 ה\u0003משיח. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003במשיח כתיב דמורח ודאין\u0004 \u0005[נאמר ש\u0006הוא \u0005מריח ודן],\u0006 \u0003נחזי אנן אי מורח ודאין\u0004 \u0005[נראה אנחנו אם מריח\u0006 הוא \u0005ודן],\u0006 \u0003כיון דחזיוהו\u0004 \u0005[שראוהו]\u0006 שהוא \u0003לא מורח ודאין\u0004 \u0005[מריח ודן]\u0006 \u0003קטלוהו\u0004 \u0005[הרגוהו]\u0006 הגויים.","שש מעלות ב\u0003דניאל חנניה מישאל ועזריה, דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"\u0004ילדים \u0003אשר אין בהם כל מאום וטובי מראה ומשכלים בכל חכמה וידעי דעת ומביני מדע ואשר כח בהם לעמד בהיכל המלך וללמדם ספר ולשון כשדים\"\u0004 (דניאל א, ד).","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אשר אין בהם כל מום\"? אמר ר' חמא בר' חנניא: אפילו כריבדא דכוסילתא\u0004 \u0005[כפצע שנשאר אחר הקזת הדם]\u0006 \u0003לא הוה בהו\u0004 \u0005[היה בהם],\u0006 שהיו ללא כל סריטה. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואשר כח בהם לעמד בהיכל המלך\"?\u0004 מה כח צריך לזה? \u0003אמר ר' חמא בר' חנינא: מלמד שהיו אונסין\u0004 (מונעים) \u0003את עצמן מן השחוק, ומן השיחה, ומן השינה, ומעמידין על עצמן\u0004 (מתאפקים) \u0003בשעה שנצרכין לנקביהם, מפני אימת מלכות.\u0004","נאמר \u0003\"ויהי בהם מבני יהודה דניאל חנניה מישאל ועזריה\u0004 (שם ו). \u0003אמר ר' אליעזר: כולן מבני יהודה הם. ור'\u0004 \u0003שמואל בר נחמני אמר: דניאל מבני יהודה, חנניה מישאל ועזריה משאר שבטים.\u0004","נאמר לחזקיהו: \u0003\"ומבניך אשר יצאו ממך אשר תוליד יקחו והיו סריסים בהיכל מלך בבל\"\u0004 (ישעיה לט, ז). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"סריסים\"\u0004 בפסוק זה? \u0003רב אמר: סריסים ממש,\u0004 שסרסום הבבלים כדי להשתמש בהם בכל עבודות המלך, \u0003ור' חנינא אמר: שנסתרסה עבודה זרה בימיהם,\u0004 שהתברר לכל שאין בה ממש, והם חנניה מישאל ועזריה.","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שנסתרסה עבודה זרה בימיהם\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"וחבל לא איתי בהון\"\u0004 \u0005[וחבלה,\u0006 מום \u0005לא היתה בהם]\u0006 (דניאל ג, כה), משמע שהיו שלמים בכל גופם, ולא היו סריסים. \u0003אלא למאן דאמר\u0004 \u0005[אלא ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003סריסים ממש\u0004 נעשו, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וחבל לא איתי בהון\"\u0004 \u0005[וחבלה,\u0006 מום \u0005לא היה בהם]?\u0006 ומשיבים: הכוונה \u0003חבלא דנורא\u0004 \u0005[נזק של האש]\u0006 שאש הכבשן לא נגעה בהם, אבל כבר נסתרסו מקודם. ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 כבר \u0003\"וריח נור לא עדת בהון\"\u0004 \u0005[וריח אש לא בא בהם]\u0006 (שם כז), אם כן הרי למדנו כבר שלא פגעה בהם האש! ומשיבים: רצה לומר \u0003לא חבלא\u0004 \u0005[חבלה]\u0006 מצד האש ואפילו \u0003לא ריחא\u0004 \u0005[ריח\u0006 האש\u0005].\u0006","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שנסתרסה עבודה זרה בימיהם\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"כה אמר ה' לסריסים אשר ישמרו את שבתתי\u0004 ובחרו באשר חפצתי ומחזיקים בבריתי\u0003\"\u0004 (ישעיה נו, ד), שכתוב זה מדבר בהם וקורא להם \"סריסים\" בגלל נס שאירע להם. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי נעשו \u0003סריסים ממש,\u0004 וכי \u0003משתעי קרא בגנותא דצדיקי\u0004 \u0005[האם מדבר המקרא בגנות הצדיקים]\u0006 שיזכיר במקרא זה את מומם, ולא יקרא בשמותיהם? ומשיבים: \u0003הא והא הוה בהו\u0004 \u0005[זה וזה היה בהם]\u0006 שהיו סריסים ממש, וכאן נאמר הכינוי גם לשבחם, שזכו שעבודה זרה תיבטל בימיהם.","ושואלים מצד אחר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי נעשו \u0003סריסים ממש\u0004 — מובן המשך הכתובים, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \"ונתתי להם \u0003בביתי ובחומתי יד ושם טוב מבנים ומבנות\u0004 שם עולם אתן לו אשר לא יכרת\" (שם ה). \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שנסתרסה עבודה זרה בימיהם, מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"טוב מבנים ומבנות\"? אמר רב נחמן בר יצחק:\u0004 הכוונה \u0003מבנים שהיו להם כבר ומתו\u0004 ויתנחמו שגם לאלה יהא זכרון. ואגב שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שם עולם אתן לו אשר לא יכרת\"? אמר ר' תנחום, דרש בר קפרא בצפורי\u0004 והסביר: \u0003זה ספר דניאל שנקרא על שמו.\u0004","כיון שהוזכרה המעלה שבקריאת ספר על שמו של אדם גדול, שואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כל מילי\u0004 \u0005[הדברים]\u0006 של ספר \u0003עזרא נחמיה בן חכליה אמרינהו\u0004 \u0005[אמרם]\u0006 וכתב רובם, \u0003ונחמיה בן חכליה מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003ל\u0004\u0003א איקרי סיפרא\u0004 \u0005[נקרא הספר]\u0006 \u0003על שמיה\u0004 \u0005[על שמו],\u0006 שבמשך דורות רבים עוד שנים רבות לאחר תקופת התלמוד לא היה ספר נחמיה אלא ספר עזרא בלבד שכלל את שני הספרים? \u0003אמר ר' ירמיה בר אבא: מפני שהחזיק\u0004 נחמיה \u0003טובה לעצמו\u0004 והתפאר במעשיו הטובים, \u0003שנאמר: \"זכרה לי אלהי לטובה\"\u0004 (נחמיה יג, לא). ושואלים: וכי פגם הוא זה? והרי \u0003דוד\u0004 המלך \u0003נמי מימר אמר\u0004 \u0005[גם כן אמר]\u0006 \u0003\"זכרני ה' ברצון עמך פקדני בישועתך\"\u0004 (תהלים קו, ד)! ומשיבים: \u0003דוד רחמי\u0004 \u0005[רחמים]\u0006 \u0003הוא דקבעי\u0004 \u0005[שביקש],\u0006 ובלשון תפילה אמר, ונחמיה אמר זאת כקביעה וכדרישה שראוי שיזכרו לו לטובה.","\u0003רב יוסף אמר:\u0004 נחמיה נענש \u0003מפני שסיפר בגנותן של ראשונים, שנאמר: \"והפחות הראשונים אשר לפני הכבידו על העם ויקחו מהם בלחם ויין אחר כסף שקלים ארבעים\u0004 גם נעריהם שלטו על העם ואני לא עשיתי כן מפני יראת אלהים\u0003\"\u0004 (נחמיה ה, טו). \u0003ואף על דניאל ש\u0004היה \u0003גדול ממנו סיפר\u0004 דברים אלה של גנות.","ושואלים: \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 שדניאל היה \u0003גדול ממנו?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וראיתי אני דניאל לבדי את המראה והאנשים אשר היו עמי לא ראו את המראה אבל חרדה גדלה נפלה עליהם ויברחו בהחבא\"\u0004 (דניאל י, ז). \u0003\"והאנשים אשר היו עמי לא ראו את המראה\", ומאן נינהו\u0004 \u0005[ומי הם]\u0006 \u0003אנשים\u0004 אלה? \u0003אמר ר' ירמיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חייא בר אבא: זה חגי זכריה ומלאכי\u0004 שהיו עימו ולא ראו, הרי שהיה דניאל גדול אף מן הנביאים הללו, וכל שכן מנחמיה שלא זכה לנבואה."],["אגב הזכרת דניאל עם חגי זכריה ומלאכי, מעירים: \u0003אינהו עדיפי מיניה\u0004 \u0005[הם עדיפים ממנו]\u0006 בדבר, \u0003ואיהו\u0004 \u0005[והוא]\u0006 \u0003עדיף מנייהו\u0004 \u0005[מהם].\u0006 ומפרטים: \u0003אינהו עדיפי מיניה\u0004 \u0005[הם עדיפים ממנו]\u0006 — \u0003דאינהו נביאי\u0004 \u0005[שהם נביאים],\u0006 \u0003ואיהו לאו\u0004 \u0005[והוא לא]\u0006 \u0003נביא,\u0004 שהנביא הוא זה שנשלח על ידי ה' לנבא, ודניאל לא נשלח לנבא. \u0003ואיהו\u0004 \u0005[והוא]\u0006 \u0003עדיף מנייהו\u0004 \u0005[מהם]\u0006 — \u0003דאיהו חזא, ואינהו\u0004 \u0005[שהוא ראה\u0006 את המראה, \u0005והם]\u0006 \u0003לא חזו\u0004 \u0005[ראו].\u0006","ושואלים: \u0003וכי מאחר\u0004 ש\u0003לא חזו\u0004 \u0005[ראו],\u0006 \u0003מאי טעמא איבעות\u0004 \u0005[מה טעם נבהלו]?\u0006 ומשיבים: \u0003אף על גב דאינהו\u0004 \u0005[אף על פי שהם]\u0006 \u0003לא חזו מידי\u0004 \u0005[ראו דבר],\u0006 מכל מקום \u0003מזלייהו חזי\u0004 \u0005[מזלם ראה].\u0006 \u0003אמר רבינא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003האי מאן דמבעית\u0004 \u0005[מי שנבהל]\u0006 פתאום בלא סיבה, \u0003אף על גב דאיהו לא חזי, מזליה חזי\u0004 \u0005[אף על פי שהוא אינו רואה\u0006 סיבה לבהלה זו, \u0005מזלו רואה],\u0006 ויש לו לדאוג לתקנת הדבר.","\u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 \u0003לינשוף מדוכתיה\u0004 \u0005[שיקפוץ ממקומו]\u0006 \u0003ארבעה גרמידי\u0004 \u0005[אמות],\u0006 ויתרחק ממקום שהוא אולי מועד לפורענות. \u0003אי נמי ליקרי\u0004 \u0005[או גם כן שיקרא]\u0006 \u0003קרית שמע\u0004 שתגן עליו. \u0003ואי קאי\u0004 \u0005[ואם עומד]\u0006 \u0003במקום הטנופת\u0004 שאסור לומר בו דברי קדושה, \u0003לימא הכי\u0004 \u0005[שיאמר כך]\u0006 לחש זה: \u0003\"עיזא דבי טבחא שמינא מינאי\"\u0004 \u0005[העז שבבית המטבחיים שמנה ממני],\u0006 שילך המזיק ממנו ויזיק אותה.","אגב הדברים שנאמרו בחזקיה מביאים מה שנאמר: \u0003\"לםרבה המשרה ולשלום אין קץ\u0004 על כסא דוד ועל ממלכתו להכין אותה ולסעדה במשפט ובצדקה מעתה ועד עולם קנאת ה' צבאות תעשה זאת\u0003\"\u0004 (ישעיה ט, ו). \u0003אמר ר' תנחום, דרש בר קפרא בציפורי: מפני מה כל מ\"ם שבאמצע תיבה\u0004 (מלה) \u0003פתוח\u0004 כדרכו, \u0003וזה סתום?\u0004 — מפני ש\u0003ביקש הקדוש ברוך הוא לעשות\u0004 את \u0003חזקיהו משיח, ו\u0004את \u0003סנחריב גוג ומגוג,\u0004 שניבא עליהם ביחזקאל לאחרית הימים, ותהא זו גאולה אחרונה.","\u0003אמרה מדת הדין לפני הקדוש ברוך הוא: רבונו של עולם! ומה דוד מלך ישראל שאמר כמה שירות ותשבחות לפניך\u0004 — \u0003לא עשיתו משיח, חזקיה שעשית לו כל הנסים הללו,\u0004 שניצל מסנחריב ונתרפא מחוליו, \u0003ולא אמר שירה לפניך\u0004 — \u0003תעשהו משיח? לכך נסתתם\u0004 שהיה אז פתח לגאולה ונסתם.","\u0003מיד פתחה הארץ ואמרה לפניו: רבונו של עולם, אני אומרת לפניך שירה תחת צדיק זה, ועשהו משיח. פתחה ואמרה שירה לפניו, שנאמר: \"מכנף הארץ זמרת שמענו צבי לצדיק\u0004 ואמר רזי לי רזי לי אוי לי בוגדים בגדו ובגד בוגדים בגדו\u0003\"\u0004(ישעיה כד, טז).","\u0003אמר שר העולם לפניו: רבונו של עולם! צביונו\u0004 (רצונו) \u0003עשה לצדיק זה! יצאה בת קול ואמרה: \"רזי לי רזי לי\",\u0004 כלומר, דבר זה הוא עדיין בגדר סוד לפי שאיני מביא את הגאולה מיד. \u0003אמר נביא: \"אוי לי, אוי לי\u0004 (ישעיה כד, טז), \u0003עד מתי\u0004 תימשך הגלות \u0003\"?\u0004 \u0003יצאה בת קול ואמרה: \"בגדים בגדו ובגד בוגדים בגדו\"\u0004 (ישעיה כד, טז), \u0003ו\u0004כפירוש לדבר \u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יצחק: עד דאתו בזוזי ובזוזי דבזוזי\u0004 \u0005[שיבואו שודדים ושודדים על שודדים]\u0006 ואז יהיה זמן הגאולה.","מעין דברים אלה נאמרו בנבואה אחרת: \u0003\"משא דומה אלי קרא משעיר שמר מה מלילה שמר מה מליל\"\u0004 (שם כא, יא). \u0003אמר ר' יוחנן: אותו מלאך הממונה על הרוחות \"דומה\" שמו, נתקבצו כל הרוחות\u0004 (הקרויות גם שעירים, \"שעיר\") \u0003אצל דומה, אמרו לו: \"שמר מה מלילה שמר מה מליל\",\u0004 האם אמר שומר ישראל, ה', אם כבר הגיע זמן הגאולה? עונה המלאך \u0003\"אמר שמר אתא בקר וגם לילה אם תבעיון בעיו שבו אתיו\"\u0004 (שם יב). וכאן נתפרשו מעין דברים אלה כך: \"אמר שומר (הקדוש ברוך הוא) אתא בוקר\" — של גאולה, \"וגם לילה\" — של גלות אחריו, \"אם תבעיון\" ותחפצו תשובה לגאולה — \"בעיו\", בקשו, שובו בתשובה, ו\"אתיו\" — ובואו לה'.","\u0003תנא\u0004 \u0005[שנה]\u0006 חכם \u0003משום\u0004 (בשם) \u0003ר' פפייס: גנאי הוא לחזקיה וסייעתו שלא אמרו שירה\u0004 בעצמם, \u0003עד שפתחה הארץ ואמרה שירה, שנאמר: \"מכנף הארץ זמרת שמענו צבי לצדיק\"\u0004 (שם כד, טז). \u0003כיוצא בדבר אתה אומר\u0004 על הכתוב \u0003\"ויאמר יתרו ברוך ה' אשר הציל\u0004 \u0003אתכם\u0004 מיד מצרים ומיד פרעה\u0003\"\u0004 (שמות יח, י). \u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003משום ר' פפייס: גנאי הוא למשה וששים ריבוא\u0004 ישראל שעמו \u0003שלא אמרו \"ברוך\" עד שבא יתרו ואמר \"ברוך ה' \".\u0004","נאמר שם \u0003\"ויחד יתרו\u0004 על כל הטובה אשר עשה ה' לישראל אשר הצילו מיד מצרים\u0003\"\u0004 (שם ט), ובפירוש המלה \"ויחד\" נחלקו \u0003רב ושמואל; רב אמר: שהעביר חרב חדה על בשרו,\u0004 כלומר, מל עצמו. \u0003ושמואל אמר: שנעשה חדודים חדודים\u0004 (דקירות וקמטים) \u0003כל בשרו,\u0004 כלומר, שהרגיש אי נעימות משום מפלת המצרים. \u0003אמר רב: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003גיורא\u0004 \u0005[גר],\u0006 \u0003עד עשרה דרי\u0004 \u0005[דורות]\u0006 \u0003לא תבזה ארמאי קמיה\u0004 \u0005[גוי לפניו],\u0006 שאף שנתגייר או שהוא רק ממשפחת גרים, מכל מקום רגיש הוא לצערם של גויים.","נאמר: \u0003\"לכן ישלח האדון ה' צבאות במשמניו רזון\"\u0004 (ישעיה י, טז), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"במשמניו רזון\"?\u0004 — \u0003אמר הקדוש ברוך הוא: יבא חזקיהו שיש לו שמונה שמות\u0004 (\"משמניו\"), \u0003ויפרע מסנחריב שיש\u0004 גם \u0003לו שמונה שמות.\u0004 ומבארים: \u0003חזקיה\u0004 יש לו שמונה שמות, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי ילד ילד לנו בן נתן לנו ותהי המשרה על שכמו ויקרא שמו פלא יועץ אל גבור אבי עד שר שלום\"\u0004 (שם ט, ה). ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 שם נוסף \u0003\"חזקיה\"!\u0004 ומסבירים: זה אינו שם אלא כינוי על שם מעשיו, מפני \u0003שחזקו יה. דבר אחר: \"חזקיה\"\u0004 נקרא משום \u0003שחיזק את ישראל לאביהם שבשמים\u0004 (יה).","ו\u0003סנחריב\u0004 יש לו שמונה שמות, \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 במלכי אשור: \u0003\"תגלת פלאסר\"\u0004 (מלכים ב' טו, כט), \u0003\"\u0004תלגת \u0003פלנאסר\"\u0004 (דברי הימים ב' כח, כ), \u0003\"שלמנאסר\"\u0004 (מלכים ב' יז, ג), \u0003\"פול\"\u0004 (שם טו, יט), \u0003\"סרגון\"\u0004 (ישעיה כ, א), \u0003\"אסנפר רבא ויקירא\"\u0004 (עזרא ד, י). ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם שם זה \u0003\"סנחריב\"!\u0004 ומסבירים: \u0003שסיחתו\u0004 (שיחתו) \u0003ריב,\u0004 כלומר, דבריו דברי ריב וגנאי הם. \u0003דבר אחר:\u0004 \"סנחריב\" נוטריקון הוא \u0003שסח וניחר דברים כלפי מעלה.\u0004","אגב הזכרת שמותיו \u0003אמר ר' יוחנן: מפני מה זכה אותו רשע לקרותו \"אסנפר רבא ויקירא\"?\u0004 — \u0003מפני שלא סיפר בגנותה של ארץ ישראל, שנאמר: \"עד באי ולקחתי אתכם אל ארץ כארצכם\"\u0004 (מלכים ב, יח, לב), ולא אמר שיש ארץ טובה יותר.","\u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מלך פקח היה\u0004 בדבריו אלה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מלך טיפש היה. למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003מלך פקח היה,\u0004 כך יש להבין: \u0003אי אמינא להו עדיפא מארעייכו\u0004 \u0005[אם אומר להם\u0006 ארץ \u0005עדיפה וטובה מארצכם],\u0006 \u0003אמרו: קא משקרת\u0004 \u0005[משקר אתה],\u0006 \u0003ומאן דאמר\u0004 \u0005[ו\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003מלך טיפש היה,\u0004 אם אינו מבטיח להם יותר, \u0003אם כן מאי רבותיה\u0004 \u0005[מה גדולתו],\u0006 ולשם מה יסכימו לגלות?","ושואלים עוד: \u0003להיכא אגלי להו\u0004 \u0005[להיכן הגלה אותם]\u0006 את עשרת השבטים? \u0003מר זוטרא אמר: לאפריקי, ור' חנינא אמר: להרי סלוג\u0004 (שלג). ומעירים: \u0003אבל ישראל\u0004 עצמם כשגלו \u0003ספרו בגנותה של ארץ ישראל\u0004 ושיבחו את ארץ גלותם. \u0003כי מטו\u0004 \u0005[כאשר הגיעו]\u0006 למקום הקרוי \u0003שוש,\u0004 קראוהו כך משום ש\u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003שויא כי ארעין\u0004 \u0005[שוה היא לארצנו],\u0006 ולכן נקרא \"שוש\" בדומה ל\"שווה\". \u0003כי מטו\u0004 \u0005[כאשר הגיעו]\u0006 למקום הקרוי \u0003עלמין,\u0004 קראוהו כך משום ש\u0003אמרו: כעלמין\u0004 \u0005[כעולמנו,\u0006 כארצנו\u0005]\u0006 הנקראת \"בית עולמים\". \u0003כי מטו\u0004 \u0005[כאשר הגיעו]\u0006 למקום שנקרא אחר כך \u0003שוש תרי, אמרי\u0004 \u0005[אמרו]:\u0006 \u0003על חד תרין\u0004 \u0005[אחת שתים]\u0006 כלומר, טובה פי שתים מארצנו.","על נאמר עוד באותם מקראות המדברים בסנחריב \u0003\"ותחת כבדו יקד יקד כיקוד אש\"\u0004 (ישעיה י, טז). \u0003אמר ר' יוחנן: תחת כבודו\u0004 — \u0003ולא כבודו ממש,\u0004 וכוונתו שהיתה האש תחת לבושיהם ונשרף גופם. \u0003כי הא\u0004 \u0005[כמו זה],\u0006 כפי ש\u0003ר' יוחנן\u0004 בכלל \u0003קרי ליה למאני\u0004 \u0005[קרא להם לבגדיו]\u0006 \u0003\"מכבדותי\". ר' אלעזר אמר: תחת כבודו ממש\u0004 כלומר, תחת בשרו, שהבשר עצמו לא נשרף, \u0003כשריפת בני אהרן. מה להלן\u0004 בבני אהרון היתה זו \u0003שריפת נשמה וגוף קיים\u0004 — \u0003אף כאן\u0004 בחילות סנחריב \u0003שריפת נשמה\u0004 היתה אבל ה\u0003גוף\u0004 נותר \u0003קיים.\u0004","\u0003תנא משמיה\u0004 \u0005[שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' יהושע בן קרחה: פרעה שחירף בעצמו\u0004 את ה' — \u0003נפרע הקדוש ברוך הוא ממנו בעצמו, סנחריב שחירף\u0004"],["\u0003על ידי שליח\u0004 — \u0003נפרע הקדוש ברוך הוא ממנו על ידי שליח.\u0004","כיצד, \u0003פרעה דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 שאמר למשה: \u0003\"מי ה' אשר אשמע בקלו\"\u0004 (שמות ה, ב), \u0003נפרע הקדוש ברוך הוא ממנו בעצמו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וינער ה' את מצרים בתוך הים\"\u0004 (שם יד, כז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"דרכת בים סוסיך\"\u0004 (חבקוק ג, טו). \u0003סנחריב דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 \u0003\"ביד מלאכיך חרפת ה' \"\u0004(מלכים ב' יט, כג), \u0003נפרע הקדוש ברוך הוא ממנו על ידי שליח, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצא מלאך ה' ויך במחנה אשור מאה שמונים וחמשה אלף\"\u0004 (שם לה).","\u0003ר' חנינא בר פפא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בדברי סנחריב: \u0003\"\u0004ואבוא \u0003מרום קצו\"\u0004 (ישעיה לז, כד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק מקביל: \"ואבואה \u0003מלון קצה\"\u0004 (מלכים שם). ויש ליישב, \u0003אמר אותו רשע: בתחלה אחריב דירה של מטה,\u0004 כלומר, בית המקדש שהוא מלון קיצו, \u0003ואחר כך אחריב דירה של מעלה\u0004 (\"מרום קיצו\").","\u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"עתה המבלעדי ה' עליתי על המקום הזה להשחתו ה' אמר אלי עלה על הארץ הזאת והשחיתה\"\u0004 (שם יח, כה), \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 דבר זה, היכן נצטווה להשחית את הארץ? ומסביר: ש\u0003שמע לנביא דקאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"יען כי מאס העם הזה את מי השלח ההולכים לאט ומשוש את רצין ובן רמליהו.\u0004 ולכן הנה ה' מעלה עליהם... את מלך אשור\u0003\"\u0004 (ישעיה ח, ו–ז).","\u0003אמר רב יוסף: אלמלא תרגומא דהאי קרא\u0004 \u0005[התרגום של כתוב זה]\u0006 \u0003לא הוה ידענא מאי קאמר\u0004 \u0005[הייתי יודע מה אמר],\u0006 והתרגום הוא: \u0003חלף דקץ עמא הדין במלכותא\u0004 \u0005[משום שמאס העם הזה במלכותו]\u0006 של \u0003בית דוד דמדבר להון בנייח\u0004 \u0005[שמנהיג אותם בנחת],\u0006 \u0003כמי שילוחא דנגדין בנייח\u0004 \u0005[כמי השילוח ההולכים בנחת],\u0006 \u0003ואיתרעיאו\u0004 \u0005[ורצו]\u0006 \u0003ברצין ובר רמליה.\u0004","באותו ענין \u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מארת ה' בבית רשע ונוה צדיקים יברך\"\u0004 (משלי ג, לג); \u0003\"מארת ה' בבית רשע\"\u0004 — \u0003זה פקח בן רמליהו, שהיה אוכל ארבעים סאה גוזלות בקינוח סעודה,\u0004 שכאילו נשלחה מארה בממונו. \u0003\"ונוה צדיקים יברך\"\u0004 — \u0003זה חזקיה מלך יהודה, שהיה אוכל ליטרא ירק בסעודה\u0004 ומסתפק בכך.","נאמר שם: \u0003\"ולכן הנה ה' מעלה עליהם את מי הנהר העצומים והרבים את מלך אשור\"\u0004 (ישעיה ח, ז). \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וחלף ביהודה שטף ועבר עד צואר יגיע\"\u0004 (שם ח), והוא שרמז רבשקה באומרו שהוא פועל על פי דבר ה'.","ושואלים: אם כן, הרי באמת כך היתה הנבואה! \u0003אלא מאי טעמא איעניש\u0004 \u0005[מה טעם נענש]\u0006 סנחריב שעשה כדבר ה'? ומשיבים: ה\u0003נביא\u0004 על \u0003עשרת השבטים איתנבי\u0004 \u0005[התנבא]\u0006 שאותם יחריבו, \u0003איהו יהיב דעתיה על כולה\u0004 \u0005[הוא נתן דעתו על כל]\u0006 \u0003ירושלים\u0004 להחריבה. \u0003בא\u0004 ה\u0003נביא ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"כי לא מועף לאשר מוצק לה\u0004 כעת הראשון הקל ארצה זבולון וארצה נפתלי והאחרון הכביד דרך הים עבר הירדן גליל הגוים\u0003\"\u0004 (שם כג). \u0003אמר ר' אלעזר בר ברכיה,\u0004 כך יש לדרוש כתוב זה: \u0003אין נמסר עם עייף\u0004 (עסוק) \u0003בתורה\u0004 (\"מועף\") \u0003ביד מי המציק\u0004 (\"מוצק\") \u0003לו.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המשך הכתוב \u0003\"כעת הראשון הקל ארצה זבלון וארצה נפתלי והאחרון הכביד דרך הים עבר הירדן גליל הגוים\"\u0004 — \u0003לא כראשונים\u0004 כגון דורו של אחז \u0003שהקלו מעליהם עול תורה, אבל אחרונים שהכבידו עליהן עול תורה וראויין הללו לעשות להם נס כעוברי הים\u0004 סוף (\"דרך הים\") \u0003וכדורכי הירדן\u0004 (\"עבר הירדן\") שעברו שם ביבשה. \u0003אם חוזר בו\u0004 סנחריב מתכניתו זו — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 חוזר בו — \u0003אני אעשה לו גליל בגוים,\u0004 כלומר, יהא לבושה בין העמים.","נאמר: \u0003\"אחרי הדברים והאמת האלה בא סנחריב מלך אשור ויבא ביהודה ויחן על הערים הבצרות ויאמר לבקעם אליו\"\u0004 (דברי הימים ב' לב, א). ותוהים: \u0003האי רישנא להאי פרדשנא\u0004 \u0005[מתנה זו כתמורה לזה]?!\u0006 וכי אחר שמנה הכתוב כל אותם דברים טובים שעשה חזקיה מספר שכתמורה לכך בא עליו סנחריב?","ומסבירים: \u0003\"אחרי הדברים והאמת\", אחר מאי\u0004 \u0005[מה]?\u0006 ומה הקשר בין הדברים? \u0003אמר רבינא: לאחר שקפץ הקדוש ברוך הוא ונשבע\u0004 (ש\"אמת\" חותמו של הקב\"ה הוא, וסימן לשבועה ולאימות דברים) שיתן את שלל מלך אשור ביד חזקיה, \u0003ואמר:\u0004 \u0003אי אמינא ליה\u0004 \u0005[אם אומר לו]\u0006 \u0003לחזקיה: מייתינא ליה\u0004 \u0005[אביא אותו]\u0006 את \u0003סנחריב ומסרנא ליה\u0004 \u0005[ואמסור אותו]\u0006 \u0003בידך,\u0004 \u0003השתא אמר\u0004 \u0005[עכשיו יאמר]:\u0006 \u0003לא הוא בעינא\u0004 \u0005[אותו אני רוצה]\u0006 \u0003ולא ביעתותיה בעינא\u0004 \u0005[\u0006את \u0005פחדו אני רוצה],\u0006 כלומר, מוותר אני על כל הנס.","\u0003מיד קפץ הקדוש ברוך הוא ונשבע: דמייתינא ליה\u0004 \u0005[שמביא אני אותו],\u0006 \u0003שנאמר: \"נשבע ה' צבאות לאמר אם לא כאשר דמיתי כן היתה וכאשר יעצתי היא תקום. לשבר אשור בארצי ועל הרי אבוסנו וסר מעליהם עלו וסבלו מעל שכמו יסור\"\u0004 (ישעיה יד, כה). וכפירוש לדבר \u0003אמר ר' יוחנן, אמר הקדוש ברוך הוא: יבא סנחריב וסיעתו ויעשה אבוס\u0004 (\"אבוסנו\"), כלומר, מקור פרנסה \u0003לחזקיהו ולסיעתו.\u0004","נאמר על מפלת אשור \u0003\"והיה ביום ההוא יסור סבלו מעל שכמך ועלו מעל צוארך וחבל על מפני שמן\"\u0004 (ישעיה י, כז). וכביאור לדבר \u0003אמר ר' יצחק נפחא: חובל עול של סנחריב מפני שמנו של חזקיהו,\u0004 אותו שמן \u0003שהיה דולק בבתי כנסיות ובבתי מדרשות\u0004 בשעות הלילה שיעסקו ישראל בתורה.","\u0003מה עשה\u0004 חזקיהו להביא את העם ללימוד התורה? \u0003נעץ חרב על פתח בית המדרש\u0004 לסמל ולאיום \u0003ואמר: כל מי שאינו עוסק בתורה ידקר בחרב זו. בדקו מדן ועד באר שבע\u0004 כל גבול ישראל \u0003ולא מצאו עם הארץ\u0004 שאינו יודע כלל. בדקו \u0003מגבת ועד אנטיפרס\u0004 (שהן תחומי ארץ יהודה) \u0003ולא מצאו תינוק ותינוקת, איש ואשה שלא היו בקיאין\u0004 אפילו \u0003בהלכות טומאה וטהרה\u0004 הקשות.","\u0003ועל אותו הדור הוא אומר: \"והיה ביום ההוא יחיה איש עגלת בקר ושתי צאן.\u0004 והיה מרוב עשות חלב \u0003יאכל חמאה כי חמאה ודבש יאכל כל הנותר בקרב הארץ\u0004\u0003\"\u0004 (ישעיה ז, כא–כב), \u0003ואומר\u0004 בהמשך הדברים: \u0003\"והיה ביום ההוא יהיה כל מקום אשר יהיה שם אלף גפן באלף כסף לשמיר ולשית יהיה\"\u0004 (ישעיה ז, כג). וכוונת הדברים היא ש\u0003אף על פי שאלף גפן באלף כסף\u0004 ואפשר יהיה להפיק רווחים עצומים — מכל מקום \u0003לשמיר ולשית יהיה,\u0004 בכל זאת לא יעבדו שטחים אלה משום שהכל הקדישו עצמם ללימוד התורה ולא עסקו במלאכה אלא לפרנסתם בצמצום.","נאמר \u0003\"ואסף שללכם אסף החסיל\u0004 כמשק גבים שוקק בו\u0003\"\u0004 (שם לג, ד), \u0003אמר להם\u0004 ה\u0003נביא לישראל: אספו שללכם\u0004 מחילות סנחריב. \u0003אמרו לו: לבזוז,\u0004 שכל אחד יקח לעצמו את שללו, \u0003או לחלוק\u0004 אותו שלל למלכות? \u0003אמר להם: כ\"אסף החסיל\", מה אסף החסיל\u0004 — \u0003כל אחד ואחד\u0004 מן החגבים אוכל \u0003לעצמו, אף שללכם\u0004 — \u0003כל אחד ואחד\u0004 יטול את שללו \u0003לעצמו.\u0004","\u0003אמרו לו: והלא ממון עשרת השבטים מעורב בו,\u0004 שהרי בתוך הרכוש של צבא סנחריב נמצא גם ממון ישראל של עשרת השבטים, ואין לנו רשות לקחתו משום איסור גזל! \u0003אמר להם: \"כמשק גבים שקק בו\"\u0004 (ישעיה ז, כג), \u0003מה גבים\u0004 (מקוות מים) \u0003הללו מעלין את האדם מטומאה לטהרה\u0004 כשטובל בהם — \u0003אף ממונם של ישראל, כיון שנפל ביד גוים\u0004 נתייאשו ממנו בעליו ו\u0003מיד טיהר\u0004 ויכולים ישראל לקחתו בלי חשש. ומעירים: \u0003כ\u0004דברי \u0003רב פפא.\u0004 ש\u0003אמר רב פפא: עמון ומואב טהרו בסיחון\u0004 שאף שאסר ה' לכבוש מעמון ומואב, ואולם מה שכבש סיחון מעמון ומואב לא חל עליו עוד האיסור הזה, ונעשה מותר (טהור) לישראל לכבשו.","\u0003אמר רב הונא: עשר מסעות נסע אותו רשע\u0004 סנחריב \u0003באותו היום, שנאמר: \"בא על עית עבר במגרון למכמש יפקיד כליו. עברו מעברה גבע מלון לנו חרדה הרמה גבעת שאול נסה. צהלי קולך בת גלים הקשיבה לישה עניה ענתות. נדדה מדמנה ישבי הגבים העיזו. עוד היום בנב לעמד ינפף ידו הר בת ציון גבעת ירושל ם\"\u0004 (ישעיה י, כח–לב) שבכל מקומות אלה עבר ביום אחד.","ומקשים: \u0003הני טובא הויין\u0004 \u0005[אלה הרבה הם]\u0006 יותר מעשרה! ומשיבים: הכתוב \u0003\"צהלי קולך בת גלים\", נביא הוא דקאמר\u0004 \u0005[שאמר]\u0006 \u0003לה לכנסת ישראל,\u0004 וכך פירושו: \u0003\"צהלי קולך בת גלים\"\u0004 — \u0003בתו של אברהם יצחק ויעקב שעשו מצות\u0004 רבות \u0003כגלי הים. \"הקשיבה לישה\"\u0004 — \u0003מהאי לא תסתפי\u0004 \u0005[מזה,\u0006 מסנחריב, \u0005אל תפחדי],\u0006 \u0003אלא איסתפי\u0004 \u0005[פחדי]\u0006 \u0003מנבוכדנצר הרשע דמתיל\u0004 \u0005[שנמשל]\u0006 \u0003כאריה\u0004 (ואריה הוא \"ליש\"), \u0003שנאמר\u0004 בו \u0003\"עלה אריה מסבכו\"\u0004 (ירמיה ד, ז).","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006"],["\u0003\"עניה ענתות\"\u0004 (ישעיה י, ל) — \u0003עתיד ירמיה בן חלקיה ומתנבא עלה\u0004 \u0005[עליה]\u0006 \u0003מענתות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"דברי ירמיהו בן חלקיהו מן הכהנים אשר בענתות בארץ בנימן\"\u0004 (ירמיה א, א).","ומקשים: \u0003מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 והלא \u0003התם\u0004 \u0005[שם]\u0006 בירמיהו נקרא נבוכדנצר \u0003\"ארי\",\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 נאמר \u0003\"ליש\"! אמר ר' יוחנן:\u0004 אין זו סתירה, כי \u0003ששה שמות יש לארי,\u0004 ו\u0003אלו הן: ארי, כפיר, לביא, ליש, שחל, שחץ.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שאינו מחשיב פסוק זה למסעות סנחריב, אם כן \u0003בצרו להו\u0004 \u0005[מעטו להם]\u0006 ושוב אין כאן עשרה שמות של מקומות! ומשיבים: \u0003\"עברו מעברה\" תרתי נינהו\u0004 \u0005[שנים,\u0006 שני מקומות, \u0005הם].\u0006","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עוד היום בנב לעמד\"\u0004 (ישעיה י, לב)? \u0003אמר רב הונא: אותו היום\u0004 הוא ש\u0003נשתייר מעונה של נוב,\u0004 שעד אז היה עוון זה תלוי עוד בישראל, \u0003אמרי ליה כלדאי\u0004 \u0005[אמרו לו החוזים בכוכבים]\u0006 לסנחריב: \u0003אי אזלת האידנא\u0004 \u0005[אם תלך\u0006 ותכבוש \u0005עכשיו]\u0006 — \u0003יכלת\u0004 \u0005[תוכל]\u0006 \u0003לה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תכבשנה עכשיו — \u0003לא יכלת\u0004 \u0005[תוכל]\u0006 \u0003לה.\u0004 מסופר: \u0003אורחא דבעא לסגויי\u0004 \u0005[דרך שהיה צריך ללכת]\u0006 \u0003בעשרה יומא\u0004 \u0005[ימים]\u0006 \u0003סגא בחד יומא\u0004 \u0005[הלך ביום אחד]\u0006 כדי להגיע,","\u0003כי מטו\u0004 \u0005[כאשר הגיעו]\u0006 \u0003לירושלם שדי ליה ביסתרקי\u0004 \u0005[זרקו לו מצעות],\u0006 \u0003עד דסליק ויתיב מעילוי שורה\u0004 \u0005[שעלה וישב\u0006 בגובה \u0005מעל החומה],\u0006 \u0003עד דחזיוה לכולה\u0004 \u0005[שראה את כל]\u0006 \u0003ירושלם. כי חזייה, איזוטר בעיניה\u0004 \u0005[כאשר ראה אותה, היתה קטנה בעיניו],\u0006 \u0003אמר: הלא דא\u0004 \u0005[זו]\u0006 \u0003היא קרתא דירושלם דעלה ארגישית\u0004 \u0005[העיר ירושלים שעליה הרעשתי]\u0006 את \u0003כל משיריתי\u0004 \u0005[מחנותי],\u0006 \u0003ועלה כבשית\u0004 \u0005[ועליה,\u0006 בשבילה \u0005כבשתי]\u0006 את \u0003כל מדינתא\u0004 \u0005[המדינות]?\u0006 \u0003הלא היא זעירא וחלשא\u0004 \u0005[קטנה וחלשה]\u0006 \u0003מכל כרכי עממיא דכבשית בתקוף\u0004 \u0005[ערי העמים שכבשתי בחוזק]\u0006 \u0003ידי.\u0004 \u0003עלה וקם ומניד ברישיה\u0004 \u0005[ועמד והניד בראשו\u0006 בבוז\u0005],\u0006 \u0003מוביל ומייתי בידיה\u0004 \u0005[הוליך והביא,\u0006 והניף \u0005בידו]\u0006 \u0003על טור\u0004 \u0005[הר]\u0006 \u0003בית מקדשא\u0004 \u0005[המקדש]\u0006 ש\u0003בציון ועל עזרתא דבירושלם\u0004 \u0005[העזרה שבירושלים].\u0006","\u0003אמרי\u0004 \u0005[אמרו]\u0006 לו שריו: \u0003נישדי ביה ידא האידנא\u0004 \u0005[נשים בה יד כעת]\u0006 להתחיל לכבשה! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תמהיתו\u0004 \u0005[עייפים אתם],\u0006 \u0003למחר אייתי\u0004 \u0005[יביא]\u0006 \u0003לי כל חד וחד מינייכו גולמו הרג מיניה\u0004 \u0005[אחד ואחד מכם פירור\u0006 אבן כדי \u0005חותמו ממנה,\u0006 מן החומה\u0005],\u0006 ודי יהא בכך כדי לכבשה. \u0003מיד \"ויהי בלילה ההוא ויצא מלאך ה' ויך במחנה אשור מאה שמונים וחמשה אלף וישכימו בבקר והנה כלם פגרים מתים\"\u0004 (מלכים ב' יט, לה). \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003\"בת דינא\u0004 — \u0003בטל דינא\"\u0004 \u0005[לן הדין\u0006 — \u0005בטל הדין],\u0006 שפעמים שנדחה דבר זמן מסוים ושוב אין לו קיום, וכיון שבאותו היום לא נכבשה העיר בטלה מעליה הגזירה.","וכיון שהוזכר עונש בעוון נוב מביאים מעשה אחר הקשור לכך. נאמר: \u0003\"וישבי בנב אשר בילידי הרפה ומשקל קינו שלש מאות משקל נחשת והוא חגור חדשה ויאמר להכות את דוד\"\u0004 (שמואל ב' כא, טז). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וישבי בנב\"? אמר רב יהודה אמר רב:\u0004 זהו \u0003איש שבא\u0004 להעניש את דוד \u0003על עסקי נוב. אמר ליה\u0004 \u0005[לו]\u0006 \u0003הקדוש ברוך הוא לדוד: עד מתי יהיה עון זה טמון בידך\u0004 ולא תיענש עליו? הרי \u0003על ידך נהרגה נוב עיר הכהנים, ועל ידך נטרד\u0004 מן העולם הבא \u0003דואג האדומי, ועל ידך נהרגו שאול ושלשת בניו,\u0004 שהרי דוד בבואו לנוב ובהטעותו את אחימלך הכהן גרם לכל השתלשלות הדברים, ואם כן צריך אתה להיענש, אלא שבידך לבחור את העונש,","\u0003רצונך יכלו זרעך או תמסר ביד אויב? אמר לפניו: רבונו של עולם! מוטב אמסר ביד אויב ולא יכלה זרעי.\u0004","\u0003יומא חד נפק לשכור בזאי\u0004 \u0005[יום אחד יצא לצוד ב\u0006סיוע העוף הדורס \u0005נץ],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 ה\u0003שטן ואידמי ליה כטביא\u0004 \u0005[ונדמה לו כצבי],\u0006 \u0003פתק ביה גירא\u0004 \u0005[זרק בו חץ]\u0006 \u0003ולא מטייה\u0004 \u0005[הגיעו].\u0006 \u0003משכיה\u0004 \u0005[משכו]\u0006 אחריו \u0003עד דאמטייה\u0004 \u0005[שהביאו]\u0006 \u0003לארץ פלשתים. כדחזייה\u0004 \u0005[כאשר ראה אותו]\u0006 \u0003ישבי בנוב אמר: היינו האי דקטליה\u0004 \u0005[זה הוא שהרג]\u0006 את \u0003גלית אחי. כפתיה, קמטיה, אותביה ושדייה תותי בי בדייא\u0004 \u0005[קשרו, קפלו, שמו בארץ והניחו תחת קורת בית הבד]\u0006 שיתמעך שם. \u0003אתעביד ליה ניסא, מכא ליה ארעא מתותיה\u0004 \u0005[נעשה לו נס,\u0006 ו\u0005נתמעכה,\u0006 נפתחה, \u0005לו הארץ מתחתיו]\u0006 ונעשה רווח ולא ניזוק. \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"תרחיב צעדי תחתי ולא מעדו קרסלי\"\u0004 (תהלים יח, לז).","מסופר: \u0003ההוא יומא אפניא דמעלי שבתא הוה\u0004 \u0005[אותו יום לפנות ערב של ערב שבת היה],\u0006 \u0003אבישי בן צרויה הוה קא חייף רישיה בארבעא גרבי דמיא\u0004 \u0005[היה חופף את ראשו\u0006 לכבוד שבת \u0005בארבעה כדי מים],\u0006 \u0003חזינהו כתמי דמא\u0004 \u0005[ראה\u0006 שם \u0005כתמי דם].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אתא\u0004 \u0005[באה]\u0006 \u0003יונה איטריף קמיה\u0004 \u0005[וטרפה,\u0006 נענעה בכנפיה, \u0005לפניו],\u0006 \u0003אמר: כנסת ישראל ליונה אימתילא\u0004 \u0005[נמשלה],\u0006 \u0003שנאמר: \"כנפי יונה נחפה בכסף\u0004 ואברותיה בירקרק חרוץ\u0003\"\u0004 (תהלים סח, יד), \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003דוד מלכא\u0004 \u0005[מלך]\u0006 \u0003ישראל בצערא שרי\u0004 \u0005[בצער נתון].\u0006 \u0003אתא לביתיה\u0004 \u0005[בא לביתו]\u0006 של דוד \u0003ולא אשכחיה\u0004 \u0005[מצאו],\u0006 והבין שנעלם. \u0003אמר, תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין רוכבין על סוסו\u0004 של המלך \u0003ואין יושבין על כסאו ואין משתמשין בשרביטו, בשעת הסכנה מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אתא שאיל בי מדרשא\u0004 \u0005[הלך ושאל בבית המדרש]\u0006 מה עושים בכגון זה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בשעת הסכנה שפיר דמי\u0004 \u0005[יפה,\u0006 מותר\u0005].\u0006","\u0003רכביה לפרדיה וקם ואזל\u0004 \u0005[רכב על פרדו\u0006 של המלך \u0005ועמד והלך],\u0006 \u0003קפצה ליה ארעא\u0004 \u0005[לו הארץ]\u0006 בנס, והגיע במהרה. \u0003בהדי דקא מסגי חזייה לערפה אמיה דהוות נוולא\u0004 \u0005[בעוד שהוא הולך ראה את ערפה אמו\u0006 של ישבי \u0005ש\u0006היא \u0005טווה\u0006 בפלך\u0005],\u0006 \u0003כי חזיתיה, פסקתה לפילכה, שדתיה עילויה, סברא למקטליה\u0004 \u0005[כאשר ראתה אותו, התירה את הפלך, השליכה עליו,\u0006 ו\u0005חשבה להורגו\u0006 בו\u0005],\u0006 כיון שלא הצליחה \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לאבישי: \u0003עלם\u0004 (בחור) \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003לי\u0004 את ה\u0003פלך!\u0004 \u0003פתקיה\u0004 \u0005[זרקו]\u0006 את הפלך, \u0003בריש\u0004 \u0005[בראש]\u0006 \u0003מוחה, וקטלה\u0004 \u0005[והרגה].\u0006","\u0003כד חזייה\u0004 \u0005[כאשר ראה אותו]\u0006 \u0003ישבי בנוב אמר: השתא הוו בי תרין וקטלין לי\u0004 \u0005[עכשיו הרי הם שנים,\u0006 דוד ואבישי, \u0005ויהרגו אותי].\u0006 \u0003פתקיה\u0004 \u0005[זרק]\u0006 את \u0003דוד לעילא\u0004 \u0005[למעלה],\u0006 \u0003ודץ ליה לרומחיה\u0004 \u0005[ותקע אותו, את רומחו\u0006 בארץ\u0005],\u0006 \u0003אמר: ניפול עלה ונקטל\u0004 \u0005[יפול עליו ויהרג].\u0006 \u0003אמר אבישי שם\u0004 מן השמות הקדושים, \u0003אוקמיה\u0004 \u0005[העמיד]\u0006 את \u0003דוד בין שמיא לארעא\u0004 \u0005[השמים לארץ]\u0006 שלא יפול.","ושואלים בדרך אגב: \u0003ונימא ליה איהו\u0004 \u0005[ושיאמר הוא,\u0006 דוד עצמו\u0005]\u0006 שם וינצל, ומדוע הוצרך לאבישי? ומשיבים: מקובלים אנו כי כשם ש\u0003אין חבוש\u0004 (אסיר) \u0003מוציא עצמו מבית האסורין\u0004 והוא זקוק לאחר שיוציאנו, כך הוא בדברים אלה, שהנתון בסכנה אינו מסוגל לפעול.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אבישי לדוד: \u0003מאי בעית הכא\u0004 \u0005[מה צריך אתה כאן]\u0006 ומה טעם נפלת בידו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר לי קודשא בריך\u0004 \u0005[הקדוש ברוך]\u0006 \u0003הוא, והכי אהדרי ליה\u0004 \u0005[וכך החזרתי לו],\u0006 ומסתבר שהגיע הזמן שאמסר ביד אוייב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבישי: \u0003אפיך צלותיך\u0004 \u0005[הפוך את תפילתך]\u0006 ובקש שלך לא יאונה דבר, כפי הפתגם המקובל: \u0003\"בר ברך קירא ליזבון\"\u0004 \u0005[בן בנך\u0006 שיהיה רוכל עני \u0005וימכור שעוה]\u0006 \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003לא תצטער,\u0004 כלומר, אל תצמצם הוצאותיך כדי להשאיר ירושה לבניך.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003סייע בהדן\u0004 \u0005[לי].\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ויעזר לו אבישי בן צרויה\u0004 ויך את הפלשתי וימתהו\u0003\"\u0004 (שמואל ב' כא, יז). \u0003אמר רב יהודה אמר רב:\u0004 הכוונה היא \u0003שעזרו בתפלה. אמר אבישי שם\u0004 קדוש אחר \u0003ואחתיה\u0004 \u0005[והורידו]\u0006 לדוד מהיותו תלוי באויר וברחו.","\u0003הוה קא רדיף בתרייהו\u0004 \u0005[היה רודף\u0006 ישבי \u0005אחריהם\u0006 להורגם\u0005],\u0006 \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 למקום הנקרא \u0003\"קובי\" אמרי\u0004 \u0005[אמרו\u0006 הם\u0005]:\u0006 \u0003קום ביה\u0004 \u0005[נעמוד בו]\u0006 ונתגונן. \u0003כי מטא\u0004 \u0005[כאשר הגיעו]\u0006 למקום שנקרא \u0003\"בי תרי\" אמרי\u0004 \u0005[אמרו\u0006 הם\u0005]:\u0006 \u0003בתרי גוריין קטלוה לאריא\u0004 \u0005[בשני גורים הרגו את האריה],\u0006 כלומר, יכולים אנו לעשות זאת. \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003זיל אשתכח\u0004 \u0005[לך מצא את]\u0006 \u0003ערפה אימיך בקיברא\u0004 \u0005[אמך בקבר].\u0006 \u0003כי אדכרו ליה שמא דאימיה\u0004 \u0005[כאשר הזכירו לו\u0006 את \u0005שם אמו]\u0006 וסיפרו לו שמתה, \u0003כחש חיליה, וקטליה\u0004 \u0005[התמעט כוחו, והרגהו].\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"אז נשבעו אנשי דוד לו לאמר לא תצא עוד אתנו למלחמה ולא תכבה את נר ישראל\"\u0004 (שמואל ב' כא יז).","ועוד לענין קפיצת הדרך. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה קפצה להם הארץ\u0004 והגיעו למקום חפצם במהרה בדרך נס: \u0003אליעזר עבד אברהם, ויעקב אבינו, ואבישי בן צרויה.\u0004 ומפרשים: \u0003אבישי בן צרויה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006 \u0003אליעזר עבד אברהם\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואבא היום אל העין\"\u0004 (בראשית כד, מב), \u0003למימרא דההוא יומא נפק\u0004 \u0005[לומר\u0006 לבני המשפחה \u0005שבאותו יום יצא]\u0006 ובאותו יום בא, שידעו כמה ניסים נעשים לו בזכות אברהם. \u0003יעקב אבינו\u0004 —"],["\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצא יעקב מבאר שבע וילך חרנה\"\u0004 (בראשית כח, י), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך (לכאורה אחר היותו בחרן): \u0003\"ויפגע במקום וילן שם כי בא השמש\"\u0004 (בראשית כח יא). וכך יש להבין: \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003לחרן, אמר\u0004 יעקב: \u0003אפשר עברתי על מקום שהתפללו בו אבותי ואני לא התפללתי בו? בעי למיהדר\u0004 \u0005[רצה לחזור],\u0006 \u0003כיון\u0004 ש\u0003הרהר בדעתיה למיהדר\u0004 \u0005[בדעתו לחזור]\u0006 \u0003קפצה ליה ארעא\u0004 \u0005[לו הארץ],\u0006 \u0003מיד \"ויפגע במקום\",\u0004 שנזדמן לו לפתע, והוא לשון \"פגיעה\".","\u0003דבר אחר: אין \"פגיעה\" אלא\u0004 לשון \u0003תפלה, שנאמר: \"ואתה אל תתפלל בעד העם הזה ואל תשא בעדם רנה ותפלה ואל תפגע בי\"\u0004 (ירמיה ז, טז).","נאמר ביעקב \u0003\"וילן שם כי בא השמש\"\u0004 (בראשית כח, יא), \u0003בתר דצלי בעי למיהדר\u0004 \u0005[אחר שהתפלל רצה לחזור\u0006 לדרכו\u0005],\u0006 \u0003אמר הקדוש ברוך הוא: צדיק זה בא לבית מלוני\u0004 ו\u0003יפטר בלא לינה? מיד בא השמש\u0004 שלא בזמנו, \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 ביעקב: \u0003\"ויזרח לו השמש\u0004 כאשר עבר את פנואל\u0003\"\u0004 (בראשית שם לב, לא), \u0003וכי לו בלבד זרחה? והלא לכל העולם כולו זרחה! אלא אמר ר' יצחק: שמש שבא בעבורו,\u0004 שלא בזמנו, \u0003זרחה בעבורו\u0004 שלא בזמנה, ותיקן שוב סדר הזמנים.","ולענין תפילת דוד שהפכה ובקש שיכלה זרעו, \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003כלה זרעיה\u0004 \u0005[זרעו]\u0006 של \u0003דוד?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ועתליה אם אחזיהו ראתה כי מת בנה ותקם ותאבד את כל זרע הממלכה\"\u0004 (מלכים ב' יא, א). ומקשים: והרי לא כלה כל זרעו, \u0003והא אשתייר ליה\u0004 \u0005[והרי נשאר לו]\u0006 \u0003יואש\u0004 מבניו! ומשיבים: \u0003התם נמי אשתייר\u0004 \u0005[שם גם כן,\u0006 בנוב, \u0005נשאר]\u0006 \u0003אביתר\u0004 מן הכהנים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימלט בן אחד לאחימלך בן אחטוב ושמו אביתר\"\u0004 (שמואל א' כב, כ). \u0003אמר רב יהודה אמר רב: אלמלא לא נשתייר אביתר לאחימלך בן אחיטוב, לא נשתייר מזרעו של דוד שריד ופליט.\u0004","ושוב לענין סנחריב. \u0003אמר רב יהודה אמר רב: בא עליהם סנחריב הרשע בארבעים וחמשה אלף איש בני מלכים יושבים בקרונות של זהב, ועמהן שגלונות\u0004 (נשים) \u0003וזונות. ובשמנים אלף גבורים לבושי שריון קליפה, ובששים אלף אחוזי חרב רצים לפניו, והשאר פרשים. ו\u0004כמו \u0003כן, באו על אברהם\u0004 כשעלו ארבעת המלכים להילחם בארץ כנען, \u0003וכן עתידין לבוא עם גוג ומגוג.\u0004","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003אורך מחנהו\u0004 של סנחריב \u0003ארבע מאות פרסי\u0004 \u0005[פרסאות],\u0006 \u0003רחב צואר סוסיו\u0004 אם יעמידום יחד \u0003ארבעים פרסי\u0004 \u0005[פרסאות],\u0006 \u0003סך מחנהו מאתים וששים ריבוא אלפים חסר חד\u0004 \u0005[אחד].\u0006 \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי:\u0004 מהו חסר אחד, האם \u0003חסר חד ריבויא\u0004 \u0005[ריבוא אחד],\u0006 \u0003או חסר חד אלפא\u0004 \u0005[אלף אחד],\u0006 \u0003או חסר מאה, או חסר חד\u0004 \u0005[אחד]?\u0006 לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003ראשונים\u0004 בחילו של סנחריב \u0003עברו\u0004 את הירדן \u0003בשחי\u0004 (בשחיה), \u0003שנאמר: \"וחלף ביהודה שטף ועבר\"\u0004 (ישעיה ח, ח), ועל ידי מעברם נתמעטו המים עד ש\u0003אמצעיים עברו בקומה, שנאמר: \"עד צואר יגיע\"\u0004 (ישעיה ח, ח), \u0003אחרונים\u0004 כבר \u0003העלו עפר ברגליהם ולא מצאו מים בנהר לשתות, עד שהביאו מים ממקום אחר, ושתו, שנאמר: \"אני קרתי ושתיתי מים\"\u0004 (שם לז, כה).","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויצא מלאך ה' ויכה במחנה אשור מאה ושמונים וחמשה אלף וישכימו בבקר והנה כלם פגרים מתים\"\u0004 (שם לו), הרי שלא היה מספרם גדול כל כך! \u0003אמר ר' אבהו: הללו\u0004 שנמנו כאן \u0003ראשי גייסות הן,\u0004 ולכל אחד מהם חיילים רבים הכפופים לו.","\u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מלשון הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004לכן ישלח האדון ה'... \u0003במשמניו רזון\"\u0004 (שם י, טז), משמע: \u0003בשמינים\u0004 (החשובים) \u0003דאית בהו\u0004 \u0005[שיש בהם].\u0006 \u0003אמר רבינא: דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 במפורש: \u0003\"וישלח ה' מלאך ויכחד כל גבור חיל ונגיד ושר במחנה\u0004 מלך אשור וישב בבושת פנים לארצו \u0003ויבא בית אלהיו ומיציאי מעיו שם הפילהו בחרב\"\u0004 (דברי הימים ב' לב, כא). ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך היה.","ושואלים: \u0003במה הכם\u0004 המלאך? \u0003ר' אליעזר אומר: ביד הכם, שנאמר: \"וירא ישראל את היד הגדלה\"\u0004 (שמות יד, לא) בה\"א הידיעה, לומר ש\u0003יד\u0004 זו עוד \u0003עתידה ליפרע מסנחריב. ר' יהושע אומר: באצבע הכם, שנאמר: \"ויאמרו החרטמם אל פרעה אצבע אלהים הוא\"\u0004 (שם ח, טו), \u0003היא אצבע שעתידה ליפרע מסנחריב. ר' אליעזר בנו של ר' יוסי הגלילי אומר: אמר לו הקדוש ברוך הוא לגבריאל:\u0004 האם \u0003מגלך נטושה,\u0004 כלומר, מחודד ולטוש? \u0003אמר לפניו: רבונו של עולם, נטושה ועומדת מששת ימי בראשית\u0004 — \u0003שנאמר:\u0004 \"כי \u0003מפני חרבות נדדו\u0004 מפני חרב נטושה\" (ישעיה כא, טו).","\u0003ר' שמעון בן יוחי אומר: אותו הפרק זמן בישול פירות היה, אמר לו הקדוש ברוך הוא לגבריאל: כשאתה יוצא לבשל פירות\u0004 — \u0003הזקק להם\u0004 לצבא אשור והשמידם, \u0003שנאמר: \"מדי עברו יקח אתכם כי בבקר בבקר יעבר ביום ובלילה והיה רק זועה הבין שמועה\"\u0004 (שם כח, יט), כלומר, כבדרך אגב ייהרגו אלה. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם מקובל: \u0003\"אגב אורחך, לבעל דבבך אישתמע\"\u0004 \u0005[בתוך דרכך, לשונאך השמע]\u0006 והצק לו.","\u0003ויש אומרים: בחוטמן נשף בהן ומתו, שנאמר: \"וגם נשף בהם ויבשו\"\u0004 (שם מ, כד). \u0003ר' ירמיה בר אבא אמר: כפיים ספק\u0004 (הכה) \u0003להם, ומתו, שנאמר: \"וגם אני אכה כפי אל כפי והנחתי חמתי\"\u0004 (יחזקאל כא, כב). \u0003ר' יצחק נפחא אמר: אזנים גלה להם, ושמעו שירה מפי חיות\u0004 המרכבה שמשבחות לה', \u0003ומתו, שנאמר: \"מרממתך נפצו גוים\"\u0004 (ישעיה לג, ג), שמגלוי רוממות זה מתו.","\u0003וכמה נשתייר מהם? רב אמר: עשרה, שנאמר: \"ושאר עץ יערו מספר יהיו ונער יכתבם\"\u0004 (שם י, יט), \u0003כמה נער יכול לכתוב,\u0004 כלומר, מהי גודל טיפת הדיו אותה יכול נער להטיף — כגודל האות י', שהיא מנין \u0003עשרה. ושמואל אמר: תשעה\u0004 נשארו, \u0003שנאמר: \"ונשאר בו עללות כנקף זית שנים שלשה גרגרים בראש אמיר ארבעה חמשה בסעפיה\"\u0004 (שם יז, ו), וארבעה וחמישה הם ביחד תשעה.","\u0003ר' יהושע בן לוי אמר:\u0004 נשתיירו מהם \u0003ארבעה עשר, שנאמר: \"שנים שלשה... ארבעה וחמשה\". ר' יוחנן אמר\u0004 כי בסך הכל \u0003חמשה\u0004 נשארו: \u0003סנחריב ושני בניו, נבוכדנצר ונבוזר אדן\u0004 רב הטבחים שלו. מה שאמרנו ש\u0003נבוזר אדן\u0004 היה ביניהם, \u0003גמרא\u0004 \u0005[מסורת]\u0006 היא בידינו. \u0003נבוכדנצר\u0004 יודעים אנו שהיה שם, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שנבוכדנצר אמר כשראה מלאך עם חנניה מישאל ועזריה: \u0003\"ורוה די רבעאה דמה לבר אלהין\"\u0004 \u0005[מראה הרביעי דומה למלאך]\u0006 (דניאל ג, כה), \u0003ואי לאו דחזייה, מנא הוה ידע\u0004 \u0005[אם לא שראה אותו,\u0006 את המלאך, \u0005מנין\u0006 \u0005ידע]\u0006 כיצד נראה מלאך? \u0003סנחריב ושני בניו\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ויהי הוא משתחוה בית נסרך אלהיו ואדרמלך ושראצר בניו הכהו בחרב\"\u0004 (מלכים ב' יט, לז), משמע ששלשתם נשארו.","\u0003אמר ר' אבהו: אלמלא מקרא כתוב\u0004 בענין זה \u0003אי אפשר לאמרו,\u0004 לפי שהוא נראה כחילול ה', \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ביום ההוא יגלח ה' בתער השכירה בעברי נהר במלך אשור את הראש ושער הרגלים וגם את הזקן תספה\"\u0004 (ישעיה ז, כ), שמשמע שהקדוש ברוך הוא בעצמו גילח את סנחריב.","וכך יש לספר את המעשה: \u0003אתא קודשא בריך הוא, ואדמי ליה כגברא סבא\u0004 \u0005[בא הקדוש ברוך הוא, ונדמה לו\u0006 לסנחריב \u0005כאיש זקן],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי אזלת לגבי\u0004 \u0005[כאשר תלך אצל]\u0006 \u0003מלכי מזרח ומערב דאייתיתינהו לבנייהו וקטלתינהו\u0004 \u0005[שהבאת את בניהם\u0006 עמך \u0005והרגתם],\u0006 \u0003מאי אמרת להו\u0004 \u0005[מה תאמר להם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 סנחריב לקדוש ברוך הוא: \u0003ההוא גברא בההוא פחדא נמי יתיב\u0004 \u0005[אותו אדם,\u0006 כלומר, אני, \u0005גם כן באותו פחד אני יושב]\u0006 ואיני יודע מה לעשות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 סנחריב לקדוש ברוך הוא: \u0003היכי נעביד\u0004 \u0005[מה אעשה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקדוש ברוך הוא: \u0003זיל\u0004 \u0005[לך]\u0006"],["\u0003ושני נפשך\u0004 \u0005[ושנה עצמך]\u0006 שלא יכירוך. שאל אותו סנחריב: \u0003במאי אישני\u0004 \u0005[במה אשנה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי מספרא, ואיגזייך אנא\u0004 \u0005[מספריים, ואגזוז אותך אני]\u0006 שאל סנחריב: \u0003מהיכא אייתי\u0004 \u0005[מהיכן אביא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקדוש ברוך הוא: \u0003עול לההוא ביתא ואייתי\u0004 \u0005[לך לאותו בית והבא].\u0006 \u0003אזל אשכחינהו\u0004 \u0005[הלך מצאם],\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003מלאכי שרת ואידמו ליה כגברי\u0004 \u0005[ונדמו לו כבני אדם],\u0006 \u0003והוו קא טחני קשייתא\u0004 \u0005[והיו טוחנים גרעיני תמרים].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 סנחריב: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי מספרא\u0004 \u0005[מספריים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 מלאכי השרת: \u0003טחון חד גריוא דקשייתא\u0004 \u0005[סאה אחת של גרעינים]\u0006 \u0003וניתן לך.\u0004 \u0003טחן חד גריוא דקשייתא ויהבו ליה מספרתא\u0004 \u0005[סאה אחת של גרעינים ונתנו לו מספריים].\u0006 \u0003עד דאתא\u0004 \u0005[שבא],\u0006 \u0003איחשך\u0004 \u0005[חשך היום].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקדוש ברוך הוא לסנחריב: \u0003זיל אייתי נורא\u0004 \u0005[לך הבא אש]\u0006 להאיר. \u0003אזל ואייתי נורא\u0004 \u0005[הלך\u0006 סנחריב \u0005והביא אש].\u0006 \u0003בהדי דקא נפח ליה, אתלי ביה נורא בדיקניה, אזל גזייה לרישיה ודיקניה\u0004 \u0005[בעוד שהוא נופח\u0006 באש ללבותה, \u0005אחזה האש בזקנו, הלכה וגלחה את ראשו וזקנו]\u0006 \u0003אמרו: היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"וגם את הזקן תספה\"\u0004 (ישעיה ז, כ). \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם]\u0006 כפתגם עממי: \u0003\"גרירתיה לארמאה שפיר ליה\u0004 \u0005[אם חרכת את הגוי ונאה היה\u0006 בעיניו\u0005],\u0006 \u0003איתלי ליה נורא בדיקניה\u0004 \u0005[הדלק לו אש בזקנו]\u0006 \u0003ולא שבעת חוכא מיניה\u0004 \u0005[תשבע צחוק ממנו],\u0006 ופתגם זה בא לומר שאם אדם אינו מוחה כשמזלזלים בו, ממשיכים לעשות זאת, אבל הדימוי נלקח ממעשה סנחריב.","\u0003אזל אשכח דפא מתיבותא\u0004 \u0005[הלך\u0006 סנחריב \u0005מצא קרש מתיבתו]\u0006 של \u0003נח, אמר: היינו אלהא רבא דשיזביה\u0004 \u0005[זהו האל הגדול שהצילו]\u0006 את \u0003נח מטופנא\u0004 \u0005[מהמבול],\u0006 \u0003אמר: אי אזיל ההוא גברא ומצלח, מקרב להו לתרין בנוהי קמך\u0004 \u0005[אם ילך אותו איש,\u0006 כלומר, אני, \u0005ויצליח, יקריב את שני בניו לפניך].\u0006 \u0003שמעו בנוהי וקטלוהו\u0004 \u0005[בניו והרגוהו],\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ויהי הוא משתחוה בית נסרך אלהיו ואדרמלך ושראצר בניו הכהו בחרב\u0004 והמה נמלטו ארץ אררט\u0003\"\u0004 (מלכים ב' יט, לז) ומפרש \"נסרוך\" לשון נסר, שהשתחווה לנסר ועשו אלוה.","כיון שהוזכרו קודם מלכים שבאו למלחמה על אברהם (רמ\"ה), מבארים: נאמר באברהם \u0003\"ויחלק עליהם לילה הוא ועבדיו ויכם\"\u0004 (בראשית יד, טו), והמלה \"לילה\" לכאורה אינה במקומה הראוי במשפט, ועל כך \u0003אמר\u0004 \u0003ר' יוחנן: אותו מלאך שנזדמן לו לאברהם\u0004 לעוזרו \u0003\"לילה\" שמו, שנאמר: \"והלילה אמר הרה גבר\"\u0004 (איוב ג, ג), משמע ששם מלאך הוא. \u0003ור' יצחק נפחא אמר: שעשה עמו מעשה לילה,\u0004 שכוכבי השמים נלחמו עבורו, \u0003שנאמר: \"מן שמים נלחמו הכוכבים ממסלותם נלחמו עם סיסרא\"\u0004 (שופטים ה, כ). \u0003אמר ריש לקיש: טבא דנפחא מדבר נפחא\u0004 \u0005[טוב\u0006 דברו \u0005של הנפח,\u0006 ר' יצחק נפחא, \u0005משל בן הנפח,\u0006 הוא הכנוי לר' יוחנן\u0005].\u0006","ועל מה שנאמר באברהם: \u0003\"וירדף עד דן\"\u0004 (בראשית יד, יד), \u0003אמר ר' יוחנן: כיון שבא אותו צדיק\u0004 (אברהם) \u0003עד דן\u0004 — \u0003תשש כחו,\u0004 כי \u0003ראה\u0004 ברוח הקודש את \u0003בני בניו ש\u0004הם \u0003עתידין לעבוד עבודה זרה בדן, שנאמר: \"\u0004ויעש שני עגלי זהב... \u0003וישם את האחד בבית אל ואת האחד נתן בדן\"\u0004 (מלכים א' יב, כח-כט). \u0003ואף אותו רשע\u0004 נבוכדנצר \u0003לא נתגבר עד שהגיע לדן, שנאמר: \"מדן נשמע נחרת סוסיו\"\u0004 (ירמיה ח, טז).","\u0003אמר ר' זירא: אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003שלח ר' יהודה בן בתירא מנציבין: הזהרו\u0004 בכבודו של \u0003זקן ששכח תלמודו מחמת אונסו, והזהרו ב\u0004זמן שחיטה שתחתכו גם את ה\u0003וורידין כ\u0004דעת \u0003ר' יהודה, והזהרו ב\u0004כבוד \u0003בני עמי הארץ\u0004 לפי שיש \u0003שמהן תצא תורה.\u0004 מכל מקום \u0003כי הא מילתא מודעינן להו\u0004 \u0005[כמו דבר זה מודיעים אנו להם]\u0006 נאמר","\u0003\"צדיק אתה ה' כי אריב אליך אך משפטים אדבר אותך\u0004 \u0003מדוע דרך רשעים צלחה שלו כל בגדי בגד. נטעתם גם שרשו ילכו גם עשו פרי\"\u0004 (שם יב, א-ב) \u0003מאי אהדרו ליה\u0004 \u0005[מה השיבו לו]\u0006 לירמיהו על טענה זו — \u0003\"כי את רגלים רצתה וילאוך ואיך תתחרה את הסוסים ובארץ שלום אתה בוטח ואיך תעשה בגאון הירדן\"\u0004 (שם ה), ומתחילה מבארים את הכתוב כפשוטו.","\u0003משל לאדם אחד שאמר: יכול אני לרוץ שלש פרסאות לפני הסוסים בין בצעי המים\u0004 (ביצות, מקום טובעני). \u0003נזדמן לו רגלי אחד, רץ לפניו שלשה מילין ביבשה ונלאה. אמרו לו: ומה לפני רגלי כך\u0004 התעייפת, \u0003לפני הסוסים\u0004 — \u0003על אחת כמה וכמה. ומה שלשת מילין כך\u0004 עייפת, \u0003שלש פרסאות\u0004 שהן פי ארבע — \u0003על אחת כמה וכמה. ומה ביבשה כך, בין בצעי המים\u0004 — \u0003על אחת כמה וכמה.\u0004","וביאורו של הענין: \u0003אף אתה,\u0004 ירמיהו, חשוב: \u0003ומה בשכר ארבע פסיעות ששלמתי לאותו רשע\u0004 נבוכדנצר מפני \u0003שרץ אחר כבודי\u0004 — \u0003אתה תמיה\u0004 כמה גדול תוקפו, \u0003כשאני משלם שכר לאברהם יצחק ויעקב שרצו לפני כסוסים\u0004 כל ימיהם — \u0003על אחת כמה וכמה.\u0004 ללמדנו כמה גדול כוחה של מצוה, אפילו מצוה קלה. \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"לנבאים נשבר לבי בקרבי רחפו כל עצמתי הייתי כאיש שכור וכגבר עברו יין מפני ה' ומפני דברי קדשו\"\u0004 (שם כג, ט).","ושואלים: \u0003הני\u0004 \u0005[אותן]\u0006 \u0003ארבע פסיעות\u0004 של נבוכדנצר \u0003מאי היא\u0004 \u0005[מה הן]?\u0006 ומסבירים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בעת ההיא שלח מראדך בלאדן בן בלאדן מלך בבל ספרים\u0004 ומנחה אל חזקיהו וישמע כי חלה ויחזק\u0003\"\u0004 (ישעיה לט, א). ושואלים: וכי \u0003משום \"כי חלה חזקיהו ויחזק\" שדר ליה\u0004 \u0005[שלח לו]\u0006 \u0003ספרים ומנחה?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 וטעמו — \u0003\"לדרש המופת אשר היה בארץ\"\u0004 (דברי הימים ב' לב, לא). וכך היה הדבר, ש\u0003אמר ר' יוחנן: אותו היום שמת בו אחז שתי שעות היה,\u0004 שנתקצר אותו יום בעשר שעות כדי שימהרו לקבור את אחז ולא יחלקו לו כבוד מלכים.","\u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003חלה חזקיהו ואיתפח\u0004 \u0005[והבריא],\u0006 \u0003אהדרינהו קודשא בריך הוא להנך\u0004 \u0005[החזיר הקדוש ברוך הוא לאותן]\u0006 \u0003עשר שעי ניהליה\u0004 \u0005[שעות לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנני משיב את צל המעלות אשר ירדה במעלות אחז בשמש אחרנית עשר מעלות ותשב השמש עשר מעלות במעלות אשר ירדה\"\u0004 (ישעיה לח, ח), שהשמש שירדה בשל אחז — חזרה ושבה בשל בנו. \u0003אמר להו\u0004 \u0005[להם]\u0006 מרודך לשריו: \u0003מאי האי\u0004 \u0005[מה\u0006 הוא \u0005זה]\u0006 שהיום מתארך? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003חזקיהו חלש ואיתפח\u0004 \u0005[חלה והבריא],\u0006 ובשבילו זרחה השמש. \u0003אמר\u0004 מרודך: \u0003איכא גברא כי האי ולא בעינא לשדורי ליה שלמא\u0004 \u0005[יש אדם כזה ואין אני צריך לשלוח לו שלום]?\u0006 ודאי צריך לכבדו ביותר. \u0003כתבו ליה\u0004 \u0005[לו]\u0006 שרי מרודך לחזקיהו: \"\u0003שלמא למלכא\u0004 \u0005[שלום למלך]\u0006 \u0003חזקיה, שלם לקרתא ירושלם\u0004 \u0005[שלום לעיר ירושלים],\u0006 \u0003שלם לאלהא רבא\u0004 \u0005[שלום לאל הגדול]\u0006 \u0003\".\u0004","\u0003נבוכד נאצר ספריה\u0004 \u0005[סופרו]\u0006 של \u0003בלאדן הוה\u0004 \u0005[היה],\u0006 \u0003ההיא שעתא\u0004 \u0005[\u0006ו\u0005אותה שעה]\u0006 \u0003לא הוה התם\u0004 \u0005[היה שם].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 לסופרים: \u0003היכי כתביתו\u0004 \u0005[כיצד כתבתם]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הכי כתבינן\u0004 \u0005[כך כתבנו],\u0006 כאמור. \u0003אמר להו\u0004 \u0005[להם]\u0006 נבוכדנאצר לסופרים: \u0003קריתו ליה \"אלהא רבא\" וכתביתו ליה\u0004 \u0005[קוראים אתם לו \"האל הגדול\" וכותבים אתם אותו]\u0006 \u0003לבסוף, אלא הכי כתובו\u0004 \u0005[כך כתבו]\u0006 \u0003\"שלם לאלהא רבא\u0004 \u0005[שלום לאל הגדול],\u0006 \u0003שלם לקרתא דירושלם\u0004 \u0005[שלום לעיר ירושלים],\u0006 \u0003שלם למלכא\u0004 \u0005[שלום למלך]\u0006 \u0003חזקיה\".\u0004 \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 הסופרים לנבוכדנאצר: \u0003קריינא דאיגרתא איהו ליהוי פרוונקא\u0004 \u0005[קורא האגרת הוא שיהיה השליח\u0006 לבשר את הכתוב בה\u0005],\u0006 כלומר, דאג אתה לתקן את הדברים.","\u0003רהט בתריה\u0004 \u0005[רץ אחריו]\u0006 אחרי השליח להשיבו, ולכתוב בנוסח אחר. \u0003כדרהיט\u0004 \u0005[כאשר רץ]\u0006 \u0003ארבע פסיעות אתא\u0004 \u0005[בא]\u0006 \u0003גבריאל ואוקמיה\u0004 \u0005[והעמידו]\u0006 שלא ירוץ יותר. \u0003אמר ר' יוחנן: אילמלא לא בא גבריאל והעמידו לא היה תקנה לשונאיהם של ישראל\u0004 (כלומר, לישראל) שהיה זוכה למלוכה במשך דורות רבים כל כך, ולא היתה תקומה למפלת ישראל.","אגב שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"\u0004מרודך \u0003בלאדן בן בלאדן\",\u0004 שאם היה שמו \"מרודך\", לא היה שמו \"בלאדן\"! \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003בלאדן מלכא הוה, ואישתני אפיה והוה כי דכלבא\u0004 \u0005[מלך היה, והשתנו פניו והיו כפני כלב]\u0006. \u0003הוה יתיב דבריה על מלכותא\u0004 \u0005[היה יושב בנו על\u0006 כסא \u0005מלכותו].\u0006 \u0003כי הוה כתיב, הוה כתיב שמיה ושמיה דאבוה\u0004 \u0005[כאשר היה כותב, היה כותב\u0006 את \u0005שמו ושם אביו]\u0006 \u0003בלאדן מלכא\u0004 \u0005[המלך].\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"בן יכבד אב ועבד אדניו\"\u0004 (מלאכי א, ו), כלומר, זה נקרא כיבוד אב שיש באומות.","ומסבירים: \u0003\"בן יכבד אב\"\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 בבלאדן, \u0003ועבד אדניו\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובחדש החמישי בעשור לחדש היא שנת תשע עשרה שנה למלך נבוכדנאצר מלך בבל בא נבוזראדן רב טבחים עמד לפני מלך בבל בירושל ם. וישרף את בית ה' ואת בית המלך\"\u0004 (ירמיה נב, יב-יג)"],["ויש לברר: \u0003ומי סליק\u0004 \u0005[והאם עלה]\u0006 \u0003נבוכד נצר לירושלים? והכתיב\u0004 \u0005[והרי נאמר]\u0006 בצדקיהו: \u0003\"\u0004ויתפשו את המלך \u0003ויעלו אתו אל מלך בבל רבלתה\"\u0004 (מלכים ב' כה, ו), \u0003ואמר ר' אבהו:\u0004 \"רבלתה\" \u0003זו אנטוכיא,\u0004 משמע שלא היה נבוכדנצר כלל בירושלים. \u0003רב חסדא ורב יצחק בר אבודימי\u0004 נתנו הסבר לדבר, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003דמות דיוקנו\u0004 של נבוכדנצר \u0003היתה חקוקה לו על מרכבתו\u0004 של נבוזואדן ונהג בו כאילו הוא עצמו שם, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003אימה יתירה היתה לו\u0004 לנבוזראדן \u0003ממנו ודומה\u0004 היה תמיד \u0003כמי שעומד לפניו.\u0004 והוא דוגמה לעבד המכבד את אדוניו.","כיון שדובר בנבוזראדן, מביאים גם מעשהו בחורבן הבית. \u0003אמר רבא: טעין תלת מאה כודנייתא נרגא דפרזלא דשליט בפרזלא שדר ליה\u0004 \u0005[מטען שלש מאות פרדות גרזיני ברזל החותך ברזל שלח לו]\u0006 \u0003נבוכדנצר לנבוזראדן,\u0004 \u0003כולהו בלעתינהו חד דשא דירושלם\u0004 \u0005[את כולם בלע,\u0006 שיבר \u0005שער אחד שבירושלים],\u0006 שכל הגרזינים נשברו בו, \u0003שנאמר: \"פתוחיה יחד בכשיל וכילפות יהלמון\"\u0004 (תהלים עד, ו), כלומר, שפתחי ירושלים עמדו בפני כשיל וכילפות של ברזל. \u0003בעי למיהדר\u0004 \u0005[רצה לחזור]\u0006 \u0003אמר: מסתפינא\u0004 \u0005[מתיירא אני]\u0006 ש\u0003לא ליעבדו\u0004 \u0005[יעשו]\u0006 \u0003בי כי היכי דעבדו\u0004 \u0005[כפי שעשו]\u0006 \u0003בסנחריב,\u0004 שמפלתו הגדולה היתה בירושלים.","\u0003נפקא קלא ואמר\u0004 \u0005[יצאה\u0006 בת \u0005קול ואמרה]:\u0006 \u0003שוור בר שוור\u0004 \u0005[קופץ בן קופץ],\u0006 \u0003נבוזראדן שוור, דמטא זימנא דמקדשא חריב והיכלא מיקלי\u0004 \u0005[קפוץ, שהגיע זמן המקדש להחרב וההיכל להשרף].\u0006 \u0003פש ליה חד נרגא, אתא מחייה בקופא, ואיפתח\u0004 \u0005[נשאר לו גרזן אחד, בא והכה\u0006 את השער \u0005בקצה הרחב\u0006 של הגרזן \u0005ונפתח],\u0006 \u0003שנאמר: \"יודע כמביא למעלה בסבך עץ קרדמות\"\u0004 (שם ה), שבזמן הראוי נפתח לו כאילו היה זה בתוך עצים ולא בחומה.","\u0003הוה קטיל ואזל\u0004 \u0005[היה הורג והולך]\u0006 בתוך כניסתו לעיר \u0003עד דמטא להיכלא\u0004 \u0005[שהגיע להיכל].\u0006 ומשבא להיכל \u0003אדליק ביה נורא\u0004 \u0005[הדליק בו אש].\u0006 \u0003גבה היכלא\u0004 \u0005[התרומם ההיכל]\u0006 שלא תשלוט בו האש. \u0003דרכו ביה\u0004 \u0005[בו,\u0006 אותו\u0005]\u0006 \u0003מן שמיא\u0004 \u0005[השמים]\u0006 שירד למקומו, \u0003שנאמר: \"גת דרך ה' לבתולת בת יהודה\"\u0004 (איכה א, טו). \u0003קא זיחא דעתיה\u0004 \u0005[זחה דעתו],\u0006 נתגאה נבוזראדן בנצחונו, \u0003נפקא בת קלא\u0004 \u0005[יצאה בת קול]\u0006 \u0003ואמרה ליה\u0004 \u0005[לו]:\u0006 \u0003עמא קטילא קטלת, היכלא קליא קלית, קימחא טחינא טחינת\u0004 \u0005[עם הרוג הרגת, היכל שרוף שרפת, קמח טחון טחנת],\u0006 \u0003שנאמר\u0004 על בבל: \u0003\"קחי רחים וטחני קמח גלי צמתך חשפי שבל גלי שוק עברי נהרות\"\u0004 (ישעיה מז, ב) — \u0003\"\u0004טחני \u0003חטים\" לא נאמר אלא \"\u0004טחני \u0003קמח\",\u0004 לומר, כבר נעשה הדבר בידי שמים, ומכוח ה' ולא בגבורתו של הכובש.","כשהגיע להיכל \u0003חזא דמיה\u0004 \u0005[ראה את דמו]\u0006 של \u0003זכריה\u0004 הנביא \u0003דהוה קא רתח\u0004 \u0005[שהיה רותח],\u0006 ולא שקט, מפני שנהרג בתוך המקדש. \u0003אמר להו\u0004 \u0005[להם]\u0006 נבוזראדן לכהנים שהיו שם: \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דם זבחים הוא דאישתפיך\u0004 \u0005[שנשפך]\u0006 כאן. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אייתי ואנסי אי מדמו\u0004 \u0005[הביאו ואנסה אם דומים\u0006 הם\u0005].\u0006 \u0003כסי\u0004 \u0005[שחט]\u0006 \u0003ולא אידמו\u0004 \u0005[נדמה\u0006 הדם\u0005].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003גלו לי\u0004 את האמת, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, סריקנא לכו לבשרייכו במסריקא דפרזלא\u0004 \u0005[אסרוק את בשרכם במסרקות של ברזל].\u0006","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 דם \u0003כהן ונביא הוא דאינבי להו\u0004 \u0005[שהתנבא להם]\u0006 \u0003לישראל בחורבנא דירושלם, וקטלוהו\u0004 \u0005[לחורבן ירושלים, והרגוהו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא מפייסנא ליה\u0004 \u0005[אני אפייס אותו]\u0006 שיפסיק לרתוח. \u0003אייתי רבנן, קטיל עילויה\u0004 \u0005[הביא חכמים, הרגם עליו],\u0006 ליד דם זה \u0003ולא נח.\u0004 \u0003אייתי דרדקי דבי רב קטיל עילויה\u0004 \u0005[הביא תינוקות של בית רבן הרג עליו]\u0006 \u0003ולא נח. אייתי\u0004 \u0005[הביא]\u0006 \u0003פרחי\u0004 (צעירי) \u0003כהונה קטיל עילויה\u0004 \u0005[הרג עליו]\u0006 \u0003ולא נח,\u0004 \u0003עד די קטל עילויה תשעין\u0004 \u0005[שהרג עליו תשעים]\u0006 \u0003וארבעה ריבוא\u0004 אנשים, \u0003ו\u0004עדיין \u0003לא נח.\u0004","\u0003קרב לגביה\u0004 \u0005[התקרב\u0006 נבוזראדן \u0005אליו,\u0006 אל הדם\u0005]\u0006 ו\u0003אמר: זכריה זכריה, טובים שבהן איבדתים\u0004 בגללך, האם \u0003ניחא\u0004 \u0005[נוח]\u0006 \u0003לך\u0004 (רצונך) \u0003דאיקטלינהו לכולהו\u0004 \u0005[שאהרוג את כולם]?!\u0006 \u0003מיד נח\u0004 הדם. \u0003הרהר\u0004 נבוזראדרן \u0003תשובה בדעתיה\u0004 \u0005[בדעתו],\u0006 \u0003אמר: מה הם שלא איבדו אלא נפש אחת, כך\u0004 לא היתה להם כפרה אלא במותם של אלפים רבים כל כך, \u0003ההוא גברא מה תיהוי עליה\u0004 \u0005[אותו אדם,\u0006 הוא עצמו, \u0005מה תהיה עליו],\u0006 ומה יהיה עונשו שיצטרך להיענש על כל חטאיו? \u0003ערק, שדר פורטיתא לביתיה, ואיתגייר\u0004 \u0005[ברח, שלח צוואה לביתו, והתגייר].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נעמן\u0004 הארמי \u0003גר תושב היה,\u0004 שלא קיבל על עצמו את היהדות בשלימות, אלא נמנע מעבודה זרה בלבד. \u0003נבוזראדן גר צדק\u0004 גמור \u0003היה.\u0004 ועוד כיוצא בזה: \u0003מבני בניו של סיסרא למדו תורה בירושלים.\u0004 \u0003מבני\u0004 \u0003בניו של סנחריב לימדו תורה ברבים.\u0004 ושואלים: \u0003ומאן נינהו\u0004 \u0005[ומי הם]\u0006 אלה? ומשיבים: \u0003שמעיה ואבטליון\u0004 שהיו מבני גרים ממשפחה זו.","\u0003מבני בניו של המן למדו תורה בבני ברק. ואף מבני בניו של אותו רשע,\u0004 נבוכדנצר, \u0003ביקש הקדוש ברוך הוא להכניסן תחת כנפי השכינה\u0004 שיתגיירו. \u0003אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם: מי שהחריב את ביתך ושרף את היכלך תכניס תחת כנפי השכינה? היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"רפינו את בבל ולא נרפתה\"\u0004 (ירמיה נא, ט). \u0003עולא אמר: זה נבוכדנצר\u0004 שלא נתגייר איש מבני בניו. \u0003ר' שמואל בר נחמני אמר:\u0004 אין הכוונה לאדם מסויים, אלא \u0003אלו נהרות בבל, ותרגמה\u0004 \u0005[והסברה]\u0006 שמדובר \u0003דצינייתא צרידתא דבבלאי\u0004 \u0005[נהרות המרים המלוחים של בבל]\u0006 (גאונים).","אגב סיפור זה העוסק בחורבן הבית, מספרים את השתלשלות הדברים. \u0003אמר עולא: עמון ומואב שיבבי בישי דירושלם הוו\u0004 \u0005[שכנים רעים של ירושלים היו].\u0006 \u0003כיון דשמעינהו לנביאי דקא מיתנבאי לחורבנא דירושלם\u0004 \u0005[ששמעו אותם, את הנביאים שמתנבאים על חורבן ירושלים]\u0006 \u0003שלחו לנבוכדנצר: פוק ותא\u0004 \u0005[צא\u0006 ממקום מושבך \u0005ובוא\u0006 עליהם\u0005]\u0006 ותכבשם. \u0003אמר\u0004 להם בתשובה: \u0003מסתפינא\u0004 \u0005[מתיירא אני]\u0006 ש\u0003לא ליעבדו\u0004 \u0005[יעשו]\u0006 \u0003לי כדעבדו בקמאי\u0004 \u0005[כפי שעשו בראשונים].\u0006","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 עמון ומואב: \u0003\"כי אין האיש בביתו הלך בדרך מרחוק\"\u0004 \u0005(משלי ז, יט)\u0006, \u0003ואין\u0004 משמעות \u0003\"איש\" אלא\u0004 רמז ל\u0003הקדוש ברוך הוא, שנאמר: \"ה' איש מלחמה\"\u0004 (שמות טו, ג). \u0003שלח להו\u0004 \u0005[להם]\u0006 בתשובה: \u0003בקריבא\u0004 \u0005[ב\u0006מקום \u0005קרוב]\u0006 \u0003הוא, ואתי\u0004 \u0005[ויבוא].\u0006 הוסיפו ו\u0003שלחו ליה\u0004 \u0005[לו]:\u0006 \u0003\"הלך בדרך מרחוק\"\u0004 (משלי ז, יט). \u0003שלח להו\u0004 \u0005[להם]:\u0006 \u0003אית להו צדיקי דבעו רחמי, ומייתו ליה\u0004 \u0005[יש בהם צדיקים שיבקשו רחמים, ויביאו אותו].\u0006","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 עוד עמון ומואב: \u0003\"צרור הכסף לקח בידו\"\u0004 (שם ז, כ), \u0003ואין\u0004 משמעות \u0003\"כסף\" אלא צדיקים, שנאמר: \"ואכרה לי בחמשה עשר כסף וחמר שערים ולתך שערים\"\u0004 (הושע ג, ב), שנתפרש שקנה ה' את כנסת ישראל בשל הצדיקים שבהם, ושלחו לו שאבדו הצדיקים מישראל.","\u0003שלח להו\u0004 \u0005[להם]:\u0006 שמא \u0003הדרי רשיעי\u0004 \u0005[יחזרו הרשעים]\u0006 שבהם \u0003בתשובה\u0004 וייעשו כצדיקים, \u0003ובעו רחמי ומייתו ליה\u0004 \u0005[\u0006\u0005ויבקשו רחמים ויביאו אותו].\u0006 \u0003שלחו ליה\u0004 \u0005[לו]:\u0006 \u0003כבר קבע להן זמן\u0004 מתי תבוא הגאולה, ועד אז יכול אתה לעשות כרצונך, \u0003שנאמר: \"ליום הכסא יבא לביתו\"\u0004 (משלי ז, כ), ו\u0003אין\u0004 משמעות \u0003\"כסא\" אלא זמן\u0004 מסויים וקצוב, \u0003שנאמר: \"\u0004תקעו בחודש שופר \u0003בכסה ליום חגנו\"\u0004 (תהלים פא, ד). \u0003שלח להו\u0004 \u0005[להם]:\u0006 זמן \u0003סיתווא\u0004 \u0005[חורף]\u0006 \u0003הוא, ולא מצינא דאתי מתלגא וממיטרא\u0004 \u0005[ואין אני יכול לבוא\u0006 משום \u0005השלג והמטר].\u0006","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 עמון ומואב: \u0003תא אשינא דטורא\u0004 \u0005[בוא על שיני ההרים]\u0006 מלמעלה, ששם אין המטר יוצר שלוליות, \u0003שנאמר: \"שלחו כר מושל ארץ מסלע מדברה אל הר בת ציון\"\u0004 (ישעיה טז, א). \u0003שלח להו\u0004 \u0005[להם]:\u0006 \u0003אי אתינא, לית\u0004 \u0005[אם אבוא אין]\u0006 \u0003לי דוכתא דיתיבנא ביה\u0004 \u0005[מקום שאשב בו]\u0006 בשעת המצור על העיר. \u0003שלחו ליה\u0004 \u0005[לו]:\u0006 \u0003קברות\u0004 (מערות הקבורה) \u0003שלהם מעולין מפלטירין\u0004 (ארמונות) \u0003שלך\u0004 ויכול אתה לפנות את מערות הקבורה שלהם ולדור שם, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בעת ההיא נאם ה' יוציאו את עצמות מלכי יהודה ואת עצמות שריו ואת עצמות הכהנים ואת עצמות הנביאים ואת עצמות יושבי ירושל ם מקבריהם. ושטחום לשמש ולירח ולכל צבא השמים אשר אהבום ואשר עבדום ואשר הלכו אחריהם\"\u0004 (ירמיה ח, א-ב), והוציאום משום שהיו צריכים לפנות מקום לצבא נבוכדנצר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לר' יצחק: מי שמיע לך אימת אתי בר נפלי\u0004 \u0005[\u0006האם יודע אתה, \u0005האם שמעת מתי יבוא בן הנפילים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאן בר נפלי\u0004 \u0005[מיהו בן הנפילים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משיח.\u0004 שאל אותו בתמיה: את ה\u0003משיח \"בר נפלי\" קרית ליה\u0004 \u0005[\"בן נפילים\" קורא אתה]?\u0006 \u0003אמר\u0004 \u0003ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ביום ההוא אקים\u0004"],["\u0003את סכת דויד הנפלת\"\u0004 (עמוס ט, יא), ולכן נקרא המשיח \"בר (בן) ניפלי\". \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: דור שבן דוד\u0004 (המשיח) \u0003בא בו, תלמידי חכמים מתמעטים, והשאר עיניהם כלות ביגון ואנחה, וצרות רבות\u0004 (מתרבות), \u0003וגזרות קשות מתחדשות, עד שהראשונה פקודה\u0004 (עוברת), \u0003שניה ממהרת לבא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו\u0006 חכמים] בברייתא: \u0003שבוע\u0004 (שמיטה, שבע שנים) \u0003שבן דוד בא בו, שנה ראשונה מתקיים מקרא זה: \"והמטרתי על עיר אחת ועל עיר אחת לא אמטיר\"\u0004 (שם ד, ז). בשנה ה\u0003שניה\u0004 מאותה שמיטה — \u0003חיצי רעב משתלחים,\u0004 שמקומות מסויימים יסבלו מן הרעב. בשנה ה\u0003שלישית\u0004 של שמיטה זו — \u0003רעב גדול, ומתים אנשים ונשים וטף חסידים ואנשי מעשה, ותורה משתכחת מלומדיה. ב\u0004שנה ה\u0003רביעית\u0004 — \u0003שובע ואינו שובע. בחמישית\u0004 — \u0003שובע גדול, ואוכלין ושותין ושמחין, ותורה חוזרת ללומדיה. בששית\u0004 — \u0003קולות\u0004 נשמעים משמים, \u0003בשביעית\u0004 — \u0003מלחמות\u0004 כגון מלחמת גוג ומגוג, הבאות על ישראל. \u0003במוצאי שביעית\u0004 — \u0003בן דוד בא.\u0004","\u0003אמר רב יוסף: הא\u0004 \u0005[הרי]\u0006 \u0003כמה\u0004 שנות \u0003שביעית דהוה כן\u0004 \u0005[שהיה כך]\u0006 כעין מאורעות אלה \u0003ולא אתא\u0004 \u0005[בא]\u0006 משיח! \u0003אמר אביי:\u0004 מה שאמרו שיהיו \u0003בששית קולות,\u0004 ו\u0003בשביעית מלחמות, מי הוה\u0004 \u0005[האם היה]?\u0006 שחלק זה עדיין לא נתקיים. \u0003ועוד, כסדרן מי הוה\u0004 \u0005[האם היה],\u0006 שאף אם היו שנות רעב ושובע ומלחמה, אבל לא ארעו הדברים לפי הסדר שבאותה ברייתא.","נאמר \u0003\"אשר חרפו אויביך ה' אשר חרפו עקבות משיחך\"\u0004 (תהלים פט, נב). \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: דור שבן דוד בא בו, בית הוועד\u0004 שהוא מושב החכמים \u0003יהיה לזנות, והגליל יחרב, והגבלן\u0004 (הבשן) \u0003יאשם\u0004 (יהא שומם), \u0003ואנשי גבול\u0004 שימלטו מפני הגויים \u0003יסובבו מעיר לעיר ולא יחוננו\u0004 (ירוחמו), \u0003וחכמת הסופרים תסרח\u0004 (תתמעט), \u0003ויראי חטא ימאסו, ופני הדור כפני כלב\u0004 בחוצפה וחוסר בושה,","\u0003והאמת\u0004 תהא \u0003נעדרת, שנאמר: \"ותהי האמת נעדרת וסר מרע משתולל\"\u0004 (ישעיה נט, טו). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ותהי האמת נעדרת\"? אמרי דבי\u0004 \u0005[אמרו\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: מלמד שנעשית\u0004 האמת \u0003עדרים עדרים, והולכת לה. מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וסר מרע משתולל\"?\u0004 \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא: כל מי שסר מרע\u0004 — \u0003משתולל,\u0004 נחשב כמשוגע \u0003על הבריות.\u0004","כיון שדובר בהעדר האמת, מביאים דברים ש\u0003אמר רבא: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 כי \u0003ליכא קושטא בעלמא\u0004 \u0005[אין אמת בעולם],\u0006 שאין מקום שידברו בו תמיד אמת. \u0003אמר לי ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003ורב טבות שמיה\u0004 \u0005[שמו],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב טביומי שמיה\u0004 \u0005[שמו]\u0006, והוא היה אדם ישר כל כך, \u0003דאי הוו יהבי ליה\u0004 \u0005[שאם היו נותנים לו]\u0006 את \u0003כל חללי דעלמא\u0004 \u0005[חלל העולם]\u0006 \u0003לא הוה משני בדיבוריה\u0004 \u0005[היה משנה בדיבורו],\u0006 וסיפר לי: \u0003זימנא חדא איקלעי לההוא אתרא ו\"קושטא\" שמיה\u0004 \u0005[פעם אחת הזדמנתי למקום אחד ו\"אמת\" שמו],\u0006 \u0003ולא הוו משני בדיבורייהו\u0004 \u0005[היו משנים בדבריהם],\u0006 שהיו מקפידים לומר רק אמת, \u0003ולא הוה מיית איניש מהתם\u0004 \u0005[היה מת אדם משם]\u0006 \u0003בלא זימניה\u0004 \u0005[זמנו].\u0006 \u0003נסיבי איתתא מינהון, והוו\u0004 \u0005[נשאתי אשה מביניהם, והיו]\u0006 \u0003לי תרתין בנין מינה\u0004 \u0005[שני בנים ממנה].\u0006","\u0003יומא חד הוה יתבא דביתהו וקא חייפא רישא\u0004 \u0005[יום אחד ישבה אשתו וחפפה\u0006 את \u0005ראשה],\u0006 \u0003אתאי שיבבתה טרפא אדשא\u0004 \u0005[באה שכנתה\u0006 ו\u0005דפקה בדלת]\u0006 להכנס, \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003לאו אורח ארעא\u0004 \u0005[לא דרך ארץ]\u0006 זה לספר לה שאשתו רוחצת עצמה, \u0003אמר לה: ליתא הכא\u0004 \u0005[איננה כאן],\u0006 וכיון ששינה בדיבורו \u0003שכיבו ליה תרתין בנין\u0004 \u0005[מתו לו שני בנים].\u0006 \u0003אתו אינשי דאתרא לקמיה\u0004 \u0005[באו אנשי המקום אליו]\u0006 ו\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי הוה\u0004 \u0005[כך היה]\u0006 \u0003מעשה\u0004 ששיניתי בדיבורי מפני הנימוס. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003במטותא מינך, פוק מאתרין ולא תגרי בהו מותנא בהנך אינשי\u0004 \u0005[בבקשה ממך צא ממקומנו ואל תגרה את המות באותם אנשים],\u0006 כלומר, אל תביא עלינו מיתה שלא בזמנה.","ושוב לענין ראשון: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נהוראי אומר: דור שבן דוד בא בו, נערים ילבינו פני זקנים, וזקנים יעמדו לפני נערים\u0004 לכבדם, \u0003ובת קמה\u0004 (מורדת) \u0003באמה, וכלה בחמותה, ופני הדור כפני כלב, ואין הבן מתבייש מאביו.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נחמיה אומר: דור שבן דוד בא בו, העזות\u0004 (חוצפה) \u0003תרבה, והיוקר יעות\u0004 את האנשים, שיהיו רמאים, \u0003והגפן יתן\u0004 אמנם \u0003פריו,\u0004 \u0003ו\u0004אולם \u0003היין\u0004 יהיה \u0003ביוקר, ונהפכה כל המלכות למינות,\u0004 שתתפשט הנצרות בעולם, \u0003ואין תוכחה,\u0004 שלא יקבלו הבריות תוכחה שמוכיחים אותם. ומעירים, \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003ל\u0004שיטת \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: אין בן דוד בא עד שתתהפך כל המלכות למינות. אמר רבא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 הרומז על כך — שנאמר בדיני צרעת: \u0003\"כלו הפך לבן טהור הוא\"\u0004 (ויקרא יג, יג), שאף שאם יש מקצת לובן של נגע חולני בעור הרי זה סימן לנגע צרעת, אולם אם כל העור הופך לבן הרי זה סימן טהרה. ואף תיקון העולם יהיה כשיגיע לתחתית הירידה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \u0003\"כי ידין ה' עמו\u0004 ועל עבדיו יתנחם \u0003כי יראה כי אזלת יד ואפס עצור ועזוב\"\u0004 (דברים לב, לו), \"אזלת יד\" זו כוונתה: \u0003אין בן דוד בא עד שירבו המסורות\u0004 (המלשינים). \u0003דבר אחר: עד שיתמעטו התלמידים. דבר אחר:\u0004 אינו בא \u0003עד שתכלה פרוטה מן הכיס. דבר אחר: עד שיתייאשו מן הגאולה, שנאמר: \"ואפס עצור ועזוב\" כביכול אין סומך ועוזר לישראל,\u0004","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 של \u0003ר' זירא כי הוה משכח רבנן דמעסקי ביה\u0004 \u0005[כאשר היה מוצא חכמים שעוסקים בו,\u0006 בענין קץ המשיח\u0005]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003במטותא, בעינא מנייכו לא תרחקוה\u0004 \u0005[בבקשה מבקש אני מכם אל תרחקוהו]\u0006 על ידי עיסוק בחישובי קיצים, \u0003דתנינא\u0004 \u0005[ששנינו]:\u0006 \u0003שלשה\u0004 דברים \u0003באין בהיסח הדעת\u0004 כשאין חושבים עליהם, \u0003אלו הן: משיח, מציאה, ועקרב.\u0004 ולכן מוטב שלא להתעסק בענייני המשיח, ולהסיח את הדעת ממנו.","\u0003אמר רב קטינא: שית אלפי שני הוו עלמא, וחד חרוב\u0004 \u0005[ששת אלפים שנה הוא\u0006 משך ימי \u0005העולם,\u0006 ואלף \u0005אחד יחרב].\u0006 ומנין שאלף אחד ייחרב — \u0003שנאמר: \"ונשגב ה' לבדו ביום ההוא\"\u0004 (ישעיה ב, יא), שיומו של ה' — אלף שנה הוא. \u0003אביי אמר: תרי חרוב\u0004 \u0005[שני\u0006 אלפים \u0005יחרב],\u0006 \u0003שנאמר: \"יחינו מימים ביום השלישי יקמנו ונחיה לפניו\"\u0004 (הושע ו, ב).","\u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב קטינא:\u0004 \u0003כשם שהשביעית משמטת שנה אחת לשבע שנים, כך העולם משמט\u0004 ומבטל קיומו את הרגיל \u0003אלף שנים לשבעת אלפים שנה, שנאמר: \"ונשגב ה' לבדו ביום ההוא\", ואומר: \"מזמור שיר ליום השבת\"\u0004 (תהלים צב, א), כלומר, \u0003יום\u0004 (אלף שנה) \u0003שכולו שבת. ואומר:\u0004 כדי שנבין את שיעור הגודל \u0003\"כי אלף שנים בעיניך כיום אתמול כי יעבר\u0004 ואשמורה בלילה\" \u0005(תהלים צ, ד)\u0006.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003אליהו\u0004 \u0003ששת אלפים שנה הוי עלמא\u0004 \u0005[הוא העולם],\u0006 \u0003שני אלפים\u0004 מהם \u0003תוהו,\u0004 שאין העולם מסודר ומאורגן, \u0003שני אלפים תורה\u0004 מימות האבות עד סוף ימי תקופת המשנה בערך, \u0003שני אלפים ימות המשיח.\u0004 זה צריך היה להיות סדר מהלך ההיסטוריה."],["\u0003ובעונותינו שרבו יצאו מהם מה שיצאו\u0004 ולא בא המשיח בסוף ארבעת אלפים שנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אליהו לרב יהודה אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב סלא חסידא\u0004 \u0005[החסיד]:\u0006 \u0003אין העולם\u0004 מתקיים \u0003פחות משמונים וחמשה יובלות\u0004 שהם ארבעת אלפים ומאתיים וחמישים שנה. \u0003וביובל האחרון בן דוד בא.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה לאליהו: האם \u0003בתחילתו\u0004 של היובל בא, \u0003או בסופו?\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003איני יודע.\u0004 ועוד שאלו רב יהודה: האם \u0003כלה\u0004 היובל האחרון הזה \u0003או אינו כלה,\u0004 ויבוא משיח לפני שיגמר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003איני יודע. רב אשי אמר:\u0004 לא כך יש להבין, שקבע מועד לביאת הגואל, אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד הכא\u0004 \u0005[כאן]\u0006 \u0003לא תיסתכי ליה\u0004 \u0005[תצפה לו],\u0006 \u0003מכאן ואילך איסתכי ליה\u0004 \u0005[מכאן והלאה תצפה לו].\u0006","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן בר תחליפא לרב יוסף: מצאתי אדם אחד ובידו מגילה אחת כתובה אשורית\u0004 (באותיות מרובעות) \u0003ולשון קדש, אמרתי לו:\u0004 מגילה \u0003זו מניין לך? אמר לי: לחיילות של רומי נשכרתי, ובין גינזי רומי מצאתיה,\u0004 וברור שלא רומאים כתבוה אלא מישראל היא, \u0003וכתוב בה\u0004 במגילה: \u0003לאחר ארבעת אלפים ומאתים ותשעים ואחד שנה לבריאתו של עולם\u0004 — \u0003העולם יתום\u0004 (יכלה), \u0003מהן\u0004 יהיו שנים של \u0003מלחמות תנינים\u0004 בין הלויתן ובהמות \u0003מהן מלחמות גוג ומגוג, ושאר\u0004 הימים \u0003ימות המשיח\u0004 ואחר כך ייהרס העולם. \u0003ואין הקדוש ברוך הוא מחדש\u0004 ובורא \u0003את עולמו אלא לאחר שבעת אלפים שנה. רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא אמר: \"לאחר חמשת אלפים שנה\" איתמר\u0004 \u0005[נאמר].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: מקרא זה נוקב ויורד עד תהום,\u0004 כלומר, כוונת הפסוק עמוקה מני תהום, ואין אדם יכול לדעת מראש את הדבר, ומהו הכתוב — \u0003\"כי עוד חזון למועד ויפח לקץ ולא יכזב אם יתמהמה חכה לו כי בא יבא לא יאחר\"\u0004 (חבקוק ב, ג),","\u0003לא כרבותינו שהיו דורשין \"עד עדן\u0004 ו\u0003עדנין ופלג עדן\"\u0004 (דניאל ז, כה), שסברו שתארך גלות אחרונה פי שלוש וחצי מגלות מצרים (\"עידן\"),","\u0003ולא כ\u0004שיטת \u0003ר' שמלאי שהיה דורש\u0004 את הכתוב \u0003\"האכלתם לחם דמעה ותשקמו בדמעות שליש\"\u0004 (תהלים פ, ו), שתמשך הגלות פי שלוש (\"שליש\") כגלות מצרים,","\u0003ולא כ\u0004שיטת \u0003ר' עקיבא שהיה דורש\u0004 את הכתוב \u0003\"עוד אחת מעט היא ואני מרעיש את השמים ואת הארץ\"\u0004 (חגי ב, ו), שסבר שהגאולה קרובה לבוא אחר החורבן.","\u0003אלא\u0004 הסדר כך היה: \u0003מלכות ראשון\u0004 של החשמונאים בגדולתם — \u0003שבעים שנה, מלכות שניה\u0004 של הורדוס וביתו — \u0003חמשים ושתים\u0004 שנה, \u0003ומלכות בן כוזיבא\u0004 (בר כוכבא) \u0003שתי שנים ומחצה,\u0004 ולאחר מכן אין לדעת עד כמה תארך עוד גלות ישראל.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 דיוק הלשון \u0003\"ויפח לקץ ולא יכזב\"? אמר ר' שמואל בר נחמני אמר ר' יונתן: תיפח עצמן של\u0004 (יקוללו אלו שהם) \u0003מחשבי קיצין, שהיו אומרים כיון שהגיע את הקץ\u0004 שחשבנו \u0003ולא בא\u0004 המשיח \u0003שוב אינו בא\u0004 כלל, \u0003אלא חכה לו\u0004 גם לאחר מכן. \u0003שנאמר: \"אם יתמהמה חכה לו\". שמא תאמר אנו\u0004 \u0003מחכין\u0004 ושואפים שיגיע הקץ \u0003והוא\u0004 הקדוש ברוך הוא \u0003אינו מחכה\u0004 ואינו חפץ בו?! — \u0003תלמוד לומר: \"ולכן יחכה ה' לחננכם ולכן ירום לרחמכם\u0004 כי אלהי משפט ה' אשרי כל חוכי לו","\u0003\"\u0004(ישעיה ל, יח), ולכאורה \u0003וכי מאחר שאנו מחכים\u0004 ורוצים בו \u0003והוא מחכה,\u0004 אם כן \u0003מי מעכב?\u0004 אולם \u0003מדת הדין מעכבת\u0004 (\"כי אלהי משפט ה' \") ואין אנו ראויים עדיין לכך. \u0003וכי מאחר שמדת הדין מעכבת\u0004 ואיננו ראויים לגאולה, אם כן \u0003אנו למה מחכין\u0004 בכל יום שיבוא? כדי \u0003לקבל שכר\u0004 על הצפיה עצמה, \u0003שנאמר: \"אשרי כל חוכי לו\"\u0004 (ישעיה ל, יח).","אגב הזכרת פסוק זה \u0003אמר אביי: לא פחות עלמא מתלתין ושיתא צדיקי דמקבלי אפי\u0004 \u0005[אין העולם פחות משלושים וששה צדיקים שמקבלים\u0006 את \u0005פני]\u0006 ה\u0003שכינה בכל דרא\u0004 \u0005[דור],\u0006 \u0003שנאמר: \"אשרי כל חוכי לו\", \"לו\" בגימטריא תלתין ושיתא הוו\u0004 \u0005[שלושים ושש הם].\u0006 ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003ו\u0004הרי \u0003אמר רבא: דרא דקמי קודשא בריך הוא תמני סרי אלפי פרסא הואי\u0004 \u0005[שורה\u0006 של צדיקים \u0005שלפני הקדוש ברוך הוא שמונה עשר אלף פרסות היא]\u0006 \u0003שנאמר\u0004 בעיר ה' שלעתיד לבוא: \u0003\"סביב שמנה עשר אלף\u0004 ושם העיר מיום ה' שמה\u0003\"\u0004 (יחזקאל מח, לה) ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 המספר הקטן הוא של צדיקים \u0003דמסתכלי\u0004 \u0005[שמסתכלים]\u0006 \u0003באיספקלריא המאירה,\u0004 שכביכול רואים את כבוד ה' במראה בהירה, ורואים היטב והם מועטים מאד. \u0003הא דמסתכלי\u0004 \u0005[זו,\u0006 המרובים, הם \u0005שמסתכלים]\u0006 \u0003באיספקלריא שאינה מאירה.\u0004","ושואלים: \u0003ומי נפישי כולי האי\u0004 \u0005[וכי מרובים כל כך]\u0006 אלה המסתכלים באספקלריא מאירה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003חזקיה אמר ר' ירמיה משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: ראיתי בני עלייה,\u0004 כלומר, גדולי הצדיקים הזוכים למעלה עליונה \u0003והן מועטין\u0004 מאד, \u0003אם אלף הם\u0004 — \u0003אני ובני מהם, אם מאה הם\u0004 — \u0003אני ובני מהם, אם שנים הם\u0004 — \u0003אני ובני הם.\u0004 ומשמע שייתכן שיש רק שנים בכל העולם!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא דעיילי בבר\u0004 \u0005[זה,\u0006 המנין הגדול, הוא של \u0005הנכנסים ברשות],\u0006 שאין מעלתם גבוהה כל כך, וכדי להכנס צריכים כאילו לקבל רשות מן המלאכים, \u0003הא, דעיילי\u0004 \u0005[זה, שנכנסים]\u0006 \u0003בלא בר\u0004 \u0005[רשות]\u0006 כר' שמעון בן יוחאי ובנו שאין דבר בכל העולם נעול בפניהם.","ועוד לענין הקץ \u0003אמר רב: כלו כל הקיצין\u0004 שחישבו \u0003ואין הדבר תלוי אלא בתשובה ומעשים טובים,\u0004 שכאשר יחזרו ישראל בתשובה — יגאלו. \u0003ושמואל אמר: דיו לאבל שיעמוד באבלו,\u0004 כלומר, אפילו בלא תשובה יגאלו, כי בכך שישראל מצטערים בצער הגלות ראויים הם בשל כך לגאולה. ומעירים: מחלוקת זו היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 באותו ענין. ששנינו, \u0003ר' אליעזר אומר: אם ישראל עושין תשובה\u0004 — \u0003נגאלין, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין נגאלין. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע:\u0004 וכי \u0003אם אין עושין תשובה\u0004 מעצמם \u0003אין נגאלין?! אלא הקדוש ברוך הוא מעמיד להן מלך שגזרותיו קשות כהמן, וישראל עושין תשובה\u0004 בעל כורחם \u0003ומחזירן למוטב.\u0004","\u0003תניא אידך\u0004 \u0005[שנוייה\u0006 ברייתא \u0005אחרת],\u0006 \u0003ר' אליעזר אומר: אם ישראל עושין תשובה\u0004 — \u0003נגאלין, שנאמר: \"שובו בנים שובבים ארפה משובתיכם\"\u0004 (ירמיה ג, כב) \u0003אמר לו ר' יהושע: והלא כבר נאמר \"\u0004כי כה אמר ה' \u0003חנם נמכרתם ולא בכסף תגאלו\"\u0004 (ישעיה נב, ג), וכך יש להבין \u0003\"חנם נמכרתם\"\u0004 — \u0003ב\u0004של \u0003עבודה זרה\u0004 הקרוייה \"חינם\" שהיא חטא שאין בו צידוק, \u0003\"ולא בכסף תגאלו\"\u0004 — \u0003לא בתשובה ומעשים טובים,\u0004 אלא ברצון ה'.","\u0003אמר לו ר' אליעזר לר' יהושע: והלא כבר נאמר \"שובו אלי ואשובה אליכם\"\u0004 (מלאכי ג, ז)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע: והלא כבר נאמר \"כי אנכי בעלתי בכם ולקחתי אתכם אחד מעיר ושנים ממשפחה והבאתי אתכם ציון\"\u0004 (ירמיה ג, יד) בלא כל תנאי!","\u0003אמר לו ר' אליעזר: והלא כבר נאמר \"בשובה ונחת תושעון\"\u0004 (ישעיה ל, טו), ו\"שובה\" לשון תשובה! \u0003אמר לו ר' יהושע לר' אליעזר: והלא כבר נאמר \"כה אמר ה' גאל ישראל קדושו לבזה\u0004 \u0003נפש למתעב גוי לעבד משלים\u0004"]]};
